SELECT 'moj-all-verified-judgments-review-002-chunk-063' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"a35e88cd-61e2-56c3-844b-971354eaf9fe","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج وتعاطي -قات -استغالل االبن يف الترويج - شهادة شاهد -قرينة تكذب إنكاره -اإلدانة -التعزير بالسجن والغرامة واملنع من السفر ومصادرة اجلوال .","document_number":"3441850","case_number":"344288","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف وباهلل التوفيق وصلى اهلل وسلم على نبينا محمد","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/19","year":"1434","subject":"مخدرات -ترويج وتعاطي -قات -استغالل االبن يف الترويج - شهادة شاهد -قرينة تكذب إنكاره -اإلدانة -التعزير بالسجن والغرامة واملنع من السفر ومصادرة اجلوال .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 3441850 :‬تاريخه‪1434/02/19:‬ه‬\n                      ‫رقم الدعوى‪344288:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34191328‬تاريخه‪1434/4/17 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬ترويــج وتعاطــي ‪ -‬قــات ‪ -‬اســتغالل االبــن يف الترويــج ‪-‬‬\n‫شــهادة شــاهد ‪ -‬قرينــة تكــذب إنــكاره ‪ -‬اإلدانــة ‪ -‬التعزيــر بالســجن‬\n                     ‫والغرامــة واملنــع مــن الســفر ومصــادرة اجلــوال ‪.‬‬\n\n\n\n\n               ‫‪ -1‬املادة (‪ )3‬من القرار الوزاري رقم(‪ )11‬يف ‪1374/2/1‬هـ ‪.‬‬\n‫‪ -2‬الفقــرة الثانيــة مــن املــادة (‪ )3‬مــن نظــام مكافحة املخــدرات واملؤثرات‬\n                                                                      ‫العقلية‪.‬‬\n‫‪ -3‬الفقــرة (‪-2‬د) مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخدرات واملؤثرات‬\n                                                                      ‫العقلية‪.‬‬\n‫‪ -4‬الفقــرة األولــى مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات‬\n                                                       ‫واملؤثــرات العقليــة‪.‬‬\n‫‪ -5‬الفقــرة األولــى مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات‬\n                                                       ‫واملؤثــرات العقليــة‪.‬‬\n‫‪ -6‬الفقــرة األولــى مــن املــادة (‪ )6‬مــن نظــام مكافحــة املخــدرات واملؤثرات‬\n                                                                      ‫العقلية‪.‬‬\n‫‪ -7‬تعميــم وزيــر العــدل رقــم‪/13‬ت‪ 2832/‬يف ‪1427/2/14‬ه املبنــي علــى‬\n            ‫برقيــة وزيــر الداخليــة رقــم‪ 1/5/7565/2‬يف ‪1427/2/5‬ه ـ ‪.‬‬\n\n\n\n                                                                                   ‫‪190‬‬\n\f      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بترويــج القــات بقصــد البيــع‬\n      ‫وتعاطــي لنوعــه والتغريــر بابنــه وجعلــه وســيلة للترويــج وطلــب إثبــات مــا‬\n      ‫أســند إليــه واحلكــم عليــه بعقوبــة الســجن والغرامــة واملنــع مــن الســفر‬\n      ‫وتعزيــره لقــاء قيامــه بالتغريــر بابنــه وجعلــه وســيلة للترويــج ومصــادرة‬\n      ‫اجلوال املستخدم يف الترويج وإسقاط الشريحة ‪ ،‬حيث مت التنسيق بني‬\n      ‫املصــدر واملدعــى عليــه لشــراء القــات منــه فطلــب مــن املصــدر احلضــور‬\n      ‫ملنزلــه وأن ابنــه الصغيــر ســوف يســلمه القــات وعنــد احلضــور إلــى املنــزل‬\n      ‫خــرج ابــن املدعــى عليــه وســلم املصــدر القــات واســتلم املبلــغ ومت القبــض‬\n      ‫عليــه ومبداهمــة املنــزل وتفتيشــه عثــر علــى املدعــى عليــه كمــا عثــر‬\n      ‫علــى نبــات يشــبه أن يكــون قــات ‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي‬\n      ‫إيجابيــة العينــة املضبوطــة لنبــات القــات احملظــور‪ ،‬وأقــر املدعــى عليــه‬\n      ‫بحيــازة القــات وارســال ابنــه لتســليم القــات وتعاطيــه لــه وأنكــر الترويــج‬\n      ‫والبيــع ‪ ،‬وملــا كانــت بينــة املدعــي العــام شــهادة الشــهود ‪،‬وبنــاء علــى مــا‬\n      ‫تقــدم حكمــت احملكمــة بســجنه ســنتني وتغرميــه عشــرة آالف ريــال‬\n      ‫ومصــادرة هاتفــه اجلــوال وإيــداع ثمنــه لــدى اجلهــة املختصــة مــع إســقاط‬\n      ‫الشــريحة ومنعــه مــن الســفر وقنــع املدعــى عليــه باحلكــم واعتــرض‬\n      ‫‪،‬وصــدق احلكــم مــن محكمة‬     ‫املدعــي العــام مكتفيـ ًا بالئحــة الدعــوى ُ‬\n                                                                            ‫االســتئناف‪.‬‬\n\n\n\n\n‫‪191‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي أنــا‬\n‫‪ .....‬القاضــي باحملكمــة اجلزائيــة بالدمــام بنــاء علــى املعاملــة الــواردة مــن‬\n‫هيئــة التحقيــق واالدعــاء العــام واملقيــدة لــدى احملكمة برقــم ‪3418637‬‬\n‫وتاريــخ ‪1434/1/4‬ه ـ واحملالــة لنــا مــن فضيلة رئيــس احملكمة اجلزائية‬\n‫بالدمــام برقــم ‪ 344288‬وتاريــخ ‪1434/1/4‬ه ـ افتتحــت اجللســة يف يــوم‬\n‫األربعــاء ‪1434/1/28‬ه ـ الســاعة احلاديــة عشــرة والنصــف وفيهــا قــدم‬\n‫املدعــي العــام ‪.....‬دعــواه ونصهــا اآلتــي‪ :‬بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة‬\n‫االدعــاء العــام لفــرع املنطقــة الشــرقية أدعــي علــى‪..... /‬مجهــول الهويــة‬\n‫مبوجــب البطاقــة البديلــة رقــم ‪.....‬حيــث إنــه بتاريــخ ‪1433/11/27‬ه ـ‬\n‫ورود بــاغ لشــعبة مكافحــة املخــدرات مــن أحــد املصــادر الســرية‬\n‫مبعلومــات مفادهــا عــن وجــود املدعــى عليــه يســكن حــي ‪.....‬بالدمــام‬\n‫ويقــوم بترويــج القــات املخــدر ويســتخدم اجلــوال رقــم ‪.....‬عليــه فقــد‬\n‫اســتعد املصــدر بالشــراء منــه واإلطاحــة بــه باجلــرم املشــهود عليــه مت‬\n‫مقابلــة املصــدر ومتكينــه مــن االتصــال علــى املدعــى عليــه علــى هاتفــه‬\n‫وطلــب حزمــة قــات مببلــغ ثالثمائــة ريــال فوافــق املدعــى عليــه وقــال‬\n‫للمصــدر بأنــه ســوف يرســل لــه ولــده الصغيــر لكــي يســلمه احلزمــة‬\n‫وطلــب منــه أن يحضــر إلــى منزلــه وبنــاء علــى مــا ذكــر مت تكليــف أحــد‬\n‫أفــراد الضبــط اجلنائــي مرافقــة املصــدر وتزويدهــم مببلــغ حكومــي‬\n‫مرقــم واالنتظــار عنــد إحــدى البنايــات وبعــد مــرور حوالــي خمــس دقائــق‬\n‫نــزل شــخص صغيــر الســن وتقابــل مــع املصــدر ومرافقــه وقــام بتســليمهم‬\n‫كيــس بداخلــه حزمــة قــات بلــغ وزنهــا (‪ )229‬جــرام وهــي الكميــة‬\n\n                                                                                        ‫‪192‬‬\n\f      ‫املروجــة وقــام باســتالم املبلــغ احلكومــي منهــم وبعدهــا مت متابعــة ابــن‬\n      ‫املــروج للقبــض علــى والــده الــذي كان متواجــد باملنــزل ولكــون االبــن‬\n      ‫متلبــس باجلــرم واســتنادا للمــادة الثالثــة واألربعــون مــن نظــام اإلجــراءات‬\n      ‫اجلزائيــة وباصطحــاب املفتشــة النســائية مت القبــض علــى االبــن داخــل‬\n      ‫املنــزل ومت مداهمــة املنــزل حيــث عثــر علــى والــده داخل املنزل وبتفتيشــه‬\n      ‫شــخصيا لــم يعثــر بحوزتــه علــى أي شــيء مــن املمنوعــات إال أنــه عثــر‬\n      ‫معــه علــى جــوال نــوع اســود اللــون يحمــل الرقــم املصنعــي (‪ ).....‬حيــث‬\n      ‫أتضــح أنــه نفــس الرقــم الــذي مت التنســيق عليــه وبتفتيــش املنــزل عثــر يف‬\n      ‫الثالجــة بداخــل املطبــخ علــى عــدد (‪ )29‬حزمــة يشــتبه أن تكــون القــات‬\n      ‫احملظــور بلــغ إجمالــي وزنهــا جميعــا (‪ )6.100‬جــرام ومبناقشــته أنكــر‬\n      ‫يف بدايــة األمــر إال أنــه أعتــرف الحقــا بأنــه قــد قــام بإرســال ابنــه الــذي‬\n      ‫يدعــى ‪.....‬لتســليم القــات إلــى املصــدر دون معرفة االبــن مبا قام بتوصيله‬\n      ‫وأخــذ عليــه أمــام الفرقــة إقــرار بذلــك مــع العلــم أنــه عثــر علــى املبلــغ‬\n      ‫احلكومــي مــع االبــن قبــل تســليمه لوالــده ومت إطــاق ســراح االبــن يف‬\n      ‫احلــال بعــد إقــرار والــده بترويجــه للقــات دون علــم ابنــه وقــد أثبــت التقرير‬\n      ‫الكيمــاوي الشــرعي رقــم (‪ ).....‬وتاريــخ ‪1433/12/5‬ه ـ ايجابيــة‬\n      ‫العينــات املضبوطــة واملروجــة لنبــات القــات احملظــور واملــدرج علــى‬\n      ‫الفقــرة رقــم (‪ )5‬مــن اجلــدول رقــم (‪ )4‬مــن نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة وباســتجواب املدعــى عليــه أقــر بأنــه قــام بترويــج‬\n      ‫حزمــة مــن القــات حيــث قــام بإرســال ابنــه الصغيــر الــذي يبلــغ مــن العمــر‬\n      ‫(‪ )12‬ســنة وطلــب منــه تســليم هــذه احلزمــة لشــخص ثــم مت القبــض عليــه‬\n      ‫كمــا ضبــط يف منزلــه علــى (‪ )29‬تســعة وعشــرون حزمــه مــن القــات‬\n      ‫وهــي عائــدة لــه لقصــد االســتخدام كمــا أقــر بأنــه تعاطــى القــات‬\n\n\n‫‪193‬‬\n\f‫وكان ذلــك قبــل القبــض عليــه بأســبوع وانتهــى التحقيــق إلــى توجيــه‬\n‫االتهــام للمدعــى عليــه بترويــج مــا وزنــه (‪ )229‬مائتــان وتســعة وعشــرون‬\n‫جرام ـ ًا و حيــازة (‪ )29‬تســعة وعشــرين حزمــة بلــغ إجمالــي وزنهــا‬\n‫(‪ )6.100‬ســتة كيلــو ومائــة جــرام مــن القــات املخــدر بقصــد البيــع و‬\n‫تعاطــي لنوعــه والتغريــر بأبنــه وجعلــه وســيلة للترويــج ‪:‬وذلــك لألدلــة‬\n‫والقرائــن التاليــة‪ -1 :‬مــا جــاء يف اقــراره مبحضــر االســتجواب املنــوه‬\n‫عنــه واملرفــق علــى اللفــات رقــم (‪ -2 )15-14-2‬مــا جــاء يف محاضــر‬\n‫البــاغ واالتصــال والقبــض والتفتيــش واملدونــة علــى اللفــات رقــم (‪-13‬‬\n‫‪ )2-4-12‬مــن ملــف ضبــط اجــراءات االســتدالل ‪ -3‬مــا جــاء يف التقريــر‬\n‫الكيماوي الشــرعي املشــار اليه واملرفق على اللفة رقم (‪ )20‬وبالبحث‬\n‫عــن ســوابقه لــم يعثــر لــه أي ســابقة وحيــث إن مــا أقــدم عليــه املذكــور‬\n‫وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محـ ّـرم ومعاقــب عليــه شــرع ًا‬\n‫أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه مبــا يلــي‪ -1 :‬بعقوبــة الســجن‬\n‫والغرامــة واملنــع مــن الســفر الــواردة باملــادة الثالثــة مــن القــرار رقــم‬\n‫(‪ )2057‬وتاريــخ ‪1404/5/26‬ه ـ ووفق ـ ًا للقــرار الــوزاري رقــم (‪)11‬‬\n‫الصــادر بتاريــخ ‪1374/2/1‬ه ـ لقــاء قيامــه بترويــج القــات وبحيازتــه‬\n‫بقصــد البيــع وقيامــه وتعاطيــه لنوعــه ‪ -2‬بعقوبــة تعزيريــة تزجــره وتــردع‬\n‫غيــره لقــاء قيامــه بالتغريــر بابنــه الصغيــر وجعلــه وســيلة للترويــج‬\n‫‪-3‬مصــادرة الهاتــف اجلــوال العائــد للمدعــى عليــه والــذي مــن نــوع أســود‬\n‫والــذي يحمــل الرقــم املصنعــي رقــم (‪ ).....‬ويحمــل رقــم االتصــال (‪).....‬‬\n‫الســتخدامه يف الترويــج وفقــا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )53‬مــن‬\n‫نظــام مكافحــة املخــدرات مــع املطالبــة بإســقاط شــريحة الهاتــف‬\n‫النقــال وعــدم صرفهــا لنفــس املدعــى عليــه وفقــا لتعميــم ســمو وزيــر‬\n\n\n                                                                                     ‫‪194‬‬\n\f      ‫الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1429/2/10-9‬ه ـ هكــذا ادعــى‬\n      ‫ا مــا ذكــره املدعــي‬   ‫وبعــرض الدعــوى علــى املدعــى عليــه أجــاب قائ ـ ً‬\n      ‫العــام مــن قيامــي بحيــازة القــات وإرســال ابنــي لتســليم القــات للمصــدر‬\n      ‫فذلــك صحيــح ولــم أقصــد البيــع علــى املصــدر وإمنــا إعــادة بعــض القــات‬\n      ‫لــه حيــث إنــه ســيتلف وهــو مــن باعــه علــي ولــم أتفــق معــه عندمــا تصــل‬\n      ‫بــي علــى بيــع القــات ولــم أتفــاوض معــه علــى البيع هكذا أجــاب وبعرض‬\n      ‫ذلــك علــى املدعــي العــام قــال مــا ذكــره املدعــى عليــه غيــر صحيــح‬\n      ‫والصحيــح مــا ذكــرت يف دعــواي مــن قيامــه بالتفــاوض علــى البيــع‬\n      ‫هكــذا أجــاب ثــم جــرى ســؤال املدعــي العــام البينــة علــى دعــواه فقــال‬\n      ‫أطلــب مهلــة إلحضارهــا ويف جلســة أخــرى حضــر الطرفــان ثــم جــرى‬\n      ‫ســؤال املدعــي العــام عــن البينــة علــى دعــواه فقــال إننــي أحضــرت معــي‬\n      ‫الشــاهد‪.....‬وأطلب ســماع مــا لديــه وبســؤال الشــاهد عــن شــهادته قــال‪:‬‬\n      ‫( أشــهد بــاهلل أننــي كنــت مــع املصــدر وأنــه مت متكــن املصــدر مــن‬\n      ‫االتصــال علــى جــوال املدعــى عليــه وطلــب منــه حزمــة قــات مببلــغ‬\n      ‫ثالثمائــة ريــال فوافــق املدعــى عليــه وقــال للمصــدر بأنــه ســوف يرســل لــه‬\n      ‫ولــده الصغيــر لكــي يســلمه احلزمــة وطلــب منــه أن يحضــر إلــى منزلــه‬\n      ‫وبنــاء علــى ذلــك مت تزويــد املصــدر باملبلــغ احلكومــي املرقــم وقــدره‬\n      ‫ثالثمائــة ريــال ثــم قمنــا باالنتظــار عنــد إحــدى البنايــات وبعــد مــرور‬\n      ‫حوالــي خمــس دقائــق نــزل طفــل صغيــر الســن وتقابــل مــع املصــدر وقــام‬\n      ‫بتســليمه كيــس بداخلــه حزمــة قــات بلــغ وزنهــا (‪ )229‬جــرام وهــي‬\n      ‫الكميــة املروجــة وقــام باســتالم املبلــغ احلكومــي منــه) هكــذا شــهد‬\n      ‫وبعــرض الشــاهد وشــهادته علــى املدعــى عليــه قــال أمــا الشــاهد فــا‬\n      ‫أعرفــه وشــهادته غيــر صحيحــة هكــذا أجــاب ثــم جــرى ســؤال املدعــي‬\n\n\n‫‪195‬‬\n\f‫العــام هــل لديــه زيــادة بينــة فقــال ال توجــد لــدي بينــة ســوى مــا قدمتــه‬\n‫وأطلــب الرجــوع إلــى املعاملــة ثــم جــرى ســؤال املدعــي العــام املزكــن‬\n‫للشــاهد فقــال إننــي أحضرتهمــا معــي وهمــا ‪.....‬و‪.....‬وبســؤالهما عــن‬\n‫الشــاهد قــال كل واحــد منهمــا مبفــرده( إننــي أعــرف الشــاهد ‪ .....‬وهــو‬\n‫عــدل ثقــة مقبــول الشــهادة يف الديــن واملــروءة) هكــذا شــهدا ثــم جــرى‬\n‫رفــع اجللســة لالطــاع علــى املعاملــة ويف يــوم األربعــاء ‪1434/02/13‬ه ـ‬\n‫افتتحــت اجللســة وفيهــا حضــر الطرفــان ثــم جــرى ســؤال املدعــى عليــه‬\n‫ا نعــم قــد تعاطيــت القــات احملظور‬   ‫هــل قــام بتعاطــي القــات فأجــاب قائـ ً‬\n‫وحيازتــي لــه ألجــل التعاطــي فقــط هكــذا أجــاب ثــم الرجــوع إلــى‬\n‫املعاملــة فوجــدت علــى لفــة رقــم (‪ )1‬ملــف ضبــط إجــراءات ص (‪)13-12‬‬\n‫محضــر واقعــة قبــض وضبــط وتفتيــش املتضمــن طبــق مــا ذكــر املدعــي‬\n‫العــام يف دعــواه كمــا وجــدت علــى لفــة رقــم (‪ )18-16‬كــرت بصمــات‬\n‫املدعــى عليــه املتضمــن وجــود ســابقة حيــازة واســتعمال قــات كمــا‬\n‫وجــدت علــى لفــة رقــم (‪ )20‬تقرير كيماوي شــرعي رقــم (‪ ).....‬املتضمن‬\n‫ـاء علــى مــا تقــدم‬\n                  ‫ايجابيــة العينــات املرســلة لنبــات القــات احملظــور فبنـ ً‬\n‫مــن دعــوى املدعــي العــام وإجابــة املدعــى عليــه وإقــراره بحيــازة وتعاطــي‬\n‫القــات والتغريــر بابنــه جلعلــه وســيلة لترويــج القــات ومبــا أن املدعــى عليــه‬\n‫ـاء علــى شــهادة الشــاهد املعــدل التعديــل الشــرعي‬    ‫أنكــر الترويــج وبنـ ً‬\n‫ونظــر ًا لوجــود كميــة كبيــرة مــن القــات يف منــزل املدعــى عليــه وهــذه‬\n‫قرينــة تؤيــد دعــوى املدعــي العــام ومــا دفــع بــه املدعــى عليــه مــن كونــه‬\n‫لــم يبــع القــات وإمنــا قــام بــرده عــذر غيــر مقبــول الســيما مــع وجــود كميــة‬\n‫أكبــر منهــا يف منزلــه وهــذه قرينــة تــدل علــى كذبــه وقيامــه بالترويــج‬\n‫ـاء علــى املــادة رقــم (‪ )3‬مــن القــرار الــوزاري رقــم (‪ )11‬الصــادر بتاريــخ‬\n                                                                                ‫وبنـ ً‬\n\n                                                                                          ‫‪196‬‬\n\f      ‫ـاء علــى الفقــرة (‪ )2‬مــن املــادة رقــم (‪ )3‬والفقــرة ( ‪-2‬د‬\n                                                                   ‫‪1374/2/1‬ه ـ وبنـ ً‬\n      ‫) مــن املــادة رقــم (‪ )38‬والفقــرة (‪ )1‬مــن املــادة (‪ )53‬والفقــرة (‪ )1‬مــن‬\n      ‫املــادة رقــم (‪ )56‬والفقــرة (‪ )1‬مــن املــادة رقــم (‪ )62‬مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة وبنــاء علــى تعميــم معالــي وزيــر العــدل رقــم‬\n      ‫‪/13‬ت‪ 2832/‬يف ‪1427/2/14‬ه ـ املبنــي علــى برقيــة صاحــب الســمو‬\n      ‫امللكــي وزيــر الداخليــة رقــم ‪2/7565/5/1‬ش وتاريــخ ‪1427/2/5‬ه ـ‬\n      ‫املتضمــن أن القــات مــن أخــف املــواد املخــدرة ويراعــى عنــد تطبيــق‬\n      ‫العقوبــة مــا نصــت عليــه املــادة (‪ )60‬مــن نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة لــذا كلــه فقــد ثبــت لــدي إدانــة املدعــى عليــه ‪.....‬‬\n      ‫بترويــج مــا وزنــه (‪ )229‬مائتــان وتســعة وعشــرون جرامـ ًا مــن نبــات القات‬\n      ‫احملظــور كمــا ثبــت لــدي حيازتــه لعــدد (‪ )29‬تســعة وعشــرين حزمــة‬\n      ‫قــات بلــغ إجمالــي وزنهــا (‪ )6.100‬ســتة كيلــو ومائــة جرام ـ ًا مــن نبــات‬\n      ‫القــات املخــدر بقصــد البيــع والتعاطــي كمــا ثبــت لــدي تعاطيــه للقــات‬\n      ‫احملظــور والتغريــر بابنــه وجعلــه وســيلة للترويــج وقــررت عقابــه علــى‬\n      ‫ـداء مــن تاريــخ إيقافــه وتغرميــه‬\n                                       ‫ذلــك مبــا يلــي‪ :‬أوالً‪ :‬ســجنه ملــدة ســنتني ابتـ ً‬\n      ‫عشــرة آالف ريــال تدفــع للجهــة املختصــة وذلــك لقــاء بيعــه وحيازتــه‬\n      ‫وتعاطيــه لنبــات القــات احملظــور والتغريــر بابنــه الصغيــر بجعلــه وســيلة‬\n      ‫للترويج‪ .‬ثانياً‪ :‬منعه من الســفر ملدة ســنتني تبدأ بعد انتهاء محكوميته‬\n      ‫املقــررة يف البنــد أوالً‪ .‬ثالث ـاً‪ :‬مصــادرة اجلــوال املوصــوف يف الدعــوى‬\n      ‫وإيداعــه أو ثمنــه لــدى اجلهــة املختصــة مــع إســقاط الشــريحة وعــدم‬\n      ‫صرفهــا لــه‪ .‬وبــكل مــا تقــدم حكمــت وبعــرض احلكــم علــى الطرفــن‬\n      ‫قــرر املدعــى عليــه القناعــة باحلكــم وأمــا املدعــي العــام فقــرر عــدم‬\n      ‫القناعــة باحلكــم وطلــب االســتئناف مكتفي ـ ًا بالئحــة الدعــوى العامــة‬\n\n\n‫‪197‬‬\n\f‫وأمــرت برفــع املعاملــة إلــى محكمــة االســتئناف وبــاهلل التوفيــق وصلــى‬\n                     ‫اهلل وسلم على نبينا محمد‪ .‬حرر يف ‪1434/02/19‬هـ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة القائــم بعمــل رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام‬\n‫برقــم ‪ 34/18637‬وتاريــخ ‪1434/2/24‬ه ـ املقيــدة لــدى احملكمــة برقم‬\n‫‪/34/510538‬ج‪ 1‬وتاريــخ ‪1434/2/30‬ه ـ املرفــق بهــا القــرار الصــادر‬\n‫مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪.....‬املســجل برقــم ‪3441850‬‬\n‫وتاريــخ ‪1434/2/19‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضد‪...../‬مجهــول‬\n‫الهويــة يف قضيــة قــات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو‬\n‫مــدون ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n‫قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                ‫وآلــه وصحبــه وســلم حــرر يف ‪1434/4/17‬هــ‪.‬‬\n\n\n\n\n                                                                                         ‫‪198‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":190,"source_page_end":198,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"be715999a494ee539a77f097ee61783db0cadf7eee55a7c0bfd6e4eb0f10a526","normalized_text_hash":"2da84c3447cd0d5a93ebc2a6ca8d666d37795f7bbae077ed7dfd0527d3d71447","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p190-3441850"},{"id":"6d9ed042-f765-591e-9bec-ae59eae10403","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة -وجود سوابق على املتهم قضى فيها باإلدانة -ندم وتوبة -رد دعوى القتل تعزير ا -غرامة وسجن وجلد -مصادرة ومنع من السفر.","document_number":"3381914","case_number":"3259536","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/02/14","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة -وجود سوابق على املتهم قضى فيها باإلدانة -ندم وتوبة -رد دعوى القتل تعزير ا -غرامة وسجن وجلد -مصادرة ومنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3381914 :‬تاريخه‪1433/02/14 :‬هـ‬\n                           ‫رقم الدعوى ‪3259536:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 3411657‬تاريخه‪1434/1/13 :‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة ‪ -‬وجــود ســوابق علــى املتهــم قضى‬\n       ‫فيهــا باإلدانــة ‪ -‬نــدم وتوبــة ‪ -‬رد دعــوى القتــل تعزيــر ًا ‪ -‬غرامــة وســجن‬\n                                             ‫وجلــد ‪ -‬مصــادرة ومنــع مــن الســفر‪.‬‬\n\n\n\n\n       ‫املــادة (‪ ، )3‬واملــادة (‪ ، )37‬واملــادة (‪ )60‬مــن نظــام مكافحــة املخــدرات‬\n                                                            ‫واﻤﻟﺆﺛﺮات اﻟﻌﻘﻠﻴﺔ‪.‬‬\n\n\n\n\n       ‫أقــام املدعــي العــام دعــواه ضــد املدعــى عليــه طالب ـ ًا إثبــات مــا أســند‬\n       ‫إليــه وفقــا للمــادة ‪ 3‬مــن نظــام اإلجــراءات اجلزائيــة واملــادة ‪ 64‬مــن نظــام‬\n       ‫مكافحــة املخــدرات واملؤثــرات العقليــة وذلــك لقيامــه ببيــع احلبــوب‬\n                    ‫احملظــورة بقصــد الترويــج وتعاطيــه لهــا واحلكــم عليــه بـ ــ‪:‬‬\n       ‫‪ .1‬عقوبــة القتــل املنصــوص عليهــا بالفقــرة اخلامســة مــن البنــد األول مــن‬\n                          ‫املــادة ‪ 37‬مــع مراعــاة مــا تقضــى بــه املــادة ‪ 62‬مــن النظــام‪.‬‬\n       ‫‪ .2‬مصــادرة الســيارة املســتخدمة يف عمليــة الترويــج وفــق الفقــرة (‪ )1‬مــن‬\n                                                                     ‫املــادة ‪ 53‬مــن النظــام‪.‬‬\n       ‫ومبواجهــة املدعــى عليــه أقــر بــكل مــا ورد بالئحــة االدعــاء وأبــدى ندمه‬\n                                                           ‫وتوبتــه عــن األفعــال املذكورة‪.‬‬\n\n‫‪199‬‬\n\f         ‫وبعد أن أطلعت احملكمة على كامل األوراق والتقارير قررت‪:‬‬\n‫‪ .1‬ثبــوت ترويــج املدعــى عليــه وبيــع ‪ 24‬حبــة محظــورة للمــرة الثانيــة‬\n‫والنــزول عــن عقوبــة القتــل لندمــه وتوبتــه وحكمــت بتعزيــره بالســجن ‪5‬‬\n‫ســنوات وجلــده خمســمائة جلــدة وتغرميــه مائــة ألــف ريــال ســعودي ومنعــه‬\n‫مــن الســفر خمــس ســنوات ومصــادرة الســيارة واجلــوال ‪،‬وقنــع املدعــى‬\n‫عليــه واعتــرض املدعــى العــام ‪،‬وجــرى تصديــق احلكــم مــن محكمــة‬\n‫االســتئناف بعــد زيــادة الســجن إلــى ثمــان ســنوات واجللــد إلــى ثمامنائــة‬\n                                     ‫جلــدة ومنعــه مــن الســفر ثمــان ســنوات‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلدينــا نحــن القضــاة باحملكمــة العامــة بالدمــام‬\n‫‪...........‬القائــم بعمــل املكتــب القضائــي ‪ ......................‬وبنــاء علــى‬\n‫املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالدمــام برقــم‬\n‫‪ ...........‬وتاريخ ‪1432/2/28‬هـ واملقيدة باحملكمة برقم ‪ ...........‬وتاريخ‬\n‫‪1432/2/28‬هـ ففي يوم األحد املوافق ‪1432/5/20‬هـ افتتحت اجللسة‬\n‫بخصــوص دعــوى املدعــي العــام ‪ ............ /‬ضــد ‪ ............ /‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...........‬ونصهــا بصفتــي مدعي ـ ًا‬\n‫عامـ ًا بدائــرة االدعــاء العــام لفــرع الهيئــة باملنطقــة الشــرقية أدعــي علــى‬\n‫املذكــور أعــاه حيــث إنــه باالطــاع علــى محاضــر االنتقــال والترقيــم‬\n‫والقبــض والتفتيــش املعــدة مــن قبــل رجــال الضبــط اجلنائــي مبكافحــة‬\n‫املخــدرات تبــن أنــه يف يــوم االثنــن املوافق‪1431/10/18‬ه ـ و بنــاء علــى‬\n‫بــاغ احــد املصــادر عــن وجــود شــخص يدعــى (‪ )...........‬يقــوم بترويــج‬\n‫احلبــوب احملظــورة فتــم بالتنســيق مــع املصــدر لشــراء كميــة مــن احلبــوب‬\n\n                                                                                       ‫‪200‬‬\n\f      ‫احملظــورة و مت متكــن املصــدر مــن االتصــال علــى هاتــف املتهــم و طلــب‬\n      ‫شــراء خمســة وعشــرين حبــة فأجابه املتهــم‪ .........../‬بقولــه طلبك موجود‬\n      ‫ثــم اتفقــا علــى أن يتقابــا بجــوار ســوق الســمك فتم تزويــد املصدر باملبلغ‬\n      ‫املرقم و مت تفتيش املصدر وســيارته أبراء للذمة ومرافقته من قبل أحد‬\n      ‫أفــراد الفرقــة القابضــة ومتركــزت الفرقــة القابضــة يف املوقــع احملــدد‬\n      ‫وبعــد حوالــي ربــع ســاعة حضــرت ســيارة مــن نــوع (‪ ).....‬يف املوقــع احملــدد‬\n      ‫تنطبــق عليهــا نفــس املواصفــات و يقودهــا شــخص تنطبــق عليــه أيضــا‬\n      ‫نفــس املواصفــات و احتــك باملصــدر وقــام املصــدر بالركــوب معه و اخذ‬\n      ‫لفــة صغيــرة حتــت أنظــار الفرقــة القابضــة ثــم قــام بإنــزال املصــدر الــذي‬\n      ‫قــام بتســليم الفــرد املرافــق مــا عــدده (‪ )24‬أربعــة وعشــرون حبــة اثبــت‬\n      ‫التقريــر الكيمــاوي الشــرعي الصــادر مــن املركــز اإلقليمــي ملراقبــة‬\n      ‫الســموم بالشــرقية رقــم (‪ ).........‬و تاريــخ ‪1431/10/26‬ه ـ ايجابيــة عينة‬\n      ‫احلبــوب املروجــة ملــادة االمفيتامــن املــدرج باجلــدول (‪ )2‬فئــة (ب) املرفــق‬\n      ‫بنظــام مكافحــة املخــدرات ‪ .‬و بعدهــا قــام املرافــق بإعطــاء اإلشــارة‬\n      ‫الدالــة علــى امتــام عمليــة الترويــج فتمــت متابعــة املــروج مــن بعــد حتــى‬\n      ‫توقــف بإحــدى احملطــات يف حــي ‪ .....‬و متــت مداهمتــه و بتفتيشــه عثــر‬\n      ‫علــى املبلــغ املرقــم وقــدره (‪ )350‬ريــال يف جيــب ثوبــه العلــوي كامــا‬\n      ‫ومبناقشــته اعتــرف بعمليــه الترويــج وانــه يحضــر احلبــوب مــن شــخص‬\n      ‫بحــي ‪ .....‬فتــم القبــض عليــه ‪ .‬و تبــن أنــه ســبق و أن أديــن يف قضيــة‬\n      ‫ترويــج مبوجــب القــرار الشــرعي رقــم ( ‪ ) 3/84‬و تاريــخ ‪1482/5/19‬ه ـ‬\n      ‫الصــادر مــن محكمــة اجلبيــل و باســتجواب املتهــم اقــر بصحــة واقعــة‬\n      ‫القبــض عليــه مــن قبــل رجــال الضبــط اجلنائــي مبكافحــة املخــدرات‬\n      ‫إثــر بيعــه للحبــوب احملظــورة و اســتالم مقابلهــا ثالثمائــة وخمســون ريــال‬\n\n\n‫‪201‬‬\n\f‫بقصــد الكســب املــادي وتعاطيــه للحبــوب احملظــورة و اخــر مــرة كانت‬\n‫قبــل القبــض عليــه بشــهر مضيفــا ان الســيارة التــي قــام بالترويــج عليهــا‬\n‫تعــود ملكيتهــا لــه و قــد انتهــى التحقيــق إلــى اتهــام املدعــى عليــه باآلتــي‬\n‫‪ -1:‬بيعــه مــا عــدده (‪ )24‬اربعــة وعشــرون حبــة مــن مــادة االمفيتامــن‬\n‫املنبهــة واحملظــورة بقصــد االجتــار للمــرة الثانيــة ‪ -2- .‬تعاطيــه احلبــوب‬\n‫احملظــورة‪ .‬وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬اعترافــه املــدون علــى‬\n‫الصفحــات رقــم (‪ )5-4‬مــن ملــف التحقيــق املرفــق علــى اللفــة رقــم‬\n‫(‪ )1‬واللفــات رقــم (‪ -2 )16-14‬محاضــر البــاغ والترقيــم واالنتقــال‬\n‫والقبــض والتفتيــش املنــوه عنهــا املدونــة علــى الصفحــات رقــم (‪ )3-1‬مــن‬\n‫امللــف املرفــق علــى لفــة (‪ -3- . )1‬التقريــر الكيمــاوي الشــرعي املنــوه‬\n‫عنــه واملرفــق علــى اللفــة رقــم (‪ . )19‬وحيــث إن مــا أقــدم عليــه املدعــى‬\n‫عليــه و هــو بكامــل أهليــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه و‬\n‫مجــرم نظامــا مبوجــب نظــام مكافحــة املخــدرات واملؤثــرات العقليــة يف‬\n‫عقوبــة األصليــة والتكميليــة أطلــب مــا يلــي‪ -:‬أوال‪ :‬إثبــات مــا أســند إليــه‬\n‫وفقــا للمــادة (‪ )3‬مــن نظــام االجــراءات اجلزائيــة و املــادة (‪ )64‬مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة و احلكــم عليــه باآلتــي‪-1:‬‬\n‫بعقوبــة القتــل املنصــوص عليهــا بالفقــرة (اخلامســة) مــن البنــد (االول)‬\n‫مــن املــادة (‪ )37‬مــع مراعــاة مــا تقضــي بــه املــادة (‪ )62‬مــن النظــام ‪-2‬‬\n‫مصــادرة الســيارة التــي مــن نوع ‪ .....‬رقم اللوحــة (‪ )...........‬صنع (‪2004‬م)‬\n‫الســتخدامها مــن قبلــه يف عمليــة الترويــج وفــق الفقــرة (‪ )1‬مــن املــادة‬\n‫(‪ )53‬مــن النظــام‪-3- .‬مصــادرة الهاتــف اجلــوال نــوع ‪ ....‬رقــم م املصنعــي‬\n‫(‪ ).........‬الســتخدامه مــن قبلــه يف إمتــام عمليــة الترويــج وفــق الفقــرة (‪)1‬‬\n‫مــن املــادة (‪ )53‬مــن النظــام وبعــرض دعــوى املدعــي العــام علــى املدعــى‬\n\n\n                                                                                        ‫‪202‬‬\n\f      ‫عليــه أجــاب قائــا كل مــا ورديف الئحــة الدعــوى كلــه صحيــح جملــة‬\n      ‫وتفصيــا وأنــا تائــب إلــى اهلل ونــادم علــى مــا فعلتــه وأقــر أن لــدي ســابقه‬\n      ‫ترويــج مخــدرات حكــم علــي فيهــا هــذه إجابتــي ثــم يف جلســه أخــرى‬\n      ‫لدينــا نحــن القضــاة بهــذه احملكمــة ‪...........‬و ‪...........‬و‪...........‬القائــم‬\n      ‫بعمــل املكتــب القضائــي الثالــث حضــر املدعــي العــام ‪...........‬الســعودي‬\n      ‫بالطاقــة رقــم ‪ ...........‬وحضــر حلضــوره املدعــى عليــه ‪...........‬فتــم الرجــوع‬\n      ‫الــى لفــات املعاملــة ومنهــا محضــر الضبــط اخلــاص بإجــراءات قضيــة‬\n      ‫مخــدرات حتمــل الرقــم ‪ ...........‬وقــد جــاء يف الصفحــة رقــم ‪ 2‬محضــر‬\n      ‫ترقــم مبلــغ ثالثمائــة وخمســن ريــال كمــا جــاء يف الصفحــة رقــم ‪3‬‬\n      ‫محضــر انتقــال وشــراء وقبــض وتفتيــش مــؤرخ ‪1431/10/18‬هـ ـ‬\n      ‫ومضمونــه ورود معلومــات لــدى املديريــة العامــة ملكافحــة املخدرات عن‬\n      ‫قيــام املدعــى عليــه بترويــج احلبــوب املخــدرة وأن أحــد املصــادر اتصــل بــه‬\n      ‫لشــراء خمســه وعشــرين حبــه فأجابــه بوجــود احلبــوب لديــه ثــم اتفــق معــه‬\n      ‫علــى مــكان لتســليمها لــه وانــه يف املــكان احملــدد حضــر املدعــى عليــه‬\n      ‫بســيارة ‪ .....‬حتمــل لوحــة برقــم ‪...........‬فركــب معــه املصــدر بعــد أن مت‬\n      ‫تفتيشــه قبــل ذلــك وســلمه لفــه مبــرأى مــن الفرقــة ثــم عــاد املصــدر وســلم‬\n      ‫للفرقــة اربعــة وعشــرين حبــه وهــي الكميــة املروجــة ثــم متــت متابعــة‬\n      ‫املدعــى عليــه ويف احــدى احملطــات علــى شــارع ‪.........‬مت القبــض عليــه‬\n      ‫وبتفتيشــه عثــر علــى املبلــغ احلكومــي املرقــم يف جيــب ثوبــه العلــوي ولــم‬\n      ‫يعثــر علــى شــيء مــن املمنوعــات معــه او يف ســيارته وقد أقــر املدعى عليه‬\n      ‫يف الصفحــة الرابعــة مــن احملضــر املذكــور أنــه يأخــذ احلبــوب مــن آخــر‬\n      ‫ويبيعهــا بنفــس الثمــن ليتحصــل علــى حبــه أو حبتــن ليتعاطاهــا كمــا‬\n      ‫وجــد يف الصفحــة رقــم ‪ 6‬محضــر حتريــر للحبــوب التــي روجهــا املدعــى‬\n\n\n‫‪203‬‬\n\f‫عليــه كمــا مت االطــاع علــى خطــاب مديــر املركــز اإلقليمــي ملراقبــة‬\n‫الســموم باملنطقــة الشــرقية ويحمــل الرقــم ‪...........‬يف ‪1431/10/26‬ه ـ‬\n‫ومضمونــه ثبــوت إيجابيــة احلبــوب املرســلة ملــادة االمفيتامــن املــدرج يف‬\n‫اجلــدول رقــم ‪ 2‬فئــة ب مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫كمــا مت االطــاع علــى كــرت الســوابق اخلــاص باملدعــى عليــه فتبــن‬\n‫أن عليــه ثــاث ســوابق هــي اســتعمال مخــدرات وحيــازة واســتعمال‬\n‫مخــدرات والثالثــة حيــازة واســتعمال وترويــج مخــدرات كمــا مت‬\n‫االطــاع علــى صــورة القــرار رقــم ‪ ...........‬يف ‪1428/5/19‬ه ـ الصــادر‬\n‫مــن محكمــة اجلبيــل العامــة وختــم علــى الصــورة بختــم طبــق األصــل‬\n‫ومضمــون القــرار املذكــور إدانــة املدعــى عليــه بترويــج عشــر حبــات مــن‬\n‫حبــوب الكبتاجــون احملظــورة عــن طريــق البيــع كمــا وجــد مــن ضمــن‬\n‫لفــات املعاملــة صــورة رخصــة الســير وتثبــت أن الســيارة املســتخدمة‬\n‫ملــك للمدعــى عليــه كمــا جــاء يف صحيفــة الدعــوى يــأن املدعــى عليــه‬\n‫مــن مواليــد ‪1389/5/20‬ه ـ ومســجون بســبب هــذه القضيــة مــن تاريــخ‬\n‫القبــض عليــه ‪1431/10/18‬ه ـ فبنــاء علــى مــا تقــدم وألن املدعــى عليــه‬\n‫أقــر مبــا نســب إليــه يف هــذه الدعــوى مــن ترويجــه ألربعــة وعشــرين حبــه‬\n‫كبتاجــون وأبــدى ندمــه علــى ذلــك الفعــل وملــا يف املخــدرات مــن أضــرار‬\n‫بالغــه وشــرور مســتطيره علــى الفــرد واملجتمــع ولذلــك حرمتهــا الشــريعة‬\n‫املطهــرة وحرمــت تعاطيهــا وترويجهــا األنظمــة الشــرعية ولتكــرار‬\n‫ســوابق املدعى عليه ومنها ســابقة ترويج وملا جاء يف املواد الثالثة واملادة‬\n‫الســابعة والثالثــن مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫ومضمونهــا حتــرمي مــن قــام بترويــج احلبــوب املخــدرة بالبيــع وعقوبــة مــن‬\n‫قــام بذلــك إذا كان الترويــج للمــرة الثانــي بالقتــل تعزيــرا وجــواز النــزول‬\n\n\n                                                                                     ‫‪204‬‬\n\f      ‫عــن عقوبــة القتــل وأســباب تقدرهــا احملكمــة إلــى عقوبــة الســجن التــي‬\n      ‫ال تقــل عــن خمســة عشــر ســنه وباجللــد الــذي ال يزيــد علــى خمســن جلــده‬\n      ‫وبالغرامــة التــي ال تقــل عــن مائــة ألــف ريــال وملــا جــاء يف املــادة الســتني‬\n      ‫مــن النظــام املذكــور مــن أن للمحكمــة ألســباب معتبــره النــزول عــن‬\n      ‫احلــد األدنــى يف هــذه القضيــة وملــا بــدر منهــم أثنــاء محاكمتــه مــن إظهــار‬\n      ‫للنــدم لــكل ذلــك تقــرر مــا يلــي ‪ :‬أوال‪ :‬ثبــت لدينــا ترويــج املدعــى عليــه‬\n      ‫بيــع أربعــه وعشــرين حبــة كبتاجــون وهــذا ترويــج للمــرة الثانيــة ‪ .‬ثانيــا‪:‬‬\n      ‫قررنــا النــزول عــن عقوبــة القتــل ملــا ذكــر يف حيثيــات احلكــم وحكمنــا‬\n      ‫بتعزيــره عوضــا عــن ذلــك بســجنه خمــس ســنوات حتســب منها املــدة التي‬\n      ‫أوقــف فيهــا بســبب هــذه القضيــة وجلــده خمســمائة جلــده علــى عشــر‬\n      ‫دفعــات متســاوية قــدر الدفعــة خمســون جلــده وبــن كل دفعــه والتــي‬\n      ‫تليهــا مــدة شــهر ومصــادرة ســيارته وجوالــه املذكوريــن الســتخدامه‬\n      ‫لهمــا يف هــذه اجلرميــة وتغرميــه مائــة ألــف ريــال ومنعــه مــن الســفر إلــى‬\n      ‫خــارج اململكــة بعــد انتهــاء محكوميتــه مــدة خمــس ســنوات وبعــرض‬\n      ‫احلكــم علــى الطرفــن اعتــرض عليــه املدعــي العــام أمــا املدعــى عليــه‬\n      ‫فقــرر قناعتــه باحلكــم فأفهــم املدعــي العــام بأنــه ســيتم تزويــده بصــوره‬\n      ‫مــن احلكــم لتقــدمي اعتراضــه عليــه خــال ثالثــة أيــام وأن عليــه أن يقــدم‬\n      ‫الئحتــه االعتراضيــة يف مــده ال تتجــاوز ثالثــن هــي مــدة االعتــراض‬\n      ‫كمــا أفهــم بأنــه إن مضــت هــذه املــدة دون أن يقــدم الئحتــه االعتراضيــة‬\n      ‫فســيتم رفــع املعاملــة إلــى محكمــة االســتئناف كاملتبــع بــدون الئحــة‬\n      ‫ففهــم ذلــك ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                           ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1433/2/14‬هــ‪.‬‬\n      ‫تابــع دعــوى املدعــي العــام ضــد ‪...........‬ثــم انــه يف هــذا اليــوم الثالثــاء‬\n\n\n‫‪205‬‬\n\f‫املوافــق ‪1433/10/17‬ه ـ حضــر املدعــي العــام ‪...........‬وحضــر حلضــوره‬\n‫املدعــى عليــه ‪ ...........‬ويف هــذه اجللســة مت اســتعراض قــرار محكمــة‬\n‫االستئناف باملنطقة الشرقية رقم ‪ ...........‬يف ‪1433/6/10‬هـ ومضمونه‬\n‫أن ماحكــم بــه علــى املدعــى عليــه قليــل وذلــك لتعــدد ســوابقه ولعــدم‬\n‫تبريــر أســباب معتبــرة للنــزول لتوافــق مــا جــاء يف املــادة الســتني مــن نظــام‬\n‫مكافحــة املخــدرات وعليــه وملــا ذكــر أصحــاب الفضيلــة يف قرارهــم‬\n‫املذكــور فــإن ســبب النــزول عــن احلــد األدنــى هــو مــا بــدر مــن املدعــى‬\n‫عليــه أثنــاء محاكمتــه مــن النــدم ولقلــة احلبــوب التــي ثبــت ترويجهــا‬\n‫ولتوجيــه أصحــاب الفضيلــة فقــد قررنــا زيــادة الســجن احملكــوم بــه‬\n‫عليــه ثــاث ســنوات واجللــد ثالثمائــة جلــدة مفرقــة وزيــادة مــدة منعــه‬\n‫مــن الســفر إلــى خــارج اململكــة مــدة ثــاث ســنني ولذلــك قررنــا تعديــل‬\n‫الفقــرة الثانيــة مــن احلكــم ليكــون نصهــا كالتالــي ‪.‬ثانيــا قررنــا‬\n‫النــزول عــن عقوبــة القتــل ملــا ذكــر يف حيثيــات احلكــم وحكمنــا‬\n‫بتعزيــره عوضــا عــن ذلــك بســجنه ثمــان ســنوات حتســب منهــا املــدة التــي‬\n‫أوقــف فيهــا بســبب هــذه القضيــة وجلــد ثمامنائــة جلــده علــى ســت عشــرة‬\n‫دفعــة متســاوية قــدر الدفعــة خمســون جلــدة وبــن كل منهــا والتــي تليهــا‬\n‫مــدة شــهر ومصــادرة ســيارته وجوالــه املذكوريــن الســتخدامه لهمــا‬\n‫يف هــذه اجلرميــة وتغرميــه مائــة ألــف ريــال ومنعــه مــن الســفر إلــى خــارج‬\n‫اململكــة بعــد انتهــاء محكوميتــه مــدة ثمــان ســنوات وبعــرض احلكــم‬\n‫علــى الطرفــن ذكــر املدعــي العــام أنــه ال يــزال علــى معارضتــه امــا‬\n‫املدعــى عليــه فقــرر قناعتــه باحلكــم‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/10/17‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعنــا نحــن ق ــضاة الدائـ ــرة اجلزائـي ــة‬\n\n\n                                                                                         ‫‪206‬‬\n\f      ‫اخلماسـي ــة األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبدينــة الدمــام‬\n      ‫برقــم ‪ ...........‬وتاريــخ ‪1433/11/2‬ه ـ واملقيــدة لــدى احملكمــة برقــم‬\n      ‫‪...........‬وتاريــخ ‪1433/11/10‬ه ـ املرفــق بهــا القــرار الشــرعي ذو الرقــم‬\n      ‫‪ ...........‬والتاريــخ ‪1433/2/14‬ه ـ الصــادر مــن أصحــاب الفضيلــة‬\n      ‫القضــاة باحملكمــة الشــيخ‪ .........../‬والشيخ‪.........../‬والشــيخ‪.........../‬‬\n      ‫اخلــاص بدعــوى‪ /‬املدعــي العــام ضــد‪ .........../‬يف قضيــة مخــدرات وقــد‬\n      ‫تضمــن القــرار حكــم أصحــاب الفضيلــة مبــا هــو مــدون ومفصــل فيــه ‪.‬‬\n      ‫وحيــث ســبق دراســة القــرار وصــورة ضبطــه وأوراق املعاملــة وباالطــاع‬\n      ‫علــى مــا أجــاب بــه أصحــاب الفضيلــة علــى قرارنــا رقــم ‪...........‬وتاريــخ‬\n      ‫‪1433/6/10‬ه ـ قررنــا املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر‪.‬‬\n      ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف‬\n                                                                ‫‪ 1434/11/13‬هـ ـ ـ ـ ‪.‬‬\n\n\n\n\n‫‪207‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":199,"source_page_end":207,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"52ac9d2d2c2ae8e7ef8af296dda5695b399704227bfbcbd90808835bc8b8e25d","normalized_text_hash":"dea1beb0360da0ca3a985a4ba6e5351dcff36d0eaaaa4f932e75b7281e285a10","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p199-3381914"},{"id":"ee9565af-5100-5196-886b-f7ef481324a4","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج املخدرات -ترويج الهيروين املخدر -إقرار - التعزير بالسجن و اجللد و الغرامة و اإلبعاد عن الباد و مصادره الهاتف اجلوال وإلغاء الشريحة .","document_number":"34265704","case_number":"3300695","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/11","year":"1434","subject":"مخدرات -ترويج املخدرات -ترويج الهيروين املخدر -إقرار - التعزير بالسجن و اجللد و الغرامة و اإلبعاد عن الباد و مصادره الهاتف اجلوال وإلغاء الشريحة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34265704 :‬تاريخه ‪1434/07/11 :‬هـ‬\n                     ‫رقم الدعوى ‪3300695 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34318256‬تاريخه‪1434/9/14 :‬هـ‬\n\n\n ‫مخــدرات ‪ -‬ترويــج املخــدرات ‪ -‬ترويــج الهيرويــن املخــدر ‪ -‬إقــرار ‪-‬‬\n ‫التعزيــر بالســجن و اجللــد و الغرامــة و اإلبعــاد عــن البــاد و مصــادره‬\n                                      ‫الهاتــف اجلــوال وإلغــاء الشــريحة ‪.‬‬\n\n\n\n\n         ‫‪ .1‬املادة ( ‪ ) 38‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n         ‫‪ .2‬املادة ( ‪ ) 53‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n         ‫‪ .3‬املادة ( ‪ ) 56‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n         ‫‪ .4‬املادة ( ‪ ) 60‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n         ‫‪ .5‬تعميم سمو وزير الداخلية رقم ( ‪ )9778‬يف ‪1428/2/10-9‬هـ‬\n\n\n\n\n ‫ادعــى املدعــي العــام علــى املدعــى عليــه ببيــع جــرام واحــد يحتــوي علــى‬\n ‫مــادة امليثامفيتامــن ‪ ،‬طلــب املدعــي العــام تعزيــر املدعــى عليــه بالســجن‬\n ‫واجللــد والغرامــة واإلبعــاد ومصــادرة الهاتــف اجلــوال وإلغــاء الشــريحة‬\n ‫وذلــك تطبيقـ ًا للمــواد أرقــام (‪ )56( ، )53( ، )38‬مــن نظــام مكافحــة‬\n ‫املخــدرات واملؤثــرات العقليــة ‪ ،‬حيــث توافــرت معلومــات لــدى اجلهــات‬\n ‫األمنيــة عــن قيــام املدعــى عليــه بترويــج الهيرويــن املخــدر‪ ،‬مت االتفــاق‬\n ‫معــه علــى شــراء الهرويــن مببلــغ ألــف ريــال واتفــق علــى املــكان‪،‬‬\n\n                                                                                    ‫‪208‬‬\n\f      ‫وحضــر املدعــى عليــه‪ ،‬وركــب الســيارة ‪ ،‬وأخــرج مــن جيبــه كيــس‬\n      ‫نايلــون بداخلــه مــادة بيضــاء اللــون‪ ،‬يشــتبه أن تكــون مخــدره بلــغ وزنهــا‬\n      ‫جرامــا واحـ ًـدا‪ ،‬فتــم القبــض عليــه قبــل تســلمه املبلــغ املرقــم‪ ،‬وقــد أثبــت‬\n                                                                                       ‫ً‬\n      ‫التقريــر الكيميائــي إيجابيــة العينــة علــى مــادة امليثامفيتامــن املؤثــرة‬\n      ‫عقليــا وأقــر املدعــى عليــه مبــا جــاء يف دعــوى املدعــي العــام وظهــر لناظر‬ ‫ً‬\n      ‫القضيــة ندمــه وتوبتــه وعــدم وجــود ســوابق مســجله بحقــه إضافــة إلــى‬\n      ‫قلــة الكميــة ‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة بإدانــة املدعــى‬\n      ‫عليــه مبــا نســب إليــه بتعزيــر املدعــى عليــه بالســجن و اجللــد واإلبعــاد عــن‬\n      ‫البــاد ومصــادرة اجلــوال وإلغــاء الشــريحة‪ ،‬و النــزول عــن احلــد األدنــى‬\n      ‫للعقوبــة ملقتضــى املــادة ( ‪ )60‬مــن نظــام مكافحــة املخــدرات و املؤثــرات‬\n      ‫العقليــة ‪ ،‬قنــع املدعــى عليــه باحلكــم ‪ ،‬وقــرر املدعــي العــام اعتراضــه‬\n             ‫علــى احلكــم بالئحــة‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..............‬القاضــي يف احملكمــة‬\n      ‫اجلزائيــة مبحافظــة جــدة وبنــاء علــى املعاملــة احملالة لنا مــن فضيلة رئيس‬\n      ‫احملكمــة اجلزائيــة مبحافظــة جــدة برقــم وتاريــخ ‪1434/07/01‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم وتاريــخ ‪1434/06/28‬ه ـ ففــي يــوم األثنــن‬\n      ‫املوافق‪1434/07/10‬ه ـ افتتحــت اجللســة الســاعة ‪ 11 : 00‬وفيهــا حضــر‬\n      ‫املدعــي العــام ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫ومبوجــب التكليــف رقــم ه ـ وتاريــخ ‪1430/12/29‬هـ وادعــى على ‪........‬‬\n      ‫(‪ )30‬عامـ ًا هنــدي اجلنسي ــة مبوجــب البطاقــة البديلــة رقــم ‪ ........‬بتاريــخ‬\n      ‫‪1434/5/4‬ه ـ الصــادرة مــن مكافحــة املخــدرات مبحافظة جدة عاطل‬\n\n‫‪209‬‬\n\f‫موقــوف بالســجن العــام مبحافظــة جــدة مبوجــب أمــر متديــد التوقيــف‬\n‫رقــم ‪ .......‬وتاريــخ ‪1434/5/7‬ه ـ اســتناد ًا للقــرار الــوزاري رقــم (‪)1900‬‬\n‫وتاريــخ ‪1428/7/9‬ه ـ املبنــي علــى املــادة (‪ ) 112‬مــن نظــام اإلجــراءات‬\n‫ا يف دعــواه‪ :‬إنــه بتاريــخ ‪1434/5/4‬ه ـ مت القبــض علــى‬          ‫اجلزائيــة قائ ـ ً‬\n‫املدعــى عليــه مــن قبــل أمــن املهمــات والواجبــات اخلاصــة بشــرطة منطقــة‬\n‫مكــة املكرمــة بعــد توافــر معلومــات عــن ترويجــه للهيرويــن املخــدر‬\n‫ويتواجــد علــى جــوال ومت االتفــاق معــه علــى شــراء الهيرويــن مببلــغ‬\n‫(‪ )1000‬ريــال وباالنتقــال للموقــع املتفــق عليــه حضــر املدعــى عليــه‬\n‫وركــب ســيارة الفــرد وأخــرج مــن جيبــه كيــس نايلــون بداخلــه مــادة‬\n‫بيضــاء يشــتبه أن تكــون مخــدرة بلــغ وزنهــا (‪ )1‬جــرام فتــم القبــض عليــه‬\n‫قبــل تســلمه املبلــغ املرقــم وقــد أثبــت التقريــر الكيميائــي الشــرعي رقــم‬\n‫(‪/1667‬ك ش م) لعــام ‪1434‬ه ـ احتــواء الكميــة املضبوطــة واملرســلة‬\n‫للتحليــل علــى مــادة امليثامفيتامــن املؤثــرة عقليـ ًا املدرجــة باجلــدول رقــم‬\n‫(‪ )2‬فئــة (ب) امللحقــة بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫وباســتجواب املدعــى عليــه اعتــرف مبــا نســب إليــه وأفــاد بأنــه ســلم‬\n‫الكميــة املضبوطــة ألحــد األشــخاص مقابــل خمســن ريــا ًال وأنهــا تعــود‬\n‫لشــخص هنــدي يدعــى (‪ ).....‬ال يعــرف مــكان تواجــده وانتهــى التحقيــق‬\n‫معــه إلــى توجيــه االتهــام إليــه ببيــع جــرام واحــد يحتــوي علــى مــادة‬\n‫امليثامفيتامــن املؤثــرة عقلي ـ ًا بقصــد االجتــار اســتناد ًا للفقــرة (‪ )2‬مــن‬\n‫املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وذلــك‬\n‫لألدلــة والقرائــن املرصــودة يف الئحــة الدعــوى وباالطــاع علــى ســوابقه‬\n‫لــم يعثــر لــه علــى ســوابق جنائيــة مســجلة وحيــث إن مــا أقــدم عليــه‬\n‫املدعــى عليــه فعــل محــرم شــرع ًا ومجــرم نظام ـ ًا طبق ـ ًا للمــادة الثالثــة‬\n\n\n                                                                                        ‫‪210‬‬\n\f      ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n      ‫امللكــي رقــم م‪ 39/‬وتاريــخ ‪1426/7/8‬ه ـ واملعاقــب عليهــا اســتناد ًا‬\n      ‫للمــواد (‪ )59،38‬مــع مراعــاة مــا ورد باملــادة (‪ )62‬مــن ذات النظــام‬\n      ‫لــذا أطلــب إثبــات إدانتــه مبــا نســب إليــه وملعاقبتــه بالعقوبــات األصليــة‬\n      ‫والتكميليــة التاليــة‪ :‬أوالً‪ /‬بالســجن واجللــد والغرامــة اســتناد ًا للفقــرة‬\n      ‫(‪ )1‬مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات املشــار إليــه ثاني ـاً‪/‬‬\n      ‫مصــادرة جهــازه اجلــوال املضبــوط معــه الســتخدامه يف اجلرميــة اســتناد ًا‬\n      ‫للفقــرة (‪ )1‬مــن املــادة (‪ )53‬مــن نظــام وإلغــاء اخلدمــة عــن الشــريحة لســوء‬\n      ‫اســتخدامه وعــدم صرفهــا لــه اســتناد ًا لتعميــم ســمو وزيــر الداخليــة رقــم‬\n      ‫(‪ )9778‬يف ‪1428/2/10-9‬ه ـ ثالث ـاً‪ /‬إبعــاده عــن اململكــة بعــد تنفيــذ‬\n      ‫عقوبتــه وعــدم الســماح لــه بالعــودة إليهــا وفق ـ ًا للفقــرة (‪ )2‬مــن املــادة‬\n      ‫(‪ )56‬مــن النظــام املشــار إليــه هكــذا ادعــى املدعــي العــام وبعرضــه على‬\n      ‫ا وهــو يعــرف العربيــة‪ :‬مــا ذكــره املدعــي العــام‬   ‫املدعــى عليــه أجــاب قائـ ً‬\n      ‫مــن قيامــي ببيــع جــرام واحــد يحتــوي علــى مــادة امليثامفيتامــن املؤثــرة‬\n      ‫عقلي ـ ًا بقصــد االجتــار صحيــح وأنــا نــادم علــى مــا بــدر منــي وتائــب هلل‬\n      ‫ثــم جــرى منــي االطــاع علــى أوراق املعاملــة وملــف التحقيــق ومــا ورد‬\n      ‫يف اعترافــه املــدون مبلــف االســتجواب لفــة (‪ )18-16‬ومــا ورد مبحضــر‬\n      ‫الضبــط لفــة ( ‪ ) 2-1‬ومــا ورد بالتقريــر الكيميائــي الشــرعي رقــم ()‬\n      ‫لعــام ‪1434‬ه ـ لفــة (‪ )19‬املتضمــن احتــواء الكميــة املضبوطــة واملرســلة‬\n      ‫للتحليــل علــى مــادة امليثامفيتامــن املؤثــرة عقلي ـ ًا فبنــاء علــى مــا تقــدم‬\n      ‫مــن الدعــوى واإلجابــة واإلقــرار وملــا ظهــر لــي مــن ندمــه وتوبتــه وعــدم‬\n      ‫وجــود ســوابق مســجلة عليــه ونظــر ًا لقلــة الكميــة فقــد ثبــت لــدي إدانــة‬\n      ‫املدعــى عليــه مبــا أســند إليــه وحكمــت عليــه مبــا يلــي‪-1 :‬ســجنه ملــدة‬\n\n\n‫‪211‬‬\n\f‫ســنة يحتســب منهــا مــدة إيقافــه علــى ذمــة هــذه القضيــة وجلــده خمســن‬\n‫جلــدة مكــررة ثمانــي مــرات بــن كل مــرة وأخــرى مــا ال يقــل عــن‬\n‫أســبوع وتغرميــه ( ‪ ) 1000‬ريــال اســتناد ًا للمــادة ( ‪ ) 60 ،38‬مــن نظــام‬\n‫مكافحــة املخــدرات ‪ -2‬إبعــاده خلــارج اململكــة بعــد االنتهــاء مــن تنفيــذ‬\n‫عقوبتــه وعــدم الســماح لــه بالعــودة إليهــا ومنعــه مــن دخولهــا اســتناد ًا‬\n‫للمــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات املشــار إليــه ‪ -3‬مصــادرة‬\n‫جهــازه اجلــوال املضبــوط معــه الســتخدامه يف اجلرميــة اســتناد ًا للفقــرة (‪)1‬‬\n‫مــن املــادة (‪ )53‬مــن نظــام وإلغــاء اخلدمــة عــن الشــريحة لســوء اســتخدامه‬\n‫وعــدم صرفهــا لــه اســتناد ًا لتعميــم ســمو وزيــر الداخليــة رقــم (‪)9778‬‬\n‫يف ‪1428/2/10-9‬ه ـ وبجميــع ذلــك حكمــت وبعرضــه علــى املدعــى‬\n‫عليــه قــرر قناعتــه باحلكــم فيمــا طلــب املدعــي العــام رفعهــا حملكمــة‬\n‫االســتئناف بالئحــة تقــدم خــال ثالثــن يومـ ًا مــن تاريــخ تســجيل القــرار‬\n‫وإال ســقط حقــه يف االعتــراض ورفعــت دون الئحــة وعليــه جــرى التوقيــع‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                               ‫‪1434/07/10‬ه ـ‬\n           ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد ‪-:‬‬\n‫فقــد جــرى منــا نحــن قضــاة االســتئناف بالدائــرة اجلزائيــة السادســة‬\n‫مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة جــرى منــا اإلطــاع‬\n‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة‬\n‫جــدة برقــم (‪ )....‬وتاريــخ (‪1434/9/6‬هــ) املرفــق بهــا القــرار الصــادر‬\n‫مــن فضيلــة الشــيخ‪ /‬القاضــي باحملكمــة اجلزائيــة بجــدة برقــم (‪)....‬‬\n‫وتاريــخ (‪1434/7/11‬هــ) املتضمــن دعــوى املدعــي العــام ضــد‪....../‬‬\n‫هنــدي اجلنســية املتهــم يف مخــدرات‪ ،‬احملكــوم فيــه مبــا دون باطنــه‪،‬‬\n\n\n                                                                                     ‫‪212‬‬\n\f      ‫وبدراســة القــرار وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة‬\n      ‫علــى احلكــم‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                 ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪213‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":208,"source_page_end":213,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2e87e2c45b101d8c08c764bdda1181efd2f5572a5e9437a6d8d3698cd8976e92","normalized_text_hash":"e3482445e50a3cfb42c171515d88cb2c185ad2644677601652a199776ae14345","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p208-34265704"},{"id":"8e2a0c50-9ddd-51d2-b2be-b8917cf0a8a4","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر -ترويج اخلمر املسكر -حيازة املسكر -حيازة احلشيش املخدر -حيازة عدد من حبوب محظورة -شرب املسكر -تعاطي احلشيش -تعاطي احلبوب احملظورة - احليازة بقصد التعاطي والترويج -إقامة حد املسكر -التعزير بالسجن واجللد والغرامة واملنع من السفر واملصادرة وإعادة املبلغ","document_number":"3432371","case_number":"3319993","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/9","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر -ترويج اخلمر املسكر -حيازة املسكر -حيازة احلشيش املخدر -حيازة عدد من حبوب محظورة -شرب املسكر -تعاطي احلشيش -تعاطي احلبوب احملظورة - احليازة بقصد التعاطي والترويج -إقامة حد املسكر -التعزير بالسجن واجللد والغرامة واملنع من السفر واملصادرة وإعادة املبلغ","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 3432371 :‬تاريخه ‪1434/02/9 :‬هـ‬\n                   ‫رقم الدعوى ‪3319993 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34191153‬تاريخه‪1434/4/22 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬ترويــج احلشــيش املخــدر ‪ -‬ترويــج اخلمــر املســكر ‪ -‬حيــازة‬\n‫املســكر ‪ -‬حيــازة احلشــيش املخــدر ‪-‬حيــازة عــدد مــن حبــوب محظــورة‬\n‫‪ -‬شــرب املســكر ‪ -‬تعاطــي احلشــيش ‪ -‬تعاطــي احلبــوب احملظــورة ‪-‬‬\n‫احليــازة بقصــد التعاطــي والترويــج ‪ -‬إقامــة حــد املســكر ‪ -‬التعزيــر‬\n‫بالســجن واجللــد والغرامــة واملنــع مــن الســفر واملصــادرة وإعــادة املبلــغ‬\n                                                                      ‫احلكومــي‪.‬‬\n\n\n\n‫‪ -1‬الفقــرة (‪ )2‬مــن املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                    ‫العقليــة‪.‬‬\n‫‪ -2‬الفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                    ‫العقليــة‪.‬‬\n        ‫‪ -3‬الفقرة (‪ )53‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n‫‪ -4‬الفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                    ‫العقليــة‪.‬‬\n‫‪ -5‬الفقــرة (‪ )1‬مــن املــادة (‪ )62‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                    ‫العقليــة‪.‬‬\n\n\n\n\n                                                                                   ‫‪214‬‬\n\f      ‫ادعــى املدعــي العــام علــى املدعــى عليــه ببيــع قطعــة مــن احلشــيش بقصــد‬\n      ‫االجتــار وترويجــه لزجاجتــن مــن املســكر وحيــازة خمــس زجاجــات مــن‬\n      ‫املســكر وعــدد ثــاث قطــع مــن احلشــيش وعــدد (‪ )37‬حبــة مــن حبــوب‬\n      ‫الكلوفازيبــام احملظــورة بقصــد التعاطــي والترويــج وشــرب املســكر‬\n      ‫وتعاطــي احلشــيش واحلبــوب احملظــورة حيــث ورد بــاغ لشــعبة مكافحــة‬\n      ‫املخــدرات مــن أحــد مصادرهــا عــن قيــام املتهــم بترويــج مــادة احلشــيش‬\n      ‫املخــدر ومت متكــن املصــدر مــن االتصــال علــى املدعــى عليــه وطلــب‬\n      ‫منــه قطعــه مــن احلشــيش وحضــر املتهــم بســيارته ملنــزل املصــدر وســلمه‬\n      ‫القطعــة واســتلم منــه املبلــغ املرقــم وأعطــى املصــدر الفرقــة القابضــة نــوع‬\n      ‫الســيارة ورقــم اللوحــة ‪ ،‬مت التعميــم علــى املتهــم وســيارته ‪ ،‬ورد بــاغ مــن‬\n      ‫أحــد املصــادر الســرية عــن وجــود شــخص يقــوم بترويــج احلشــيش املخــدر‬\n      ‫والشــراب املســكر وحبــوب الــروش ومت رصــد املنــزل وشــوهد املتهــم‬\n      ‫وهــو يقــود الســيارة املذكــورة وقــام بتســليم أحــد األشــخاص زجاجتــن‬\n      ‫يشــتبه أن تكــون مــن شــراب املســكر ومت اســتيقافه بتفتيــش الســيارة‬\n      ‫وجــد بهــا خمــس زجاجــات مســكر وبعــد أخــذ األذن مت الدخــول ملنــزل‬\n      ‫املدعــى عليــه وبتفتيــش غرفتــه عثــر علــى قطــع مــن احلشــيش وحبــوب‬\n      ‫الــروش ومبلــغ مالــي بجانبهــا وأربــع زجاجــات بهــا خمــر‪ .‬طلــب املدعــي‬\n      ‫العــام إثبــات إدانــة املدعــى عليــه مبــا هــو منســوب إليــه وأقــر املدعــى عليه‬\n      ‫مبــا نســب إليــه ‪ ،‬كمــا أنكــر اســتخدام ســيارته يف الترويــج وأنكــر‬\n      ‫ترويــج املســكر وقــرر بــأن املبلــغ املضبــوط يف منزلــه عائــد لــه وهــو جــزء‬\n      ‫مــن راتبــه وليــس مــن ترويــج املخــدرات او املســكرات ‪ ،‬وبنــاء علــى مــا‬\n\n‫‪215‬‬\n\f‫ســبق حكمــت احملكمــة بإقامــة حــد املســكر وتعزيــر املدعــى عليــه‬\n‫بالســجن واجللــد والغرامــة ومنعــه مــن الســفر وإعــادة املبلــغ احلكومــي‬\n‫ومصــادرة الهاتــف اجلــوال وإلغــاء شــريحته وصــرف النظــر عــن طلــب‬\n‫املدعــي العــام مصــادرة ســيارة املدعــى عليــه واملبلــغ املضبــوط يف بيتــه‬\n                                 ‫وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫اجلزئيــة‬\n   ‫ّ‬       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة‬\n‫بالدمــام وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزئيــة بالدمــام برقــم ‪ ......‬وتاريــخ ‪1433/01/08‬ه ـ املقيــدة باحملكمة‬    ‫ّ‬\n‫برقم وتاريخ ‪1433/01/08‬هـ ففي يوم االثنني املوافق‪1433/01/24‬هـ‬\n‫افتتحــت اجللســة الســاعة ‪ 10 : 32‬وفيهــا قــدم املدعــي العــام ‪ ......‬دعــواه‬\n‫ا فيهــا حيــث إنــه باالطــاع علــى محضــر‬      ‫ضــد املدعــى عليــه ‪ ......‬قائ ـ ً‬\n‫بــاغ املعــد مــن قبــل شــعبة مكافحــة املخــدرات يف األحــد‬\n‫‪1432/11/11‬ه ـ تبــن ورود بــاغ مــن أحــد مصادرهــم الســرية عــن‬\n‫قيــام املتهــم بترويــج مــادة احلشــيش املخــدر ويحمــل جــوال رقــم‪)......( :‬‬\n‫وقــد أفــاد املصــدر باســتعداده التــام للشــراء منــه واإلطاحــة بــه باجلــرم‬\n‫املشــهود عليــه مت متكــن املصــدر مــن االتصــال علــى جوالــه املشــار لــه‬\n‫ولقــد طلــب املصــدر منــه يف االتصــال قطعــة حشــيش بقيمــة (‪ )200‬ريــال‬\n‫ورد عليــه املتهــم أنــه يوجــد عنــده قطعــة حشــيش مخــدر بقيمــة (‪)250‬‬\n‫ريــا ًال فأجــاب املصــدر بأنــه ســوف يشــتريها فســأله املتهــم هــل لديــه‬\n‫ســيارة لكــي يحضــر إليــه؟ فــرد عليــه املصــدر بأنــه ال توجــد لديه ســيارة‬\n‫فقــال املتهــم إنــه ال ميلــك أيضـ ًا ســيارة وطلــب منــه االنتظــار لدقائــق حيــث‬\n\n                                                                                         ‫‪216‬‬\n\f      ‫ســيتصل عليــه الحق ـ ًا وفجــأة قــام املتهــم باالتصــال علــى املصــدر وقــال‬\n      ‫لــه ‪« :‬أنــا عنــد البيــت انــزل» فتــم إعطــاء املصــدر املبلــغ احلكومــي املرقــم‬\n      ‫ـراء للذمــة ومت‬\n                     ‫وقــدره (‪ )250‬ريــال وذلــك بعــد تفتيشــه تفتيشـ ًا دقيقـ ًا إبـ ً‬\n      ‫بعــث املصــدر للمتهــم وأثنــاء تــرك الغرفــة ملراقبــة املوقــع من اجلهــة املقابلة‬\n      ‫أفــاد املصــدر بــأن املتهــم قــام بتســليمه قطعــة مــن احلشــيش املخــدر يبلــغ‬\n      ‫وزنهــا (‪ )6.9‬جــم وأنــه حتــرك علــى الفــور كمــا أفــاد املصــدر بــأن املتهــم‬\n      ‫أتــى علــى ســيارة مــن نــوع ‪ ....‬موديــل ‪1992‬م لونهــا أخضــر حتمــل لوحــة‬\n      ‫رقــم (‪ )......‬علمـ ًا بــأن املصــدر ال يعــرف موقــع بيــت املتهــم عليــه مت جمــع‬\n      ‫املعلومــات ومت التعميــم عليــه وعلــى ســيارته املذكــورة ويف يــوم الثالثــاء‬\n      ‫‪1432/11/27‬ه ـ ورد بــاغ مــن أحــد مصادرهــم الســرية مفــاده وجــود‬\n      ‫شــخص يســكن حــي ‪ ....‬بجــوار محطــة ‪ .....‬يقــوم بترويــج مــادة احلشــيش‬\n      ‫املخــدر والشــراب املســكر وحبــوب الــروش احملظــورة وقد أفــاد املصدر‬\n      ‫بأنــه علــى أمت االســتعداد بالداللــة علــى املنــزل ويف اليــوم نفســه مت رصــد‬\n      ‫املنــزل املذكــور وشــوهد شــخص يقــود ســيارة مــن نــوع ‪ .....‬أخضــر اللــون‬\n      ‫يحمــل اللوحــة رقــم (‪ )......‬وهــو يقــوم بتســليم أحــد األشــخاص قارورتــن‬\n      ‫يشــتبه أن تكــون مــن الشــراب املســكر وأثنــاء اســتيقاف الشــخص‬\n      ‫املذكــور أعــاه اتضــح أنــه املتهــم وكان االســتيقاف بعيــد ًا عــن ســيارته‬\n      ‫وبتفتيشــه شــخصي ًا لــم ُيعثــر معــه علــى أي شــيء مــن املمنوعــات وبســؤاله‬\n      ‫عــن ســيارته التــي كان يقودهــا قــام بإنكارهــا وبتفتيــش الســيارة‬\n      ‫املذكــورة أعــاه وجــد بهــا خمســة قواريــر ميــاه معدنيــة مــن نــوع ‪ ....‬ســعة‬\n      ‫‪ 500‬مــل تفــوح منهــا رائحــة املســكر يشــتبه أن تكــون مــن الشــراب‬\n      ‫املســكر وبالضغــط عليــه مبــا يحــوزه يف منزلــه الواقــع يف حــي ‪ ....‬بجــوار‬\n      ‫محطــة ‪ ....‬قــام باالعتــراف بأنــه يوجــد بهــا كميــة من الشــراب املســكر‬\n\n\n‫‪217‬‬\n\f‫يف غرفتــه باإلضافــة إلــى قطــع مــن احلشــيش املخــدر وحبــوب الــروش‬\n‫وبعــد أخــذ اإلذن الــازم واصطحــاب املفتشــة النســائية وعضــو الهيئــة مت‬\n‫الدخــول ملنزلــه وإلــى غرفتــه مباشــرة وبرفقتــه شــخصي ًا حيــث عثــر‬\n‫الوكيــل رقيــب‪ ...... :‬علــى قطعــة ســمراء اللــون بلــغ وزنهــا ( ‪ ) 71.3‬جــم‬\n‫يشــتبه أن تكــون مــن مــادة احلشــيش املخــدر وكانــت موجــودة حتــت‬\n‫املالبــس املوجــودة يف خزانــة املالبــس كمــا عثــر حتــت الســرير علــى‬\n‫علبــة دخــان بداخلــه قطعتــن ســمراء اللــون يشــتبه أن تكــون مــن مــادة‬\n‫احلشــيش املخــدر بلــغ وزنهمــا (‪ )6‬جــم كمــا عثــر علــى عــدد ســبعة‬\n‫وثالثــن حبــة بيضــاء اللــون يشــتبه أن تكــون مــن حبــوب الــروش‬\n‫احملظــورة كانــت حتــت وســادة الســرير وبجانبهــا مبلــغ مالــي وقــدره‬\n‫(‪ )1300‬ريــال بجانــب احلبــوب حتــت الوســادة كمــا عثــرت الفرقــة علــى‬\n‫عــدد أربعــة جوالــن زرقــاء اللــون مملــوءة بشــراب يشــتبه أن يكــون مــن‬\n‫الشــراب املســكر وكانــت موجــودة يف نفــس الغرفــة وقــد أثبــت التقرير‬\n‫الكيمــاوي الشــرعي رقــم (‪ )......‬وتاريــخ ‪1432/11/21‬ه ـ الصــادر مــن‬\n‫املركــز اإلقليمــي ملراقبــة الســموم باملنطقــة الشــرقية إيجابيــة عينــة‬\n‫القطعــة املروجــة ملــادة احلشــيش املخــدر املدرجــة باجلــدول األول فئــة (أ)‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وقــد أثبــت التقريــر‬\n‫الكيمــاوي الشــرعي رقــم (‪ ).....‬وتاريــخ ‪1432/12/6‬ه ـ الصــادر مــن‬\n‫املركــز اإلقليمــي ملراقبــة الســموم باملنطقــة الشــرقية مــا يلــي‪-1:‬‬\n‫إيجابيــة احتــواء عينــة قواريــر املســكر املضبوطــة يف ســيارته علــى مــادة‬\n‫الكحــول اإليثيلــي وبنســبة مســكرة‪ -2‬إيجابيــة عينــة القطعــة‬\n‫املضبوطــة يف منــزل املتهــم ملــادة احلشــيش املخــدر املدرجــة باجلــدول األول‬\n‫فئــة (أ) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ -3‬إيجابيــة‬\n\n\n                                                                                    ‫‪218‬‬\n\f      ‫عينــة القطعتــن املضبوطتــن داخــل الباكيــت الــذي ُعثــر عليــه يف منــزل‬\n      ‫املتهــم ملــادة احلشــيش املخــدر املدرجــة باجلــدول األول فئــة (أ) مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪ -4‬إيجابيــة عينــة احلبــوب‬\n      ‫املضبوطــة يف منــزل املتهــم لعقــار الكلونازيبــام املــدرج باجلــدول الثانــي‬\n      ‫فئــة (د) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ -5‬احتــواء‬\n      ‫عينــة اجلوالــن املضبوطــة يف منــزل املتهــم علــى مــادة الكحــول اإليثيلــي‬\n      ‫وبنســبة مســكرة ‪ .‬وباســتجواب املتهــم اعتــرف بحيازتــه للهاتــف اجلــوال‬\n      ‫رقــم (‪ )......‬وبعائديــة ســيارة ‪ ....‬موديــل ‪ ......‬رقــم اللوحــة (‪ )......‬وأنكــر‬\n      ‫قيامــه بترويــج احلشــيش املخــدر يف يــوم األحــد ‪1432/11/11‬ه ـ وقــد‬\n      ‫اعتــرف بحيازتــه ملــا مت ضبطــه معــه ويف منزلــه مــن شــراب مســكر‬\n      ‫وحشــيش مخــدر وحبــوب محظــورة يف يــوم الثالثــاء ‪1432/11/27‬ه ـ‬\n      ‫وذلــك بقصــد االســتعمال الشــخصي وأنكــر قيامــه يف ذلــك اليــوم‬\n      ‫ترويجــه للمســكر وأن املبلــغ املضبــوط يف منزلــه هــو املتبقــي مــن راتبــه‬\n      ‫الشــهري كمــا اعتــرف بتعاطيــه للحشــيش املخــدر والشــراب املســكر‬\n      ‫واحلبــوب احملظــورة وانتهــى التحقيــق معــه الــى اتهامــه مبــا يلــي‪ -1/‬بيــع‬\n      ‫قطعــة مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )6.9‬ســتة جــرام وتســعة مــن‬\n      ‫العشــرة مــن اجلــرام بقصــد االجتــار وترويجــه لقارورتــن مــن املســكر‪-2‬‬\n      ‫حيــازة عــدد (‪ )5‬خمســة قواريــر مــن املســكر ســعة ‪ 500‬مــل وعــدد (‪)3‬‬\n      ‫ثــاث قطــع مــن احلشــيش املخــدر بلــغ وزنهــا ( ‪ ) 77.3‬ســبعة وســبعون‬\n      ‫جرام ـ ًا وثالثــة مــن العشــرة مــن اجلــرام وعــدد (‪ )37‬ســبعة وثالثــن حبــة‬\n      ‫بيضــاء اللــون مــن عقــار الكلونازيبــام احملظــور بقصــد التعاطــي‬\n      ‫والترويــج‪ -3‬شــرب املســكر‪ -4‬تعاطــي احلشــيش املخــدر واحلبــوب‬\n      ‫احملظــورة‪ .‬وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬مــا جــاء يف أقوالــه املنــوه‬\n\n\n‫‪219‬‬\n\f‫عنهــا واملرفقــة علــى اللفــات (‪ -2) 31.30.29.17.16.15‬محاضــر‬\n‫الضبــط املنــوه عنهــا واملدونــة علــى الصفحة رقم (‪ )11‬مــن ملف التحقيق‬\n‫املرفــق لفــة (‪ )1‬والصفحتــن رقــم (‪ )12.11‬مــن ملــف التحقيــق املرفــق‬\n‫لفــة (‪-3)18‬التقاريــر الكيماويــة الشــرعية املنــوه عنهــا واملرفقــة لفــة‬\n‫(‪ )7‬واللفــة رقــم (‪ -4)32‬وجــود املبلــغ املالــي قــرب احلبــوب احملظــورة‬\n‫املضبوطــة يف منــزل املتهــم قرينــة علــى أنهــا نتــاج عمليــات الترويــج‪-5‬‬\n‫اعتــراف املتهــم بعائديــة الســيارة املســتخدمة يف الترويــج وعائديــة‬\n‫الهاتــف اجلــوال املســتخدم بالتنســيق لعمليــة الترويــج قرينــة علــى اتهامــه‬\n‫بالقيــام بعمليــة ترويــج احلشــيش املخــدر وحيــث إن مــا أقــدم عليــه املدعــى‬\n ‫عليــه ‪ -‬وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ‪ -‬فعــلٌ محــرم ومعاقـ ٌ‬\n‫ـب‬\n‫عليــه شــرع ًا ونظامـ ًا اطلــب مــا يلــي أوالً‪ :‬إثبــات إدانتــه بشــرب املســكر‬\n‫واحلكــم عليــه بحــد الســكر لقــاء ذلــك ولتعاطيــه احلشــيش املخــدر‬\n‫ثاني ـاً‪ :‬إثبــات مــا ُأســند إليــه مــن اتهــام وفق ـ ًا للفقــرة رقــم (‪ )2‬مــن املــادة‬\n‫رقــم (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم‬\n‫عليــه مبــا يلــي‪ -1:‬بعقوبــة الســجن واجللــد والغرامــة الــواردة بالفقــرة رقــم‬\n‫(‪ )1‬مــن املــادة رقــم (‪ )38‬مــن النظــام مــع مراعــاة تطبيــق الفقــرة (‪ )1‬مــن‬\n‫املــادة (‪ )62‬مــن النظــام املتضمنــة تطبيــق العقوبــة األشــد ‪ -2‬منعــه مــن‬\n‫الســفر إعمــا ًال ملقتضــى الفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )56‬مــن‬\n‫النظــام‪ -3‬مصــادرة الهاتــف اجلــوال العائــد للمذكــور ويحمــل الرقــم‬\n‫املصنعــي (‪ )......‬ومصــادرة الســيارة املســتخدمة يف اجلرميــة وهــي مــن نــوع‬\n‫‪ ....‬أخضــر اللــون يحمــل اللوحــة رقــم (‪ )......‬وحتمــل رقــم الهيــكل (‪)......‬‬\n‫وهــي مــن نــوع ‪ .....‬الســتخدامه يف اجلرميــة وفق ـ ًا للفقــرة رقــم (‪ )1‬مــن‬\n‫املــادة رقــم (‪ )53‬مــن النظــام ‪ ،‬مــع املطالبــة بإســقاط شــريحة الهاتــف‬\n\n\n                                                                                               ‫‪220‬‬\n\f      ‫النقــال وعــدم صرفهــا لنفــس املتهــم وفقــا لتعميــم ســمو وزيــر الداخليــة‬\n      ‫رقــم ( ) وتاريــخ ‪1428/2/10-9‬ه ـ ‪ -4‬املطالبــة باملبلــغ احلكومــي املرقم‬\n      ‫والــذي لــم يتــم العثــور عليــه وفــق تعميــم صاحــب الســمو امللكــي ولــي‬\n      ‫العهــد وزيــر الداخليــة رقــم ( ) وتاريــخ ‪1428/10/23‬ه ـ ثالث ـاً‪ :‬إثبــات‬\n      ‫إدانــة املتهــم بترويــج املســكر وحيازتــه بقصــد االســتعمال الشــخصي‬\n      ‫والترويــج واحلكــم عليــه بعقوبــة تعزيريــة لقــاء ذلــك رابع ـاً‪ :‬مصــادرة‬\n      ‫املبلــغ املالــي وقــدره (‪ )1300‬ريــال كونهــا نتــاج جتــارة املخــدرات‬\n      ‫واملســكرات وبــاهلل التوفيــق ويف هــذه اجللســة حضــر املدعــى عليــه ‪......‬‬\n      ‫مبوجــب بطاقــة الهويــة الوطنيــة املــدون بهــا الرقــم ‪ ......‬وبعــرض دعــوى‬\n      ‫ا ‪ :‬صحيـ ٌـح أننــي بعــت علــى املصــدر‬   ‫املدعــي العــام عليــه أجــاب قائ ـ ً‬\n      ‫قطعــة احلشــيش املخــدر املذكــورة يف الدعــوى حيــث ســلمت لــه القطعــة‬\n      ‫واســتلمت منــه املبلــغ احلكومــي املرقــم وقــدره ( ‪ ) 250‬مائتــان وخمســون‬\n      ‫ريــا ًال وقــد صرفــت هــذا املبلــغ يف شــؤوني اخلاصــة وصحيـ ٌـح أننــي‬\n      ‫اســتخدمت هاتفــي اجلــوال املذكــور يف الدعــوى يف التنســيق مــع املصدر‬\n      ‫يف بيــع القطعــة املذكــورة وغيــر صحيــح أننــي اســتخدمت ســيارتي‬\n      ‫املذكــورة يف بيــع القطعــة املذكــورة وصحيـ ٌـح أنــه وجــد يف منزلــي مــا‬\n      ‫ـيش مخــدر وحبــوب روش وجوالــن مســكر‬           ‫ُذكــر يف الدعــوى مــن حشـ ٍ‬\n      ‫وهــذا كلــه يف حيازتــي بقصــد التعاطــي فقــط وليــس الترويــج وصحيـ ٌـح‬\n      ‫أنــه عنــد القبــض علــي كان يف حيازتــي قارورتــي املســكر املذكــورة‬\n      ‫يف الدعــوى بقصــد الشــرب وغيــر صحيـ ٌـح اتهامــي بترويجهــا وصحيـ ٌـح‬\n      ‫أننــي شــربت املســكر يــوم القبــض علــي وتعاطيت احلشــيش قبــل القبض‬\n      ‫بحوالــي ســبعة أشــهر وتعاطيــت حبــوب الكلونازيبــام قبــل خمــس‬\n      ‫ســنوات وأمــا بالنســبة للمبلــغ املالــي املوجــود يف املنــزل فلــم يكــن قــدره‬\n\n\n‫‪221‬‬\n\f‫(‪ ) 1300‬ألــف وثالثمائــة ريــال كمــا جــاء يف الدعــوى وإمنــا كان مبل ـ ٌغ‬\n‫وقــدره ( ‪ )2005‬ألفــان وخمســة ريــاالت وهــو جــزء مــن راتبــي وليــس مــن‬\n‫نتــاج املخــدرات أو املســكرات هــذه إجابتــي ‪ .‬وبســؤال املدعــي العــام‬\n‫عــن بينتــه فيمــا أنكــره املدعــى عليــه قــال لــدي البينــة معــدي محضــر‬\n                                ‫القبض وسوف أحضرهم يف اجللسة املقبلة ‪.‬‬\n‫ويف جلس ـ ٍة أخــرى حضــر الطرفــان كمــا حضــر ‪ ......‬مبوجــب بطاقــة‬\n‫الهويــة الوطنيــة املــدون بهــا الرقــم ‪ ......‬وقــال املدعــي العــام هــذا احلاضــر‬\n‫مــن ضمــن معــدي محضــر القبــض وأطلــب ســؤاله عمــا لديــه مــن شــهادة‬\n‫ا ‪ :‬أشــهد بــاهلل أننــي يف عمليــة بيــع قطعــة احلشــيش‬   ‫وبســؤاله شــهد قائـ ً‬\n‫املخــدر لــم أرى الســيارة التــي حضــر عليهــا املدعــى عليــه ولــم يرهــا أحــد‬\n‫مــن معــدي محضــر القبــض كمــا أشــهد بــاهلل أنــه عنــد القبــض علــى‬\n‫املدعــى عليــه توقــف بســيارة ‪ ...‬أخضــر مظللــه بجانــب ســيارة ‪ ....‬أســود‬\n‫وقــام أحــد داخــل الســيارة ‪ ....‬بتســليم كيــس لشــخص داخــل الســيارة‬\n‫‪ ....‬ومت إيقــاف الســيارة ‪ ....‬بعــد حوالــي ســاعة ونصــف أو ســاعتني وتبــن‬\n‫وجــود كيــس بداخلــه قارورتــن مســكر يحتمــل بشــكل كبيــر أنــه‬\n‫نفــس الكيــس الــذي مت تســليمه مــن قبــل شــخص يف الســيارة ‪ ....‬كمــا‬\n‫تبــن بتفتيــش الســيارة ‪ ....‬التــي حضــر عليهــا املدعــى عليــه وجــود خمــس‬\n‫قواريــر مســكر علمـ ًا أننــي لــم أرى الشــخص الــذي كان يف الســيارة‬\n‫ـخص الــذي كان يف‬      ‫‪ ....‬والــذي قــام بتســليم الكيــس املذكــور للشـ ٍ‬\n‫الســيارة ‪ ....‬كمــا مت تفتيــش منــزل املدعــى عليــه ووجدنــا املضبوطــات‬\n‫املذكــورة يف احملضــر يف غرفــة ذكــرت لنــا أخــت املدعــى عليــه وبعــض‬\n‫األطفــال الذيــن يف املنــزل أن هــذه الغرفــة تخــص ابــن أخــت املدعــى عليــه‬\n‫ولكــن املدعــى عليــه ذكــر أنــه ســيعترف بحيــازة مــا بداخــل هــذه‬\n\n\n                                                                                          ‫‪222‬‬\n\f      ‫الغرفــة حتــى ال ُيدخــل ابــن أختــه يف قضيــة علم ـ ًا أنــه ليــس ألحــد مــن‬\n      ‫معــدي احملضــر زيــادة عمــا ذكرتــه هــذا مــا لــدي مــن شــهادة وبعــرض‬\n      ‫ا ‪ :‬أمــا الشــاهد فــا‬    ‫الشــاهد وشــهادته علــى املدعــى عليــه أجــاب قائ ـ ً‬\n      ‫أقــول فيــه شــيئ ًا وأمــا شــهادته فالصحيــح أن مــن قــام بتســليم الكيــس‬\n      ‫الــذي بداخلــه قارورتــي املســكر شــخص كان معــي يف الســيارة يدعــى‬\n      ‫‪ ......‬وال اعــرف بقيــة اســمه ولــم أســلم أنــا هــذا الكيــس وال عالقــة لــي‬\n      ‫بترويــج هــذا املســكر وأمــا قواريــر املســكر التــي كانــت يف ســيارتي‬\n      ‫وهــي خمــس قواريــر فــا تخصنــي وتخــص الشــخص الــذي يدعــى ‪......‬‬\n      ‫وال أعــرف عنوانــه وقــد أحضــر هــذه القواريــر حتــى نشــربها ســوي ًا‬\n      ‫وصحيــح أن املضبوطــات التــي ذكرهــا الشــاهد هــي نفــس املضبوطــات‬\n      ‫التــي اعترفــت بحيازتهــا يف اجللســة الســابقة وهــي يف احلقيقــة تخــص‬\n      ‫ابــن اختــي ‪ ..........‬مــا عــدا قطعــة احلشــيش الصغيــرة التــي وزنهــا ( ‪) 6‬‬\n      ‫ســتة جرامــات فهــي لــي بقصــد التعاطــي وقــد اعترفــت بحيــازة جميــع‬\n      ‫املضبوطــات التــي يف املنــزل يف اجللســة الســابقة حتــى ُأخــرج ابــن أختــي‬\n      ‫مــن املوضــوع ‪ .‬وبطلــب معدلــن للشــاهد املذكــور قــرر املدعــي العــام‬\n      ‫إحضــار املعدلــن يف اجللســة املقبلــة ‪ .‬ويف جلس ـ ٍة أخــرى حضــر كل‬\n      ‫مــن ‪ ......‬ســعودي اجلنســية مبوجــب بطاقــة الهويــة الوطنيــة املــدون بهــا‬\n      ‫الرقــم ‪ ......‬ســعودي اجلنســية مبوجــب بطاقــة الهويــة الوطنيــة املــدون بهــا‬\n      ‫الرقــم ‪ ......‬وقــال املدعــي العــام احلاضــران معــدالن للشــاهد ‪ ......‬وأطلــب‬\n      ‫ســؤالهما عمــا لديهمــا مــن شــهادة وبســؤالهما شــهدا بعدالــة وديانــة‬\n      ‫ومــروءة الشــاهد ‪ ......‬ثــم جــرى ســؤال املدعــي العــام هــل لديــه مزيــد بينــة‬\n      ‫علــى الدعــوى فقــال ســوف أجيــب عــن ذلــك يف اجللســة املقبلــة ويف جلسـ ٍة‬\n      ‫أخــرى حضــر الطرفــان وجــرى ســؤال املدعــي العــام هــل لديــه زيــادة بينـ ٍة‬\n\n\n‫‪223‬‬\n\f‫علــى الدعــوى فقــال ‪ :‬ليــس لــدي ســوى مــا ورد يف الئحــة الدعــوى وأوراق‬\n                                           ‫املعاملــة ثــم جــرى رفــع اجللســة للتأمــل‪.‬‬\n‫احلمــد هلل وحــده وبعــد ويف يوم األربعاء املوافق‪1434/01/28‬هـ افتتحت‬\n‫اجللســة وفيهــا حضــر الطرفــان ثــم جــرى ســؤال املدعــى عليــه هــل ســيارة‬\n‫‪ ....‬التــي كانــت معــه عنــد القبــض تخصــه فقــال نعــم إنهــا ســيارتي وأنــا‬\n‫مــن كان يقودهــا ثــم جــرى ســؤاله هــل لديــه بينــة علــى مــا ذكــره مــن‬\n‫أن شــخص ًا معــه هــو مــن قــام بتســليم قارورتــي املســكر املذكورتــن يف‬\n‫الدعــوى فقــال ال بينــة لــدي علــى ذلــك ثــم جــرى االطــاع علــى أقــوال‬\n‫املدعــى عليــه لــدى هيئــة التحقيــق واالدعــاء العــام املرفقــة علــى اللفــات‬\n‫رقــم ( ‪ ) 28-30‬مــن طيــات املعاملــة وممــا تضمنتــه مــا نصــه ( ُعثــر داخــل‬\n‫ســيارتك علــى خمــس قواريــر ميــاه معدنيــة مــن نــوع ‪ ....‬تفــوح منهــا رائحــة‬\n‫املســكر فلمــن تعــود هــذه املضبوطــات ومــا هــو قصــدك مــن حيازتهــا ؟‬\n‫ج‪ /‬تعــود لــي شــخصي ًا بقصــد الشــرب ) وبعــرض هــذه األقــوال علــى‬\n‫ا ‪ :‬لقــد بصمــت علــى أقوالــي وصحيــح أننــي أن‬         ‫املدعــى عليــه أجــاب قائـ ً‬\n‫هــذه القواريــر لــي ويف حيازتــي بقصــد الشــرب ثــم جــرى االطــاع علــى‬\n‫بيانــات املدعــى عليــه يف بدايــة الئحــة الدعــوى وممــا تضمنتــه أن عليــه‬\n‫ســابقة حيــازة واســتعمال مخــدرات وبعــرض ذلــك علــى املدعــى عليــه‬\n‫ا الســابقة املذكــورة تخصنــي ثــم جــرى ســؤال املدعــى عليــه‬         ‫أجــاب قائـ ً‬\n‫هــل كانــت حيازتــه وتعاطيــه حلبــوب الكلونازيبــام ( الــروش ) بوصفـ ٍة‬\n‫طبيــة فقــال ‪ :‬ال بــدون وصفـ ٍة طبيــة فنظــر ًا ملا تقدم مــن الدعوى واإلجابة‬\n‫وحيــث أقــر املدعــى عليــه ببيــع قطعــة احلشــيش املخــدر املذكــورة يف‬\n‫الدعــوى وتســليمه لهــذه القطعــة واســتالمه للمبلــغ املرقــم وقــدره ( ‪250‬‬\n‫) مائتــان وخمســون ريــا ًال وصــرف هــذا املبلــغ يف شــؤونه اخلاصــة‬\n\n\n                                                                                            ‫‪224‬‬\n\f      ‫واســتخدامه لهاتفــه اجلــوال املذكــور يف الدعــوى للتنســيق مــع املصــدر‬\n      ‫يف بيــع القطعــة املذكــورة وأنكــر اســتخدامه لســيارته املشــار إليهــا يف‬\n      ‫الدعــوى يف عمليــة بيــع هــذه القطعــة وحيــث أقــر املدعــى عليــه يف جوابــه‬\n      ‫ـيش‬‫عــن الدعــوى بأنــه ُوجــد يف منزلــه مــا ُذكــر يف الدعــوى مــن حشـ ٍ‬\n      ‫مخــدر وحبــوب روش وجوالــن مســكر وأن ذلــك كلــه يف حيازتــه‬\n      ‫بقصــد التعاطــي وأنكــر قصــد الترويــج وحيــث رجــع املدعــى عليــه عــن‬\n      ‫اعترافــه بهــذه احليــازة يف جلس ـ ٍة أخــرى وقــرر أن جميــع املضبوطــات‬\n      ‫التــي يف املنــزل كانــت البــن أختــه وحيــث أن رجوعــه عــن اإلقــرار‬\n      ‫بحيازتهــا ال ُيقبــل منــه كــون اإلقــرار حج ـ ٌة قاصــر ٌة علــى املقــر وحيــث‬\n      ‫أقــر املدعــى عليــه بأنــه عنــد القبــض عليــه كان يف حيازتــه قارورتــي‬\n      ‫املســكر املذكورتــن يف الدعــوى بقصــد الشــرب وأنكــر اتهامــه‬\n      ‫بترويجهــا وأقــر بشــربه للمســكر وبتعاطيــه للحشــيش املخــدر وحلبــوب‬\n      ‫الكلونازيبــام وأقــر بــأن املبلــغ املالــي املوجــود يف املنــزل لــم يكــن قــدره‬\n      ‫( ‪ ) 1300‬ألــف وثالثمائــة ريــال وأنــه مبلغ ـ ًا وقــدره ( ‪ ) 2005‬ألفــان‬\n      ‫وخمســة ريــاالت وأنكــر أن يكــون هــذا املبلــغ مــن نتــاج املخــدرات أو‬\n      ‫املســكرات ولعــدم وجــود البينــة القاطعــة يف ذلــك ولعــدم وجــود البينــة‬\n      ‫كذلــك يف اســتعمال املدعــى عليــه لســيارته املذكــورة يف الدعــوى يف‬\n      ‫عمليــة بيــع قطعــة احلشــيش املخــدر ال ســيما وأن الشــاهد املعــدل شــرع ًا‬\n      ‫مشــعل العنــزي قــرر عــدم رؤيتــه للســيارة التــي حضــر عليهــا املدعــى عليه‬\n      ‫يف عمليــة بيــع قطعــة احلشــيش املخــدر وأنــه أيض ـ ًا لــم يرهــا أحـ ٌـد مــن‬\n      ‫معــدي محضــر القبــض ولعــدم وجــود البينــة القاطعــة يف إثبــات إدانــة‬\n      ‫املدعــى عليــه بترويــج قارورتــي املســكر املشــار إليهمــا يف الدعــوى‬\n      ‫ـاء على ما ورد يف شــهادة الشــاهد‬      ‫وحيــث أن التهمــة متوجـ ٌة لــه يف ذلــك بنـ ً‬\n\n‫‪225‬‬\n\f‫املعــدل شــرع ًا ‪ ......‬وممــا تضمنتــه أنــه عنــد القبــض علــى املدعــى عليــه‬\n‫توقــف بســيارة ‪ ....‬أخضــر مظللــه بجانــب ســيارة ‪ ....‬أســود وقــام أحــد‬\n‫داخــل الســيارة ‪ ....‬بتســليم كيــس لشــخص داخــل الســيارة ‪ ....‬وأنــه بعــد‬\n‫إيقــاف ‪ ....‬تبــن وجــود كيــس بداخلــه قارورتــي مســكر ويحتمــل‬\n‫بشــكل كبيــر أنــه نفــس الكيــس الــذي مت تســليمه مــن قبــل شــخص‬\n‫يف الســيارة ‪ ....‬وقــرر الشــاهد بأنــه لــم يــرى الشــخص الــذي يف كان يف‬\n‫الســيارة ‪ ....‬والــذي قــام بتســليم الكيــس املذكــور وحيــث أقــر املدعــى‬\n‫عليــه يف معــرض ســماع شــهادة الشــاهد املذكــور بــأن مــن قــام بتســليم‬\n‫الكيــس الــذي بداخلــه قارورتــي املســكر شــخص كان معــه يف‬\n‫الســيارة وأنكــر أن يكــون هــو مــن ســلم هــذا الكيــس أو أن يكــون‬\n‫لــه عالقــة بترويــج املســكر وحيــث أن يف ذلــك مــا يوجــه التهمــة يف حــق‬\n‫املدعــى عليــه باالشــتراك يف ترويــج هاتــن القارورتــن وممــا يزيــد يف‬\n‫جانــب التهمــة يف هــذا أيضـ ًا بــأن مــا أقــر بــه يتناقــض مــع مــا أقــر بــه يف‬\n‫جوابــه عــن الدعــوى مــن أن هاتــن القارورتــن يف حيازتــه بقصــد الشــرب‬\n‫وحيــث أنكــر املدعــى عليــه يف معــرض ســماع شــهادة الشــاهد املذكور‬\n‫حيــازة قواريــر املســكر املوجــود يف الســيارة ‪ ....‬وأقــر بأنهــا تخــص‬\n‫الشــخص الــذي ُيدعــى ‪ ......‬وأن هــذا الشــخص أحضرهــا لكــي‬\n‫يشــرباها ســوي ًا بينمــا أقــر يف هــذه اجللســة بحيازتــه لهــذه القوارير بقصد‬\n‫ـض يوجــه التهمــة لــه يف حيــازة هــذه القواريــر‬         ‫الشــرب ويف هــذا تناقـ ٌ‬\n‫بقصــد الترويــج باإلضافــة للشــرب ولتوجــه التهمــة يف حــق املدعــى عليــه‬\n‫بــأن قصــده مــن حيــازة املضبوطــات املوجــودة يف منزلــه كانــت بقصــد‬\n‫الترويــج باإلضافــة للتعاطــي بداللــة قيامــه ببيــع قطعــة احلشــيش املخــدر‬\n‫املذكــورة يف الدعــوى وبعــد االطــاع علــى طيــات املعاملــة ومــن ضمنهــا‬\n\n\n                                                                                          ‫‪226‬‬\n\f      ‫التقريــر الكيمــاوي الشــرعي الصــادر مــن املركــز اإلقليمــي ملراقبــة‬\n      ‫الســموم باملنطقــة الشــرقية برقــم ‪ .........‬املتضمــن احتــواء العينتــن رقــم‬\n      ‫( ‪ ) 32/1082‬ورقــم ( ‪/1082‬د ) علــى مــادة الكحــول اإليثيلــي وبنســب ٍة‬\n      ‫مســكرة وإيجابيــة العينتــن رقــم ( ‪/1082‬أ ) ورقــم ( ‪/1082‬ب ) ملــادة‬\n      ‫احلشــيش املخــدر وإيجابيــة العينــة رقــم ( ‪/1082‬ج ) لعقــار الكلونازيبــام‬\n      ‫وبعــد االطــاع علــى التقريــر الكيمــاوي الشــرعي الصــادر مــن املركــز‬\n      ‫اإلقليمــي ملراقبــة الســموم باملنطقــة الشــرقية برقــم () املتضمــن إيجابيــة‬\n      ‫العينــة ملــادة احلشــيش املخــدر وبعــد االطــاع علــى أقــوال املدعــى عليــه‬\n      ‫لــدى هيئــة التحقيــق واالدعــاء العــام املشــار إليهــا بعاليــه وبعــد االطــاع‬\n      ‫علــى إيضاحــات واقعــة القبــض والضبــط والتفتيــش املدونــة علــى‬\n      ‫الصفحــة رقــم ( ‪ ) 11‬مــن ملــف ضبــط إجــراءات االســتدالل يف قضايــا‬\n      ‫املخــدرات املرفــق علــى اللفــة رقــم ( ‪ ) 1‬مــن طيــات املعاملــة املتضمــن‬\n      ‫نحــو مــا ُأشــير إليــه يف الدعــوى وبعــد االطــاع علــى إيضاحــات واقعــة‬\n      ‫القبــض والضبــط والتفتيــش املدونــة علــى الصفحتــن رقــم ( ‪) 12 - 11‬‬\n      ‫مــن ملــف ضبــط إجــراءات االســتدالل يف قضايــا املخــدرات املرفــق علــى‬\n      ‫اللفــة رقــم ( ‪ ) 18‬مــن طيــات املعاملــة وممــا تضمنتــه بأنــه شــوهد شــخص‬\n      ‫يقود ســيارة من نوع ‪ ....‬أخضر ويقوم بتســليم أحد األشــخاص قارورتني‬\n      ‫ُيشــتبه أن تكــون مــن الشــراب املســكر وأثنــاء اســتيقاف الشــخص‬\n      ‫املذكــور اتضــح أنــه يدعــى ‪ ......‬وحيــث أن يف هــذا احملضــر مــا يوجــه‬\n      ‫التهمــة يف حــق املدعــى عليــه بترويــج قارورتــي املســكر املذكورتــن‬\n      ‫ـاء علــى الفقــرة ( ‪ ) 2‬مــن املــادة رقــم ( ‪ ) 3‬والفقــرة ( ‪ ) 1‬مــن املــادة‬\n                                                                                   ‫وبنـ ً‬\n      ‫رقــم ( ‪ ) 38‬واملــادة رقــم ( ‪ ) 53‬والفقــرة ( ‪ ) 1‬مــن املــادة رقــم ( ‪) 56‬‬\n      ‫والفقــرة ( ‪ ) 1‬مــن املــادة رقــم ( ‪ ) 62‬مــن نظــام مكافحــة املخــدرات‬\n\n\n‫‪227‬‬\n\f‫واملؤثــرات العقليــة لذلــك كلــه فقــد قــررت مــا يلــي ‪ :‬أوالً‪ -‬ثبــت لــدي‬\n‫إدانــة املدعــى عليــه بترويــج قطعــة احلشــيش املخــدر املذكــورة يف‬\n‫الدعــوى البالــغ وزنهــا ( ‪ ) 6.9‬ســتة جرامــات وتســعة مــن العشــرة مــن‬\n‫اجلــرام وذلــك عــن طريــق البيــع وقــررت معاقبتــه علــى ذلــك مبــا يلــي ‪ :‬أ‪-‬‬\n‫ـداء مــن تاريــخ إيقافــه وجلــده أربعمائــة‬  ‫ســجنه ملــدة خمــس ســنوات ابتـ ً‬\n‫ـات متســاوية بــن كل دفعـ ٍة وأخــرى مــا ال‬      ‫جلــدة مفرقــة علــى ثمــان دفعـ ٍ‬\n‫يقــل عــن خمســة عشــر يوم ـ ًا وتغرميــه مبلغ ـ ًا وقــدره ( ‪ ) 5000‬خمســة‬\n‫آالف ريــال ‪ .‬ب‪ -‬منعــه مــن الســفر ملــدة خمــس ســنوات تبــدأ بعــد انتهــاء‬\n‫مدة السجن املقررة يف حقه يف الفقرة ( أ ) من هذا البند ‪ .‬ج‪ -‬مصادرة‬\n‫هاتفــه اجلــوال املذكــور رقمــه املصنعــي يف الدعــوى الســتخدامه يف‬\n‫التنســيق لعمليــة البيــع املذكــورة مــع إســقاط شــريحة الهاتــف اجلــوال‬\n‫املذكــور يف الدعــوى وعــدم صرفهــا لنفــس املدعــى عليــه ‪ .‬ثانيـاً‪ -‬عــدم‬\n‫اســتحقاق املدعــي العــام ملــا ُيطالــب بــه مــن مصــادرة الســيارة ‪ ....‬املشــار‬\n‫إليهــا يف الدعــوى ملــا ورد مــن ضمــن احليثيــات أعــاه ‪ .‬ثالث ـاً‪ -‬إلــزام‬\n‫املدعــى عليــه بدفــع مبلـ ٍـغ وقــدره ( ‪ ) 250‬مائتــان وخمســون ريــا ًال وذلــك‬\n‫للجهــة املختصــة بــد ًال عــن املبلــغ احلكومــي املرقــم الــذي قــام بصرفــه‪.‬‬\n‫رابعـاً‪ -‬عــدم اســتحقاق املدعــي العــام ملــا ُيطالــب بــه مــن مصــادرة املبلــغ‬\n‫املالــي املشــار إليــه يف الدعــوى وقــدره ( ‪ )1300‬ألــف وثالثمائــة ريــال‬\n‫لعــدم وجــود البينــة القاطعــة مــن أنــه مــن نتــاج جتــارة املخــدرات أو‬\n‫املســكرات ‪ .‬خامس ـاً‪ -‬ثبــت لــدي إدانــة املدعــى عليــه بحيــازة ( ‪) 37‬‬\n‫ســبعه وثالثــن حبــة مــن عقــار الكلونازيبــام بقصــد التعاطــي بــدون‬\n‫وصفـ ٍة طبيــة كمــا ثبــت لــدي إدانتــه بحيــازة ثــاث قطـ ٍـع مــن احلشــيش‬\n‫املخــدر البالــغ وزنهــا ( ‪ ) 77.3‬ســبعه وســبعني جرامـ ًا وثالثــة مــن العشــرة‬\n\n\n                                                                                        ‫‪228‬‬\n\f      ‫مــن اجلــرام بقصــد التعاطــي والتهمــة متوجه ـ ُة يف حقــه بحيــازة هــذه‬\n      ‫احلبــوب والقطــع بقصــد الترويــج باإلضافــة للتعاطــي ملــا ُذكــر مــن ضمــن‬\n      ‫احليثيــات أعــاه وعقوبتــه يف ذلــك كلــه داخلـ ٌة يف العقوبــة الصــادرة يف‬\n      ‫ـاء بالعقوبــة‬‫حقــه يف الفقرتــن ( أ ) و ( ب ) مــن البنــد ( أو ًال ) اكتفـ ً‬\n      ‫األشــد ‪ .‬سادسـاً‪ -‬توجــه التهمــة يف حــق املدعــى عليــه يف ترويــج قارورتــي‬\n      ‫املســكر املذكورتــن يف الدعــوى ملــا ورد مــن ضمــن احليثيــات أعــاه‬\n      ‫كمــا ثبــت لــدي إدانتــه بحيــازة ( ‪ ) 5‬خمــس قواريــر مــن املســكر املشــار‬\n      ‫إليهــا يف الدعــوى املوجــودة يف ســيارته بقصــد الشــرب والتهمــة متوجهــة‬\n      ‫يف حقــه بحيازتهــا بقصــد الترويــج باإلضافــة للشــرب كمــا ثبــت لــدي‬\n      ‫إدانــة املدعــى عليــه بحيــازة (‪ ) 4‬أربــع جوالــن مــن املســكر املضبوطــة‬\n      ‫يف منزلــه بقصــد الشــرب والتهمــة متوجه ـ ٌة يف حقــه بحيازتهــا بقصــد‬\n      ‫الترويــج باإلضافــة للشــرب وعقوبتــه علــى ذلــك كلــه داخلــة يف عقوبــة‬\n      ‫الســجن واجللــد الصــادرة يف حقــه يف القفــرة ( أ ) مــن البنــد ( أو ًال )‬\n      ‫ـاء بالعقوبــة األشــد ‪ .‬ســابعاً‪ -‬ثبــت لــدي إدانــة املدعــى عليــه بشــرب‬\n                                                                                 ‫اكتفـ ً‬\n      ‫املســكر وقــررت جلــده حــد املســكر ثمانــن جلــدة دفع ـ ًة واحــده علن ـ ًا‬\n      ‫مبجمـ ٍـع مــن النــاس علــى أن ُيفـ ّـرق بــن هــذا اجللــد واجللــد الصــادر يف‬\n      ‫حقــه يف الفقــرة ( أ ) مــن البنــد ( أو ًال ) مبــد ٍة ال تقــل عــن خمســة عشــر‬\n      ‫يوم ـ ًا ‪ .‬ثامن ـاً‪ -‬ثبــت لــدي إدانــة املدعــى عليــه بتعاطــي احلشــيش املخــدر‬\n      ‫واكتفيــت مبــا صــدر عليــه مــن حــدٍ للمســكر املذكــور يف البنــد‬\n      ‫(ســابعاً) كمــا اكتفيــت مبــا صــدر عليــه مــن منـ ٍـع مــن الســفر املذكــور‬\n      ‫يف الفقــرة ( ب ) مــن البنــد ( أو ًال ) ‪ .‬تاســعاً‪ -‬ثبــت لــدي إدانــة املدعــى‬\n      ‫عليــه بتعاطــي حبــوب عقــار الكلونازيبــام بــدون وصف ٍة طبيــة واكتفيت‬\n      ‫مبــا صــدر عليــه مــن حــدٍ للمســكر املذكــور يف البنــد ( ســابع ًا ) عــن‬\n\n\n‫‪229‬‬\n\f‫تعزيــره لقــاء ذلــك كمــا اكتفيــت مبــا صــدر عليــه مــن منـ ٍـع مــن الســفر‬\n‫املذكــور يف الفقــرة ( ب ) مــن البنــد ( أو ًال ) وبذلــك أجمــع حكمــت‬\n‫وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه القناعة وقــرر املدعي‬\n‫العــام االعتــراض وطلــب رفــع احلكــم حملكمــة االســتئناف واكتفــى‬\n‫بالئحــة الدعــوى وأوراق املعاملــة عــن تقــدمي الئح ـ ٍة اعتراضيــة ف ٌأجيــب‬\n                ‫لطلبه واهلل املوفق وصلى اهلل على نبينا محمد وآله وسلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد‪ ،‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام برقــم ‪ ......‬وتاريــخ‬\n‫‪1434/2/20‬هـ املقيدة لدى احملكمة برقم ‪ ......‬وتاريخ ‪1434/2/26‬هـ‬\n‫املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪......‬‬\n‫املســجل برقــم ‪ ......‬وتاريــخ ‪1434/2/9‬ه ـ اخلــاص بدعوى‪/‬املدعــى العــام‬\n‫ضــد‪ ....../‬يف قضيــة مخــدرات ومســكر وقــد تضمــن القــرار حكــم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه‬\n‫وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل‬\n          ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/4/17‬ه ـ‬\n\n\n\n\n                                                                                    ‫‪230‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":214,"source_page_end":230,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"153f76efcbd454bde73fa100bc4115e6e4264f7f07a6d135f510234696afc2d6","normalized_text_hash":"88b95ad3f69ca73548c601cd30fb15d399d5b27cdff9ff441dc7a9bfab029915","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p214-3432371"},{"id":"af7b6fa5-bfe0-5c17-88b1-543c2a8f13b7","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -شروع يف نقل حبوب محظورة-شهادة شهود ومحاضر ضبط -إقرار املدعى عليه حتقيق ا -ضبط احلبوب احملظورة داخل املطار حال وصولها -ثبوت إدانة -تعزير بالسجن واجللد والغرامة ومصادرة ومنع من السفر.","document_number":"33297549","case_number":"3374553","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1432/01/29","year":"1434","subject":"مخدرات -شروع يف نقل حبوب محظورة-شهادة شهود ومحاضر ضبط -إقرار املدعى عليه حتقيق ا -ضبط احلبوب احملظورة داخل املطار حال وصولها -ثبوت إدانة -تعزير بالسجن واجللد والغرامة ومصادرة ومنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 33297549 :‬تاريخه‪1432/01/29 :‬هـ‬\n                            ‫رقم الدعوى‪3374553:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34195156‬تاريخه‪1434/4/22 :‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬شــروع يف نقــل حبــوب محظورة‪-‬شــهادة شــهود ومحاضــر‬\n       ‫ضبــط ‪ -‬إقــرار املدعــى عليــه حتقيقـ ًا ‪ -‬ضبــط احلبــوب احملظــورة داخــل‬\n       ‫املطــار حــال وصولهــا ‪ -‬ثبــوت إدانــة ‪ -‬تعزيــر بالســجن واجللــد والغرامــة‬\n                                                      ‫ومصــادرة ومنــع مــن الســفر‪.‬‬\n\n\n\n\n       ‫املــادة ‪ ، 38‬املــادة ‪ 59‬فقــرة (‪،)1‬املــادة ‪ 60‬مــن نظــام مكافحــة املخــدرات‬\n                                                               ‫واﻤﻟﺆﺛﺮات اﻟﻌﻘﻠﻴﺔ‪.‬‬\n\n\n\n\n                 ‫أقام املدعي العام دعواه ضد املدعى عليه طالب ًا احلكم عليه‪-:‬‬\n       ‫‪ .1‬عقوبــة القتــل املنصــوص عليهــا يف الفقــرة (‪ )1‬مــن املــادة الثالثــة مــن‬\n                                                  ‫نظــام املخــدرات واملؤثــرات العقليــة‬\n       ‫‪ .2‬مصــادرة جوالــه وفقـ ًا للفقــرة (‪ )1‬مــن املــادة ‪ 53‬مــن ذات النظــام وعدم‬\n                                                  ‫صــرف شــريحة اجلــوال لــه مــرة أخرى‬\n       ‫‪ .3‬مصــادرة الســيارة العائــدة للمتهــم وذلــك بعــد القبــض عليــه متلبس ـ ًا‬\n       ‫بالشــروع يف نقــل احلبــوب املخــدرة مبعرفــة رجــال األمــن واعترافــه‬\n                                                                    ‫مبحاضــر الضبــط‪.‬‬\n       ‫ومبواجهــة املدعــى عليــه أنكــر التهمــة وبــرر تواجــده بالســوق مــن أجــل‬\n\n‫‪231‬‬\n\f‫شــراء بعــض اخلضــار والفاكهــة ألجــل ســفره مــع أبنــاء عمــه‪ .‬وبعــد أن‬\n‫قارنــت احملكمــة بــن أقــوال وبينــات الطرفــن وطالعــت أوراق القضيــة‬\n‫وســماع شــهادة الشــهود قــررت احملكمــة اآلتــي‪ :‬صــرف النظــر عــن‬\n‫دعــوى املدعــى العــام وعــن مطالبتــه بتطبيــق املــادة ‪ 37‬رقــم ‪ 2‬مــن البنــد‬\n‫أوالً‪ :‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ ،‬وعــن مطالبتــه‬\n‫بتطبيــق الفقــرة (‪ )1‬مــن املــادة ‪ 53‬مــن النظــام نفســه ‪ .‬ثانيـاً‪ :‬ثبــت لديهــا‬\n‫الشــروع يف نقــل املــواد احملظــورة وقــررت تعزيــره ألجــل ذلــك بالســجن‬\n‫عشــر ســنوات وجلــده ألــف جلــدة وتغرميــه مببلــغ خمســن ألــف ريــال تــودع‬\n‫يف بيــت مــال املســلمني ومنعــه مــن الســفر مــدة مماثلــة ملــدة ســجنه‪ .‬ولــم‬\n‫يقنــع كل مــن املدعــى العــام واملدعــى عليــه ‪ ،‬وجــرى تصديــق محكمــة‬\n                                                       ‫االســتئناف علــى احلكــم‪.‬‬\n\n\n\n‫احلمد هلل وحده وبعد لدينا نحن ‪ ................‬القضاة يف احملكمة العامة‬\n‫بالدمــام وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالدمــام برقــم ‪................‬وتاريــخ ‪1433/01/29‬ه ــاملقيدة‬\n‫باحملكمــة برقــم ‪................‬وتاريــخ ‪ 1433/01/29‬ه ـ ففــي يــوم االثنــن‬\n‫املوافــق‪ 1433/02/15‬ه ـ افتتحــت اجللســة الســاعة ‪ 12 : 55‬وفيهــا‬\n‫حضــر املدعــي العــام بالدمــام ‪................‬وقــدم الئحــة الدعــوى املتضمنــة‬\n‫‪ :‬اســم املتهــم‪ ................ :‬اجلنــس‪ :‬ذكــر‪ .‬اجلنســية‪ :‬ســعودي‪ .‬العمــر وقــت‬\n‫اجلرميــة‪ 23 :‬رقــم الهويــة‪................ :‬املهنــة‪ :‬متســبب احلالــة االجتماعيــة‪:‬‬\n‫أعــزب مــكان اإلقامــة‪ - .... :‬حــي ‪.........‬جهــة اإليقــاف‪ :‬شــعبة اصالحيــة‬\n‫الدمــام تاريــخ القبــض‪ 1432/7/23 :‬حالــة املتهــم‪ :‬موقــوف اإلتهــام‪:‬‬\n\n                                                                                         ‫‪232‬‬\n\f                   ‫تلقــي املؤثــرات العقليــة بقصــد الترويــج الســوابق‪ :‬ال يوجــد ‪..‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن النبــي بعــده ‪ ...‬بصفتــي‬\n      ‫مدعي ـ ًا عام ـ ًا بدائــرة اإلدعــاء العــام لفــرع الهيئــة باملنطقــة الشــرقية‬\n      ‫أدعــي علــى املذكــور أعــاه أنــه بتاريــخ ‪1432/7/22‬ه ــتم القبــض علــى‬\n      ‫املتهــم اعــاه اثــر بــاغ مــن قبــل وحــدة مكافحــة املخــدرات مبطــار امللــك‬\n      ‫فهــد الدولــي مبنــي علــى بــاغ مــن قبــل جمــرك مطــار امللــك فهــد بقــدوم‬\n      ‫شــحنة جويــة قادمــة مــن دولــة ‪ ....‬بداخلهــا بضائــع من الفواكــه (فاكهة‬\n      ‫الكرز) ويف أثناء تفتيشــها مت العثور على ما عدده (‪ )211.293‬مائتان‬\n      ‫وأحــد عشــر ألفــا ً ومئتــان وثــاث وتســعون حبة أثبت التقريــر الكيماوي‬\n      ‫الشــرعي رقــم (‪ ).........‬وتاريــخ ‪1432/8/4‬ه ـ إيجابيــة عيناتهــا ملــادة‬\n      ‫(االمفيتامــن) املنبهــة واملدرجــة باجلــدول الثانــي فئــة (ب) مــن نظــام‬\n      ‫ـاء عليــه مت اســتدعاء‬    ‫مكافحــة املخــدرات واملؤثــرات العقليــة ‪ ،‬وبنـ ً‬\n      ‫املخلــص اجلمركــي للبضاعــة املدعــو ‪................ /‬ومبناقشــته أفــاد أن‬\n      ‫البضاعــة هــي فواكــه مســتوردة ألحــد التجــار املســتوردين يف ســوق‬\n      ‫اخلضــار والفواكــه بالدمــام ويدعــى ‪................ /‬وباالتصــال عليــه قــام‬\n      ‫باحلضــور إلــى وحــدة مكافحــة املخــدرات باملطار وبســؤاله عــن تفاصيل‬\n      ‫ســير البضاعــة املضبوطــة ذكــر أنــه دائمـ ًا مــا يقــوم باســتيراد الفواكــه‬\n      ‫وأنــه قــد اتصــل بــه شــخص ‪ ....‬اجلنســية يدعــى ‪................ /‬وأفــاد وهــو‬\n      ‫أحــد جتــار الفواكــه يف ‪ ....‬ولــه تعامــل مســبق معــه وآخرهــا يف اجلمعــة‬\n      ‫الفائتــة علــى بضاعــة مــن الفواكــه (الكــرز) حيــث اســتلمها وقــام‬\n      ‫بوضعهــا لديــه بالثالجــات وحضــر إليــه بعــد ذلــك شــخصان (ســعوديان)‬\n      ‫علــى ســيارة مــن نــوع (‪ )................‬وقامــا بتحميــل البضاعــة وذهبــوا بهــا‬\n      ‫مقابــل عمولــة يأخذهــا علــى ذلــك وأبــدى اســتعداده للتعــاون باإلطاحــة‬\n\n\n‫‪233‬‬\n\f‫باملســتقبل لهــذه الكميــة ويف متــام الســاعة الرابعــة عصــر ًا مت االنتقــال‬\n‫إلــى ســوق اخلضــار مبدينــة الدمــام ومت اصطحــاب البضاعة بســيارة (‪)....‬‬\n‫ووضعهــا يف داخــل الســوق وقــام ‪................ /‬باالتصــال علــى التاجــر ‪.....‬‬\n‫‪ .. /‬علــى الرقــم (‪ )................‬وأفــاد أن البضاعــة قــد وصلــت وســأله‬\n‫عــن الشــخص الــذي ســوف يقــوم باســتالمها فذكــر لــه أنــه شــخص‬\n‫يدعــى ‪................‬ويحمــل اجلــوال رقــم ‪................‬وأنــه ســوف يحضــر إليــه‬\n‫ـاء علــى ذلــك مت التمركــز يف ســوق اخلضــار بالدمــام‬      ‫يف اليــوم التالــي وبنـ ً‬\n‫ويف الســاعة السادســة صباحـ ًا قــام ‪................ /‬باالتصــال علــى املتهــم ‪/‬‬\n‫‪................‬علــى اجلــوال رقــم ‪................‬وطلــب منــه احلضــور إليــه الســتالم‬\n‫البضاعــة فذكــر لــه أنــه ســوف يحضــر بعــد قليــل وكانــت املكاملــة‬\n‫علــى مســمع مــن قائــد الفرقــة وبعــد نصــف ســاعة حضــرت ســيارة مــن‬\n‫نــوع ‪ ................‬اللــون ‪ ....‬حتمــل اللوحــة رقــم (‪ )............‬وقــام بالوقــوف‬\n‫بالقــرب مــن املوقــع وترجــل مــن ســيارته وتوجــه إلــى ‪ ................ /‬وســأله‬\n‫هــل البضاعــة جاهــزة فأفــاده أنهــا جاهــزة وطلــب منــه إحضــار ســيارة‬\n‫ليقــوم العمــال بتحميــل البضاعــة عليهــا ولوحــظ علــى املتهــم عالمــات‬\n‫االرتبــاك وكثــرة االلتفــات مينــة ويســرة ويبــدو أنــه يف اثنــاء ذلــك شــاهد‬\n‫قائــد الفرقــة وشــاهد آثــار التفتيــش علــى البضاعــة وقــام بالرجــوع إلــى‬\n‫ســيارته مــرة أخــرى ووقــف بالقــرب مــن بــاب الســائق وحضــر شــخص ‪....‬‬\n‫اجلنســية واحتــك بــه وكانــا يتفقــان علــى نقــل البضاعــة إلــى مدينــة ‪....‬‬\n‫وللخــوف مــن أن يكــون املتهــم قــد شــاهد البضاعــة وعليهــا عالمــات‬\n‫التفتيــش متــت مداهمتــه والقبــض عليه وبتفتيشــه شــخصي ًا لــم يتم العثور‬\n‫بحوزتــه علــى شــيء مــن املمنوعــات وبأخــذه خــارج املوقــع ومبحاولــة‬\n‫مناقشــته حــول القضيــة واإلحلــاح عليــه حيــال ذلــك أفــاد انــه قبــل يومــن‬\n\n\n                                                                                              ‫‪234‬‬\n\f                                 ‫قابــل شــخص يدعــى ‪................ /‬يف محافظــه ‪.....‬‬\n      ‫وذكــر لــه أن هنــاك حجــر ابيــض قــادم مــن ســوريا وهــو يقصــد بذلــك‬\n      ‫احلبــوب املخــدرة وتقــدر كميتهــا بــ(‪ )1000‬شــد وأنــه قــد أغــراه باملــال‬\n      ‫ووعــده مببلــغ (‪ )150‬مائــة وخمســن ألــف ريــال إذا قــام باحضارهــا إليــه‬\n      ‫يف محافظــة اخلــرج وكان ذلــك علــى مســمع مــن قائــد الفرقــة وأحــد‬\n      ‫أعضائهــا ومت متكينــه مــن االتصــال باملدعــو‪ ....‬علــى جوالــه رقــم (‪)....‬‬\n      ‫وذكــر لــه أن األمــور طيبــة وعلــى مــا يــرام ولكــن املدعــو‪ ...‬كان قلقـ ًا‬\n      ‫وكان يتصــل يف كل دقيقــة حملاولــة كشــف الشــخص وبعــد ذلــك قــام‬\n      ‫باقفــال جوالــه وبتفتيــش الســيارة العائــدة للمتهــم لــم يتــم العثــور بهــا علــى‬\n      ‫شــيء مــن املمنوعــات وأفــاد مســتورد البضاعــة‪ ....‬أن البضاعة املضبوطة‬\n      ‫قــد وردت عــن طريــق مطــار امللــك فهــد الدولــي مــن قبــل شــخص ســوري‬\n      ‫اجلنســية يدعــى‪ .....‬يتعامــل معــه يف مجــال توريــد الفواكــه منــذ ســنوات‬\n      ‫وقــد انقطــع عــن التعامــل معــه يف الفتــرة األخيــرة ولكنــه عــاد واتصل به‬\n      ‫وطلــب منــه اســتالم بضاعــة مــن الفواكــه ســوف تصــل ملطــار امللــك فهــد‬\n      ‫بالدمــام وتســمليها ‪ .. ...‬وبعــد وصــول البضاعــة مت االتصــال بــه مــن قبــل‬\n      ‫مكافحــة املخــدرات وبســؤاله عــن البضاعــة ذكــر لهــم مــا يعرفــه فتــم‬\n      ‫االتفــاق معــه علــى إخــراج البضاعة من املطار واالتصال بالشــخص الذي‬\n      ‫طلــب منــه أبــو ‪ ....‬وهــو ‪ ....‬للحضــور الســتالمها وبعــد ذلــك قــام باالتصــال‬\n      ‫باملتهــم علــى جوالــه ‪ ....‬واخبــره بوصــول البضاعــة وحضــر املتهــم‪ ،‬وقــام‬\n      ‫مبقابلتــه بالســوق وانصــرف بغــرض إحضــار ســيارة للتحميل ومت القبض‬\n      ‫عليــه يف أثنــاء ذلــك‪ ،‬وأضــاف أنــه ويف األســبوع املاضــي وصلــت بضاعــة‬\n      ‫عــن طريــق نفــس التاجــر وحضــر املتهــم وبرفقتــه شــخص آخــر لتحميلهــا‬\n      ‫وأفــاد أنــه يقــوم بذلــك مقابــل عمولــة يقــوم بأخذهــا ‪ .‬وبعــرض املتهــم ‪....‬‬\n\n\n‫‪235‬‬\n\f‫علــى ‪ ....‬قــام بالتعــرف عليــه وذكــر أنــه هــو الشــخص الــذي حضــر إليــه‬\n‫يف الســوق الســتالم البضاعــة وقــام بســؤاله عنهــا وأنــه نفــس الشــخص‬\n‫الــذي حضــر إليــه مــن قبــل وقــام باســتالم البضاعــة منــه ومبواجهــة‬\n‫ا وأنكــر مشــاهدته‬      ‫املتهــم بذلــك أنكــر عالقتــه ب ــ‪ ....‬جملــة وتفصي ـ ً‬\n‫لــه مــن قبــل وأنكــر جميــع مــا ذكــره مــن أقــوال وأنكــر وجــود اتصــال‬\n‫بينهمــا‪ .‬وأفــاد صاحــب الســيارة (النقــل) ‪ .....‬علــى أن املتهــم‪ ....‬قــد‬\n‫حضــر إليــه وطلــب منــه نقــل كميــة مــن الفواكــه إلــى مدينــة اخلــرج‬\n‫ومت االتفــاق علــى ذلــك مقابــل مبلــغ ‪700‬ريــال ويف صبــاح ذلــك اليــوم‬\n‫اتصــل بــه وطلــب منــه احلضــور إليــه يف الســوق لتحميــل البضاعــة وبعــد‬\n‫حضــوره قــام مبقابلتــه يف الســوق وهــو واقــف بجانــب ســيارته مــن نــوع ‪...‬‬\n‫أبيــض اللــون وطلــب منــه االنتظــار لتحميــل البضاعــة ويف أثنــاء ذلــك مت‬\n‫القبــض عليــه وأضــاف أنــه كان وحــده‪ .‬وبعــرض املتهــم‪ ...‬علــى صاحــب‬\n‫ســيارة النقــل‪ .....‬أكــد أنــه نفــس الشــخص الــذي حضــر إليــه واتفــق معــه‬\n‫علــى نقــل كميــة مــن اخلضــار حملافظــة اخلــرج واتصــل عليــه يف صبــاح‬\n‫ذلــك اليــوم وطلــب منــه احلضــور للســوق وعنــد الوصــول إلــى الســوق قــام‬\n‫مبقابلتــه وطلــب منــه االنتظــار لتحميــل البضاعــة ومت القبــض عليــه‬\n‫بعــد ذلــك‪ .‬وبســماع أقــوال املدعــى عليــه األوليــة أفــاد أنــه مت القبــض‬\n‫عليــه إثــر حضــوره الســتالم بضاعــة حتتــوي علــى الكــرز والتــي كان‬\n‫بداخلهــا احلبــوب املنبهــة واحملظــورة وأفــاد أنــه كان يعلــم بوجــود احلبــوب‬\n‫املنبهــة واحملظــورة يف داخــل هــذه البضاعــة والتــي تعــود للمدعــو ‪.....‬‬\n‫والــذي يســكن يف محافظــة اخلــرج وقــد اتفــق معــه علــى ذلــك مقابــل‬\n‫مبلــغ مالــي قــدره (‪ )150.000‬مائــة وخمســون ألــف ريــال‪ .‬وباســتجوابه‬\n‫انكــر قيامــه بتلقــي احلبــوب املنبهــة واحملظــورة وأفــاد أنــه مت القبــض‬\n\n\n                                                                                     ‫‪236‬‬\n\f      ‫عليــه أثنــاء تواجــده يف ســوق اخلضــار والفواكــه بغــرض شــراء كميــة‬\n      ‫مــن اخلضــار ألخذهــا إلــى النعيريــة لوجــود مناســبة لهــم هنــاك وأنه كان‬\n      ‫لوحــده وأفــاد أن اجلــوال رقــم ‪ ....‬ال عالقــة لــه بــه وأضــاف أنــه ال عالقــة له‬\n      ‫باحلبــوب التــي مت ضبطهــا يف داخــل صناديــق فاكهــة الكــرز وأنكــر‬\n      ‫عالقتــه باملدعــو‪ ...‬وأنكــر مــا تضمنــه محضــر القبــض مــن االتصــال‬\n      ‫عليــه مــن قبــل املدعــو ‪ ...‬للحضــور الســتالم البضاعــة وحضــوره بعــد‬\n      ‫ذلــك إلــى الســوق والوقــوف مــع ‪ ...‬والســؤال عــن البضاعــة واالتفــاق مــع‬\n      ‫شــخص ســوداني اجلنســية علــى حتميــل البضاعــة إلــى محافظــة اخلــرج‬\n      ‫وأفــاد أنــه قــد حضــر غلــى الدمــام للتمشــية‪ .‬وقــد انتهــى التحقيــق إلــى‬\n      ‫اتهامــه بتلقــي مــا عــدده (‪ )211293‬مائتــان وأحــد عشــر ألــف حبــة مــن‬\n         ‫احلبــوب املنبهــة واحملظــورة (اإلمفيتامــن) مــن مهــرب بقصــد االجتــار‪.‬‬\n                                                        ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n      ‫‪ -1‬مــا ورد يف اقــوال املتهــم املنــوه عنهــا علــى اللفــة رقــم (‪28, 25-21‬‬\n      ‫ـ‪ )29‬وعلــى الصفحــة رقــم ( ‪ ) 3-2‬مــن ملــف التحقيــق املرفــق علــى اللفــة‬\n                                                                                        ‫رقم‪2‬‬\n      ‫‪ -2‬محضــر االنتقــال والقبــض والتفتيــش املنــوه عنــه علــى الصفحــة رقــم‬\n                                 ‫( ‪) 13-11‬مــن ملــف التحقيــق علــى اللفــة رقــم (‪)1‬‬\n      ‫‪ -3‬التقريــر الكيمــاوي الشــرعي املنــوه عنــه املرفــق علــى اللفــة رقــم‬\n                                                                                      ‫(‪. )40‬‬\n      ‫‪ -4‬إفــادات ‪ ..‬واملقيــم ‪ ..‬املنــوه عنهــا واملرفقــة علــى اللفــة رقــم (‪ 30‬ـ ‪)35‬‬\n                                                                               ‫و (‪)45, 44‬‬\n      ‫‪ -5‬محضــري العــرض واملواجهــة املنــوه عنهــا املرفقــة علــى اللــف رقــم‬\n                                                                                  ‫(‪. )46,27‬‬\n\n\n‫‪237‬‬\n\f                                 ‫‪ -6‬اقرار املتهم املنوه عنه على اللفة رقم (‪. )6‬‬\n‫‪ -7‬وجــود اتصــاالت هاتفيــه بــن اجلــوال رقــم ‪ ........‬العائــد للمتهم واجلوال‬\n                                           ‫رقم ‪ ..........‬العائد ملســتورد البضاعة ‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور ـ وهــو بكامــل أهليتــه املعتبــرة‬\n‫شــرعا فعــل محــرم ومعاقــب عليــه شــرع ًا ومجــرم نظام ـ ًا مبوجــب‬\n‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة يف عقوباتــه األصليــة‬\n‫والتكميليــة أطلــب إثبــات مــا أســند إليــه وفق ـ ًا للفقــرة (‪ )1‬مــن املــادة‬\n‫الثالثــة مــن نظــام املخــدرات واملؤثــرات العقليــة واحلكــم مبــا يلــي‪/1 :‬‬\n‫عقوبــة القتــل املنصــوص عليهــا يف الفقــرة رقــم (‪ )2‬مــن البنــد( اوالً)‬\n‫مــن املــادة (‪ )37‬مــن النظــام ‪ /2 .‬مصــادرة جوالــه الــذي يحمــل الرقــم‬\n‫املصنعــي رقــم (‪ ).........‬وفق ـ ًا للفقــرة (‪ )1‬مــن املــادة (‪ )53‬مــن النظــام‬\n‫وعــدم صــرف الشــريحة رقــم (‪ )..‬لنفــس املتهــم وفق ـ ًا لتعميــم وزيــر‬\n                      ‫الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1428/2/10-9‬ه ـ ‪.‬‬\n‫ـاء علــى الفقــرة (‪)1‬‬ ‫‪ /3‬مصــادرة الســيارة العائــدة للمتهــم املوصوفــة بنـ ً‬\n   ‫مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪.‬‬\n‫وبــاهلل التوفيق‪،،،‬هــذه دعــواي ‪ ،‬وكنــا قــد كتبنــا إلصالحيــة الدمــام‬\n‫إلحضــار املدعــى عليــه هــذا اليــوم االثنــن ‪1433/3/14‬ه ـ ولــم يحضــر‬\n‫ولذلــك أجلــت اجللســة الــى يــوم االثنــن ‪1433/3/21‬ه ـ وبــاهلل التوفيــق‪.‬‬\n‫ويف هــذا اليــوم االثنــن ‪1433/3/21‬ه ـ حضــر الطرفــان وباســتجواب‬\n‫املدعــى عليــه أجــاب بقولــه ‪ :‬ماذكــره املدعــي العــام يف دعــواه كلــه‬\n‫غيــر صحيــح ولــم يحصــل منــي شــيء مــن ذلــك وأنــا كنــت فيســوق‬\n‫اخلضــار يف الدمــام أشــتري أغــراض للكشــتة وكنــت علــى موعــد مــع‬\n‫أبنــاء عمــي يف ‪ .....‬فســألت أحدهــم عــن موقــع ســوق اخلضــار فدلنــي‬\n\n\n                                                                                       ‫‪238‬‬\n\f      ‫علــى ســوق الدمــام وقــد قبــض علـ ّـي فيــه وال أدري عــن ســبب القبــض‬\n      ‫علــي ‪ .‬هكــذا أجــاب وبعــرض ذلــك علــى املدعــي العــام قــال‪ :‬الصحيــح‬\n      ‫مــا ذكرتــه ولــدي البينــة مــا يف أوراق املعاملــة وأطلــب الرجــوع إليهــا ‪.‬‬\n      ‫ورفعــت اجللســة لذلــك إلــى يــوم االثنــن ‪1433/3/28‬هـ الســاعة العاشــرة‬\n                                                              ‫والنصــف واهلل املوفــق‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ويف هــذا اليــوم االثنــن املوافق‪1433/04/05‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪10 : 20‬وفيهــا حضــر الطرفــان وقــد جــرى‬\n      ‫الرجــوع للمعاملــة فوجدنــا علــى اللفــة رقــم ‪ 1‬ص ‪11‬و‪ 12‬واقعــة القبــض‬\n      ‫والضبــط والتفتيــش وتتضمــن مــا يلــي ‪ :‬احلمــد هلل رب العاملــن والصــاة‬\n      ‫والســام علــى أشــرف األنبيــاء واملرســلني أمــا بعــد نثبــت نحــن املوقعــن‬\n      ‫ـاء علــى املعلومــات الــواردة لنــا مــن وحــدة مكافحــة املخــدرات‬  ‫أدنــاه وبنـ ً‬\n      ‫مبطــار امللــك فهــد بالدمــام املبنــي علــى بــاغ جمــرك املطــار بشــأن ضبط‬\n      ‫كميــة مــن احلبــوب احملظــورة بيضــاء اللــون يشــتبه أن تكــون مــن‬\n      ‫حبــوب الكبتاجــون املخــدرة بلــغ إجماليهــا (‪ )211293‬مائتــن وإحــدى‬\n      ‫عشــر ألــف ومائتــن وثالثــة وتســعني حبــة والتــي كانــت مهربــة بداخــل‬\n      ‫صناديــق فاكهــة الكــرز وعليــه ويف متــام الســاعة الواحــدة ظهــرا مــن‬\n      ‫يــوم اجلمعــة ‪1432/7/22‬ه ـ مت اســتدعاء املخلــص اجلمركــي للبضاعــة‬\n      ‫املســتوردة والــذي يدعــى ‪................ /‬ومبناقشــته أفــاد بــأن البضاعــة‬\n      ‫الفواكــه هــي ملــك ألحــد التجــار املســتوردين يف ســوق اجلملــة للخضــار‬\n      ‫والفواكــه باســم يدعــى ‪................ /‬أثنــاء ذلــك مت االتصــال علــى‬\n      ‫صاحــب البضاعــة والطلــب منــه احلضــور إلــى وحــدة املكافحــة باملطــار‬\n      ‫وبالفعــل حضــر شــخصيا وقــد طلــب منــه التفاصيــل عــن ســير البضاعــة‬\n      ‫فقــد أفــاد بأنــه دائمــا مــا يقــوم بعمليــة االســتيراد للفواكــه وقــد اتصــل‬\n\n\n‫‪239‬‬\n\f‫بــه شــخص ‪....‬يدعــى ‪................ /‬وهــو أحــد جتــار الفاكهــة يف ‪ .....‬ولــي‬\n‫تعامــل مســبق معــه وآخرهــا اجلمعــة الفائتــة علــى نفــس البضاعــة نوعيــة‬\n‫كــرز واســتلمتها ووضعتهــا لــدي باملكتــب بالثالجــات حتــى حضــر‬\n‫شــخصان ســعوديان علــى ســيارة ‪ ....‬وأخذوهــا وذهبــوا بهــا ولــي عمولــة‬\n       ‫علــى ذلــك وأنــا مســتعد بالتعــاون معكــم بــكل شــيء عــن ذلــك ‪.‬‬\n‫وأننــي ســوف أقــوم بإحضارهــا إلــى مدينــة ‪ ....‬مقابــل مبلــغ وقــدره مائــة‬\n‫وخمســن ألــف ريــال فقــط وانــه قــد قــام بالتغريــر بــي ألجــل املــادة واجــل‬\n‫حاجتــي املاســة بهــا وانــه املدعــو‪ .............‬وهــو مــن قــام بالتخطيــط علــى‬\n‫تهريبهــا والــرأس املدبــر لهــا علــى هــذا أقــر علــى مــا أقولــه وقــد أذنــت‬\n‫ملــن يشــهد بذلــك ‪ .‬الشــاهد األول ‪................‬توقيعــه الشــاهد الثانــي‬\n‫‪................‬توقيعــه املقــر مبــا فيــه ‪................‬بصمتــه ‪ .‬كمــا وجدنــا علــى‬\n‫اللفــة رقــم ‪ 2‬ص ‪ 2‬مــن ملــف التحقيــق جــواب املدعى عليــه أثناء التحقيق‬\n‫معــه ‪ :‬س ‪ /‬ملــاذا مت القبــض عليــك ‪ .‬ج ‪ /‬عنــد حضــوري الســتالم فاكهــة‬\n‫الكــرز الــواردة مــن دولــة ‪ ....‬عــن طريــق املطــار ‪ .‬س ‪ /‬مــاذا كان داخــل‬\n‫الكــرز ‪ .‬ج ‪ /‬كان بداخلهــا حبــوب أبيــض محظــورة ‪ .‬س ‪ /‬هــل كنــت‬\n‫تعلــم عــن تلــك احلبــوب ‪ .‬ج ‪ /‬نعــم ‪ .‬س ‪ /‬ملــن تعــود تلــك الكميــة ج ‪ /‬تعــود‬\n‫للمدعــو ‪................‬ويســكن ‪ .....‬س ‪ /‬كــم املبلــغ املتفــق عليــه بينــك‬\n‫وبينــه اليصــال تلــك الكميــة ‪ . .....‬ج ‪ /‬كان املبلــغ املتفــق عليــه مائــة‬\n‫وخمســن الــف ريــال كمــا وجدنــا علــى اللفــة رقــم ‪ 27‬تعــرف املدعــو‬\n‫‪ ................‬علــى املدعــى عليــه وأنــه هــو الشــخص نفســه الــذي اتصــل‬\n‫بــه بعــد إرســال رقمــه ‪................‬مــن الشــخص ‪ . ....‬كمــا وجدنــا علــى‬\n‫اللفــة رقــم ‪ 46‬محضــر تعــرف املدعــو ‪................‬علــي ‪ .....‬اجلنســية علــى‬\n‫املدعــى عليــه وأنــه هــو نفــس الشــخص الــذي حضــر إليــه واتفــق معــه‬\n\n\n                                                                                             ‫‪240‬‬\n\f      ‫علــى نقــل كميــة مــن اخلضــار حملافظــة ‪ . .....‬كمــا وجدنــا علــى اللفــة‬\n      ‫رقــم ‪ 40‬التقريــر الكيمــاوي الشــرعي رقــم ‪.........‬ويتضمــن ايجابيــة‬\n      ‫العينــة املضبوطــة ملــادة االمفيتامــن املنبــه احملظــور وبعــرض ذلــك علــى‬\n      ‫املدعــى عليــه قــال ‪ :‬كل مــا جــاء فيمــا ذكــر غيــر صحيــح وأطلــب‬\n      ‫تزويــدي بنســخة ممــا ضبــط للــرد عليــه تفصيليــا ورفعــت اجللســة لذلــك‬\n      ‫بعــد اعــام الطرفــن باحلضــور يــوم االثنــن ‪1433/4/12‬ه ـ الســاعة‬\n      ‫العاشــرة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/04/05‬ه ـ احلمــد هلل وحــده ويف هــذا‬\n      ‫اليــوم االثنــن املوافــق‪ 1433/04/12‬ه ـ افتتحــت اجللســة الســاعة ‪: 32‬‬\n      ‫‪11‬وفيهــا حضــر الطرفــان وأحضــر املدعــي العــام للشــهادة كال مــن ‪... :‬‬\n      ‫‪ .............................‬وبســؤالهما عما لديهما من شــهادة شــهد كل واحد‬\n      ‫منهمــا علــى حــده بقولــه ‪:‬إنــه جاءتنــا مــن وحــدة مكافحــة املخــدرات‬\n      ‫مبطــار امللــك فهــد بالدمــام املبنــي علــى بــاغ جمــرك املطــار بشــأن‬\n      ‫ضبــط كميــة مــن احلبــوب احملظــورة بيضــاء اللــون يشــتبه أن تكــون مــن‬\n      ‫حبــوب الكبتاجــون املخــدرة بلــغ إجماليهــا ( ‪ ) 211293‬مائتــن وإحــدى‬\n      ‫عشــر ألــف ومائتــن وثالثــة وتســعني حبــة والتــي كانــت مهربــة بداخــل‬\n      ‫صناديــق فاكهــة الكــرز وعليــه ويف متــام الســاعة الواحــدة ظهــرا مــن‬\n      ‫يــوم اجلمعــة ‪1432/7/22‬ه ـ مت اســتدعاء املخلــص اجلمركــي للبضاعــة‬\n      ‫املســتوردة والــذي يدعــى ‪ ................ /‬ومبناقشــته أفــاد بــأن البضاعــة‬\n      ‫الفواكــه هــي ملــك ألحــد التجــار املســتوردين يف ســوق اجلملــة للخضــار‬\n      ‫والفواكــه باســم يدعــى ‪................ /‬أثنــاء ذلــك مت االتصــال علــى‬\n      ‫صاحــب البضاعــة وطلــب منــه احلضــور إلــى وحــدة املكافحــة باملطــار‬\n      ‫وبالفعــل حضــر شــخصيا وقــد طلــب منــه التفاصيــل عــن ســير البضاعــة‬\n\n\n‫‪241‬‬\n\f‫فقــد أفــاد بأنــه دائمــا مــا يقــوم بعمليــة االســتيراد للفواكــه وقــد اتصــل‬\n‫بــه شــخص ‪ ....‬يدعــى ‪................ /‬وهــو أحــد جتــار الفاكهــة يف ‪.....‬‬\n‫ولــه تعامــل مســبق معــه وآخرهــا اجلمعــة الفائتــة علــى نفــس البضاعــة‬\n‫نوعيــة كــرز واســتلمها ووضعهــا لديــه باملكتــب بالثالجــات حتــى‬\n‫حضــر شــخصان ســعوديان علــى ســيارة دينــا وأخذوهــا وذهبــوا بهــا ولــه‬\n‫عمولــة علــى ذلــك وأنــه مســتعد بالتعــاون معنــا بــكل شــيء عــن ذلــك‬\n‫‪.‬وبعــد أخــذ معطيــات القضيــة مت عمــل خطــة ميدانيــة ناجحــة ملعرفــة‬\n‫املخطــط لهــا واملســتقبل لهــذه الكميــة وأنــه يف متــام الســاعة الرابعــة‬\n‫عصــر ًا مت االنتقــال لســوق اخلضــار مبدينــة الدمــام واصطحــاب دينــا‬\n‫اخلضــار ووضعهــا بداخــل الســوق وصناديــق الكــرز ملعرفــة الشــخص‬\n‫الــذي يقــوم باســتالمها بعــد ذلــك وفــور وصولنــا إلــى الســوق مت متكــن‬\n‫املدعــو ‪ ................ /‬مــن االتصــال علــى ‪ ....‬الــذي يدعــى ‪................ /‬‬\n‫علــى رقــم ال نذكــره اآلن فقــد أفــاد بــأن البضاعــة وصلــت وقــام بســؤاله‬\n‫مــن الــذي ســيقوم باســتالمها فأفــاد بــأن الشــخص الــذي سيســتلمها‬\n‫شــخص يدعــى ‪................‬يحمــل هاتــف جــوال مســجل رقمــه يف احملضــر‬\n‫وأنــه ســوف يحضــر لــك يف اليــوم التالــي الصبــاح الباكــر انتهــت‬\n‫مت التمركــز جيــدا يف املوقــع بســوق اخلضــار حتــى‬     ‫املكاملــة عنــد ذلــك ّ‬\n‫اليــوم التالــي الســبت ويف حوالــي الســاعة السادســة صباحــا مت متكــن‬\n‫املدعــو ‪................ /‬مــن االتصــال علــى املدعــو ‪................ /‬علــى هاتفــه‬\n‫وطلــب منــه احلضــور الســتالم البضاعــة فأفــاده بأنــه ســوف يحضــر بعــد‬\n‫قليــل انتهــت املكاملــة وكانــت علــى مســمع مــن قائــد الفرقــة والرقيــب‬\n‫‪................‬وبعــد نصــف ســاعة تقريبــا حضــرت ســيارة مــن نــوع ‪ ....‬اللــون‬\n‫‪ ....‬حتمــل لوحــة مذكــورة يف احملضــر تعــود ملكيتهــا ‪................‬موديــل‬\n\n\n                                                                                           ‫‪242‬‬\n\f      ‫‪ .....‬وتــدور حولــه الشــكوك ووقفــت قريبـ ًا من املوقع وترجل من ســيارته‬\n      ‫ومتــت مراقبتــه حتــى وصــل إلــى املدعــو ‪ :................‬البضاعــة جاهــزة‬\n      ‫وأفــاده بأنهــا جاهــزة وقــال لــه أحضــر ســيارتك هنــاك ليقــوم بتحميلهــا‬\n      ‫العمــال وانتظرنــا عنــد ذلــك شــوهد علــى الشــخص عالمــات االرتبــاك‬\n      ‫الشــديد مــن احلــذر وكثــرة االلتفــات مينــة ويســرة وكان قــد شــاهد قائد‬\n      ‫الفرقــة ويحتمــل أنــه شــاهد الكميــة وعليهــا آثــار عالمــات التفتيــش‬\n      ‫بعــد ذلــك رجــع حتــى وصــل إلــى ســيارته مــرة أخــرى ووقــف قريب ـ ًا مــن‬\n      ‫بــاب الســائق وحضــر شــخص ســوداني واحتــك بــه وكانــا يتفقــان علــى‬\n      ‫نقــل البضاعــة إلــى مدينــة ‪ ....‬عندهــا وخوفــا مــن أن الشــخص كان‬\n      ‫يريــد أن يقــوم ســائق الدينــا املســتأجر بتحميــل البضاعــة وأنــه يقــوم هــو‬\n      ‫مبتابعتهــا ومراقبتهــا مــن بعيــد وخوفــا أيضــا مــن أنــه شــاهد البضاعــة‬\n      ‫وعليهــا عالمــات التفتيــش فقــد متــت مداهمتــه والقبــض عليــه واتضــح‬\n      ‫أنــه يدعــى ‪................‬ســعودي اجلنســية وبتفتيشــه شــخصيا لــم يعثــر علــى‬\n      ‫شــيء مــن املمنوعــات وبأخــذه خــارج املوقــع ملناقشــته وقــد مت اخلــروج مــن‬\n      ‫الســوق وأثنــاء الطريــق متــت مناقشــته عمــا حصــل بالتفصيــل وإفهامــه‬\n      ‫بــان مبــدأ الــكالم الصــدق هــو يثمــر يف حجــر القضيــة عنــد ذلــك قــام‬\n      ‫ا ‪:‬بأنــه قبــل يومــن‬    ‫باملراوغــة يف بــادئ األمــر وبعــد اإلحلــاح أفــاد قائ ـ ً‬\n      ‫مــن اآلن تقريبــا قابلنــي شــخص يف محافظــة‪ ....‬يدعــى ‪................‬وقــال‬\n      ‫لــي فيــه حجــر ابيــض جــاي مــن ‪ .....‬وهــو يقصــد حبــوب مخــدرة وتقــدر‬\n      ‫كميتهــا بألــف شــد وقــد أغرانــي باملــال وأنه إذا قمت بإحضارها ســوف‬\n      ‫يعطينــي مقابــل ذلــك مائــة وخمســن ألــف ريــال وانــه لــوال حاجتــي املاديــة‬\n      ‫ملــا أقدمــت علــى هــذا األمــر وبعدهــا نتقابــل يف ‪ .....‬وأقــوم بتســليمها لــه‬\n      ‫هنــاك وكان ذلــك علــى مســمع مــن قائــد الفرقــة مــع الرقيــب ‪................‬‬\n\n\n‫‪243‬‬\n\f‫وقــد اخــذ عليــه إقــرار بذلــك عنــد ذلــك مت متكينــه مــن االتصــال علــى‬\n‫املدعــو ‪ ................‬علــى هاتفــه وأفــاده بــأن كل شــيء متــام وأن الوضــع‬\n‫ميشــي علــى مــا يــرام إال أن الشــخص املدعــو ‪................ /‬كان يتضــح‬\n‫مــن كالمــه القلــق وكان يتصــل كل دقيقــة حملاولة كشــف الشــخص‬\n‫وهــي عالمــة دائمــا يف عمليــات التهريــب واالســتقبال عندهــا قــام بإقفال‬\n‫مت تفتيــش‬  ‫جوالــه ولــم نتمكــن مــن مواصلــة ســير القضيــة علمــا بأنــه ّ‬\n‫الســيارة ولــم يعثــر علــى شــيء مــن املمنوعــات عنــد ذلــك مت اصطحابــه‬\n‫إلــى إدارة املكافحــة بالدمــام إلكمــال الــازم بهــذا نشــهد وعليــه نوقــع‬\n‫هكــذا ‪.‬ا‪.‬هــ‪ .‬هكــذا شــهدا ‪ .‬وبعــرض ذلــك علــى املدعــى عليــه قــال ‪:‬‬\n‫مــا ذكــره الشــهود يف شــهادتهم مــن أنهــم قبضــوا علــي يف ســوق اخلضــار‬\n‫فهــذا صحيــح وأمــا مــا ذكــروه يف باقــي شــهادتهم فهــو غيــر صحيــح‬\n‫وأنــا جئــت إلــى الســوق الشــتري خضــار حيــث أنــي ســأخرج إلــى البــر‬\n‫مــع أبنــاء عمــي ولــم آتــي الســتالم البضاعــة التــي ذكروهــا وال أدري‬\n‫عمــا ذكــروه كلــه ‪ .‬وبســؤاله هــل يطعــن يف الشــهود بشــيء قــال ‪ :‬إننــي‬\n‫ال أعرفهــم ‪ .‬وعنــد وصــول القضيــة لهــذا احلــد جــرى رفعهــا إلــى االثنــن‬\n‫القــادم ‪1433/4/19‬ه ـ واهلل املوفــق‪ .‬ويف جلســة أخــرى يــوم االثنــن‬\n‫املوافــق‪ 1433/04/19‬ه ـ حضــر الطرفــان وقــرر املدعــى عليــه أنــه أقــام‬\n‫محامي ـ ًا للدفــاع عنــه ولــم يســتطع احلضــور اليــوم ويطلــب رفــع اجللســة‬\n‫ليتمكــن احملامــي مــن احلضــور ورفعــت اجللســة لذلــك‪ .‬ويف جلســة‬\n‫أخــرى يــوم األربعــاء املوافــق‪ 1433/04/21‬ه ـ حضــر كل مــن ‪........... /‬‬\n‫ســعودي بالســجل رقــم ‪ ........‬و ‪ .........‬ســعودي بالســجل رقــم ‪.........‬‬\n‫وباستشــهادهما شــهدا بعدالــة وثقــة الشــاهدين وأنهمــا صادقــان مقبــوال‬\n‫الشــهادة‪ .‬ويف هــذا اليــوم االثنــن ‪1433/4/26‬ه ـ افتتحــت اجللســة وفيهــا‬\n\n\n                                                                                     ‫‪244‬‬\n\f      ‫حضــر الطرفــان وحضــر وكيــل املدعــى عليــه ‪ .......‬ســعودي اجلنســية‬\n      ‫ا عــن املدعــى عليــه بالوكالــة رقــم ‪.........‬‬ ‫بالبطاقــة رقــم ‪ ..........‬وكي ـ ً‬\n      ‫وتاريــخ ‪1432/10/21‬ه ـ وقــدم مذكــرة دفــاع مكونــة مــن خمــس‬\n      ‫ورقــات ولكــون فضيلــة الشــيخ ‪ .......‬يتمتــع بإجــازة اعتياديــة فقــد جــرى‬\n                                          ‫رفــع اجللســة حلــن مباشــرته وعليــه أجلــت‪.‬‬\n      ‫ويف جلســة أخــرى حضــر الطرفــان وقــد جــرى الرجــوع إلــى املعاملــة‬\n      ‫فوجدنــا علــى اللفــة رقــم ‪ 48‬صــورة مــن شــهادة تصديــر مركبــة صــادرة‬\n      ‫من إدارة املرور بدولة ‪ ....‬وتتضمن أن السيارة ‪ .....‬موديل ‪ ....‬رقم اللوحة‬\n      ‫‪ .......‬تعــود ملكيتهــا ‪ .......‬كمــا وجدنــا علــى اللفــة رقم ‪ 19‬أنه ال ســوابق‬\n      ‫للمدعــى عليــه وبعــرض مــا جــاء يف اقــرار املدعــى عليــه علــى اللفــة رقــم ‪6‬‬\n      ‫قــال ‪ :‬إنهــم غرونــي وقالــوا هــذه إجــراءات توقيفــك عندنــا ‪ .‬فبنــاء علــى‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة وإلنــكار املدعــى عليــه ملــا جــاء يف دعوى‬\n      ‫املدعــي العــام وبنــاء علــى شــهادة الشــاهدين املعدلــن شــرعا املذكــورة‬\n      ‫بعاليــه وبنــاء علــى إقــرار املدعــى عليــه املــدون مضمونــه بعاليــه والــذي‬\n      ‫دفــع املدعــى عليــه بأنــه غــرر بــه فيــه ولــم يقــم بينــة علــى ذلــك وبنــاء‬\n      ‫علــى التقريــر الكيمــاوي املذكــور بعاليــه وبنــاء علــى املــادة التاســعة‬\n      ‫واخلمســن الفقــرة (‪ )1‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقلية‬\n      ‫وبنــاء علــى املــادة (‪ )38‬و (‪ )60‬مــن النظــام نفســه وألن جرميــة املدعــى‬\n      ‫عليــه تتعلــق باملخــدرات التــي تفســد العقــول واألديــان وقــد عــم ضررهــا‬\n      ‫وانتشــر يف كثيــر مــن البلــدان ودمــرت كثيــرا مــن الشــباب والناشــئة‬\n      ‫وقــد كثــر يف اآلونــة األخيــرة ترويجهــا وبيعهــا واســتخدامها والتغريــر‬\n      ‫بهــا ممــا يســتدعي تشــديد العقوبــة علــى مــن تلبــس بهــا أو شــارك يف أي‬\n      ‫مجــال يســبب نشــرها وبثهــا بــن النــاس أشــد التعزيــر وأليــم العقوبــة‬\n\n\n‫‪245‬‬\n\f‫فبنــاء علــى كل مــا تقــدم فقــد قررنــا باإلجمــاع مــا يلــي‪ :‬أوال صرفنــا‬\n‫النظــر عــن دعــوى املدعــي العــام وعــن مطالبتــه بتطبيــق املــادة ‪ 37‬رقــم ‪2‬‬\n‫مــن البنــد أو ًال مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وعــن‬\n‫مطالبتــه بتطبيــق الفقــرة(‪ )1‬مــن املــادة (‪ )53‬مــن النظــام نفســه ‪ .‬ثانيــا‬\n‫‪ :‬ثبــت لدينــا إدانــة املدعــى عليــه بالشــروع يف التوســط أو الشــروع يف‬\n‫نقــل املــواد احملظــورة وقررنــا تعزيــره علــى ذلــك بالســجن عشــر ســنوات‬\n‫تبــدأ مــن تاريــخ إيقافــه وجلــده ألــف جلــدة مفرقــة علــى عشــرين دفعــة‬\n‫كل دفعــة خمســون جلــدة بــن كل دفعــة وأخــرى عشــرة أيــام علــى‬\n‫أن تكــون الدفعــة األولــى واألخيــرة معلنــة أمــام جامــع ‪ .........‬بالدمــام‬\n‫كمــا قررنــا إلزامــه بدفــع غرامــة ماليــة قدرهــا خمســون ألــف ريــال‬\n‫تــودع يف بيــت مــال املســلمني كمــا قررنــا منعــه مــن الســفر خلــارج البــاد‬\n‫مــدة مماثلــة ملــدة ســجنه وبذلــك كلــه حكمنــا ‪ .‬وبعــرض ذلــك علــى‬\n‫الطرفــن قــررا عــدم قناعتهمــا باحلكــم وأفهمــا بتقــدمي اعتراضيهمــا‬\n‫خــال املــدة احملــددة بعــد اســتالمهما نســخة احلكــم وبــاهلل التوفيــق‪.‬‬\n                                                      ‫حــرر يف ‪1433/6/2‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق‪ 1434/03/10‬ه ـ‬\n‫افتتحــت اجللســة بنــاء علــى عــودة املعاملــة مــن محكمــة االســتئناف‬\n‫برقــم ‪ ..........‬يف ‪1433/12/27‬ه ـ املقيــدة باحملكمــة برقــم ‪.........‬‬\n‫يف ‪1434/1/4‬ه ـ وبرفقهــا قــرار أصحــاب الفضيلــة قضــاة الدائــرة‬\n‫اجلزائيــة اخلماســية األولــى رقــم ‪ ...........‬يف ‪1433/12/20‬ه ــاملتضمن‬\n‫مــا ملخصــه بعــد املقدمــة (وبدراســة القــرار وصــورة ضبطــه والالئحتــن‬\n‫االعتراضيتــن وأوراق املعاملــة لوحــظ أنــه ذكــر أصحــاب الفضيلــة يف‬\n‫حكمهــم مــا نصــه ثبــت لدينــا إدانــة املدعــى عليــه بالشــروع يف التوســط‬\n\n\n                                                                                     ‫‪246‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":231,"source_page_end":246,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ad3f1fbce58b020e58f030affc64366b789de93fe4b9439e4f3ca2d0360671ee","normalized_text_hash":"b93e18c61227bc71d2aed64877d76773bd69b8ac4363353af134dc3a99beae77","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p231-33297549"},{"id":"48dac714-904a-59f2-b2da-0f3f3ebc7694","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج عدد من احلبوب احملظورة -تعاطي احلبوب احملظورة -اإلقرار -عقوبة مشددة كون املتهم عسكري -التعزير بالسجن واجللد والغرامة واملنع من السفر واملصادرة وإعادة املبلغ","document_number":"347121","case_number":"3410623","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/01/10","year":"1434","subject":"مخدرات -ترويج عدد من احلبوب احملظورة -تعاطي احلبوب احملظورة -اإلقرار -عقوبة مشددة كون املتهم عسكري -التعزير بالسجن واجللد والغرامة واملنع من السفر واملصادرة وإعادة املبلغ","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 347121 :‬تاريخه ‪1433/01/10 :‬هـ‬\n                           ‫رقم الدعوى ‪3410623:‬‬\n                    ‫رقم قرار التصديق من محكمة‬\n        ‫االستئناف‪ 34174231:‬تاريخه‪1434/03/29:‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬ترويــج عــدد مــن احلبــوب احملظــورة ‪ -‬تعاطــي احلبــوب‬\n       ‫احملظــورة ‪ -‬اإلقــرار ‪ -‬عقوبــة مشــددة كــون املتهــم عســكري ‪ -‬التعزيــر‬\n       ‫بالســجن واجللــد والغرامــة واملنــع مــن الســفر واملصــادرة وإعــادة املبلــغ‬\n                                                                             ‫احلكومــي‪.‬‬\n\n\n\n\n                    ‫ض َب ْع َد ِإ ْص َل ِح َها } ‪.‬‬         ‫‪ -1‬قوله تعالى { َو َل ُت ْف ِس ُدوا ِف ْ َ‬\n                                                     ‫ال ْر ِ‬\n                                                              ‫‪ -2‬قوله تعالى { َو َال ُت ْل ُقو ْا ِب َأ ْيدِ ُ‬\n                              ‫يك ْم ِإ َلى ال َّتهْ ُل َك ِة } ‪.‬‬\n       ‫‪ -3‬املــواد (‪ )2/3‬و(‪)1/38‬و (‪)1/56‬و(‪ )1/53‬مــن نظــام مكافحــة املخدرات‬\n                                                                                           ‫واملؤثــرات العقلية ‪.‬‬\n\n\n\n       ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بترويــج عــدد مــن احلبــوب‬\n       ‫احملظــورة وتعاطــي احلبــوب املنبهــة احملظــورة ‪ ،‬وطلــب املدعــي العــام‬\n       ‫إثبــات مــا أســند للمدعــى عليــه واحلكــم عليــه بالســجن واجللــد والغرامــة‬\n       ‫واملنــع مــن الســفر ومصــادرة الهاتــف اجلــوال والغاء الشــريحة والزامه برد‬\n       ‫املبلــغ احلكومــي املرقــم تطبيق ـ ًا ألحــكام نظــام مكافحــة املخــدرات‬\n       ‫واملؤثــرات العقليــة ‪ -‬حيــث وردت معلومــات ملكافحــة املخــدرات مــن‬\n       ‫أحــد مصادرهــا الســرية عــن قيــام املدعــى عليه بترويــج احلبوب احملظورة‬\n\n‫‪249‬‬\n\f‫بكميــات كبيــرة ويرتبــط مبجموعــه مــن مروجــي املخــدرات ‪ ،‬وقــد‬\n‫عــرض املدعــى عليــه علــى املصــدر البحــث لــه عــن مشــتري لكميــات‬\n‫كبيــرة مــن احلبــوب احملظــورة ‪ ،‬ومت متكــن املصــدر مــن االتصــال علــى‬\n‫جــوال املدعــى عليــه وطلــب منــه كميــه كبيــرة مــن احلبــوب وأنهــا ألحــد‬\n‫األشــخاص فوافــق املدعــى عليــه ‪ ،‬وكانــت املكاملــة علــى مســمع مــن‬\n‫أفــراد الفرقــة القابضــة ومت تزويــد املصــدر باملبلــغ املرقــم بعــد تفتيشــه‬\n‫ورافقــه قائــد الفرقــة لتمثيــل دور املشــتري واتفقا علــى الكمية ‪ ،‬وطلب‬\n‫املدعــى عليــه أن يكــون االســتالم والتســليم يف يــوم الغــد ‪ ،‬ويف اليــوم‬\n‫احملــدد اتصــل املدعــى عليــه باملصــدر وأخبــره بأنــه متواجــد يف منزلــه‬\n‫وحضــر إليــه املصــدر يرافقــه قائــد الفرقــة (ممثــل دور املشــتري) فســلمه‬\n‫ســتمائة ريــال واســتلم مــن املدعــى عليــه عــدد (‪ )22‬حبــة مــن حبــوب‬\n‫اإلمفيتامــن ‪ ،‬وطلــب املدعــى عليــه مــن املصــدر ومرافقــه االتصــال بــه‬\n‫بعــد يومــن إلخبــاره إن كانــت احلبــوب التــي ســلمها جيــدة لتســليمهما‬\n‫باقــي الكميــة املتفــق عليهــا وجــرى االتصــال علــى املدعى عليــه فاعتذر‬\n‫مــن تســليم الكميــة لشــكه بالوضــع ‪ -‬مت مراقبــة منزلــه وبعــد يومــن‬\n‫تقابــل املدعــى عليــه مــع أحــد األشــخاص وركــب معــه واجتهــا للطريــق‬\n‫الســريع فتــم االســتعانة بالدوريــات األمنيــة الســتيقافهما ومت القبــض‬\n‫علــى املدعــى عليــه ‪ ،‬أقــر املدعــى عليــه بتعاطــي حبــوب اإلمفيتامــن‬\n‫وأنكــر مــا عــداه وصــدر احلكــم بإثبــات إدانــة املدعــى عليــه ببيــع (‪)22‬‬\n‫حبــة مــن حبــوب اإلمفيتامني بقصد االجتــار وتعاطيه لهذه احلبوب‪،‬وبناء‬\n‫علــى مــا تقــدم حكمــت احملكمــة بتعزيــره بالســجن واجللــد والغرامــة‬\n‫واملنــع مــن الســفر ومصــادرة الهاتــف اجلــوال وشــريحته وإلزامــه بإعــادة‬\n            ‫املبلــغ احلكومــي وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n                                                                                    ‫‪250‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫مبحافظــة القطيــف وبنــاء علــى املعاملــة احملالــة مــن فضيلــة الرئيــس‬\n      ‫برقــم ‪ ......‬وتاريــخ ‪1434/1/6‬ه ـ املقيــدة باحملكمــة برقــم ‪ ......‬وتاريــخ‬\n      ‫‪ 1434/1/6‬ه ـ واملتعلقــة بدعــوى املدعــي العــام ‪ ......‬ضــد‪ ،......‬حامــل‬\n      ‫الســجل املدنــي رقــم ( ‪ ) ......‬ففــي يــوم الســبت ‪1434/ 1 / 10‬ه ـ فتحــت‬\n      ‫اجللســة الســاعة ‪ 10 : 15‬وفيهــا حضــر املدعــي العــام واملدعــى عليــه‬\n      ‫املدونــة هويتــه بعاليــه وقــدم املدعــي العــام الئحــة الدعــوى املتضمنــة مــا‬\n      ‫يلــي ‪( :‬بصفتــي مدعيـ ًا عامــا يف دائــرة اإلدعــاء العــام مبحافظــة القطيــف‬\n      ‫أدعي على‪ ، ...... :‬البالغ من العمر (‪ )25‬ســنة س ــعودي اجلنســية مبوجب‬\n      ‫الســجل املدنــي رقــم (‪ )......‬محصــن ‪ ،‬عســكري ‪ ،‬أوقــف بتاريــخ‬\n      ‫‪1433/11/22‬ه ـ ‪ ،‬وأحيــل لســجن محافظــة القطيــف اســتناد ًا للقــرار‬\n      ‫الــوزاري رقــم (……) وتاريــخ ‪1428/7/9‬هــ‪ .‬حيــث انــه بتاريــخ‬\n      ‫‪1433/11/14‬ه ـ وردت معلومــات لرجــال مكافحــة املخــدرات بالدمــام‬\n      ‫مــن احــد مصادرهــم الســرية عــن قيــام املدعــى عليــه بترويــج احلبــوب‬\n      ‫احملظــورة بكميــات كبيــرة ويرتبــط مبجموعــة مــن مروجــي املخــدرات‬\n      ‫بالقطيــف ويعمــل ســائق زورق يف ‪ ،.........................‬وقــد عــرض املدعــى‬\n      ‫عليــه علــى املصــدر البحــث لــه عــن مشــتري لكميــات كبيــرة مــن‬\n      ‫احلبــوب احملظــورة يرغــب يف تصريفهــا ‪ ،‬فتــم متكــن املصــدر مــن‬\n      ‫االتصــال علــى جــوال املدعــى عليــه رقــم (‪ )......‬رقمــه املصنعــي (‪)......‬‬\n      ‫وطلــب منــه حبوب ـ ًا محظــورة فذكــر املدعــى عليــه ان لديــه كميــة مــن‬\n      ‫احلبــوب احملظــورة و يرغــب يف تصريفهــا ‪ ،‬فســأله املصــدر عــن قيمــة‬\n\n‫‪251‬‬\n\f‫الشــد وهــي مائتــي حبــة فأجابــه املدعــى عليــه بــأن قيمــة الشــد ثالثــة‬\n‫آالف ريــال وأنهــا موجــودة يف الوقــت احلالــي فطلــب املصدر شــراء خمســة‬\n‫وعشــرون شــد ًا واخبــره انهــا ألحــد األشــخاص ‪ ،‬فطلــب املدعــى عليــه‬\n‫مــن املصــدر ان يــزوده برقــم هاتــف املشــتري وإبالغــه باالتصــال عليــه او‬\n‫حضــور املصــدر واملشــتري ملنزلــه ‪ ،‬وكانــت املكاملــة علــى مســمع مــن‬\n‫أفــراد الفرقــة القابضــة ‪ -‬فجــرى ترقيــم مبلــغ وقــدره (‪ )2000‬الفــي‬\n‫ريــال و تفتيــش املصــدر تفتيشــا دقيقــا‪ ،‬وقيــام قائــد الفرقــة القابضــة‬\n‫مبرافقتــه لتمثيــل دور املشــتري ومت وتزويدهمــا باملبلــغ املرقــم ‪ ،‬وانتقــا‬\n‫إلــى منــزل املدعــى عليــه وقابــاه ودخــا منزلــه وأثنــاء احلديــث اتفــق‬\n‫قائــد الفرقــة القابضــة مــع املدعــى عليــه علــى الشــراء منــه خمســة‬\n‫وعشــرين شــد ًا فوافــق املدعــى عليــه وذكــر أن الكميــة عنــد احــد‬\n‫أعوانــه بالقطيــف وطلــب ان يكــون االســتالم والتســليم يــوم غــدٍ الثالثاء‬\n‫املوافــق ‪1433/11/16‬ه ـ ‪ ،‬ويف اليــوم احملــدد مت االتصــال عليــه فذكــر‬\n‫انــه عنــد احــد أعوانــه بالقطيــف ‪ ،‬وعنــد الســاعة الواحــدة اتصل املدعى‬\n‫عليــه باملصــدر واخبــره انــه متواجــد برحيمــه مبنزلــه وطلــب حضــور‬\n‫املشــتري لــه فجــرى تفتيــش املصــدر ومرافقــة قائــد الفرقــة القابضــة لــه‬\n‫وانتقــا حتــى وصــا منــزل املدعــى عليــه وبدخولهمــا املنــزل طلــب‬\n‫املدعــى عليــه منهمــا املبلــغ قبــل اســتالم الكميــة فرفــض ممثــل دور‬\n‫املشــتري تســليم املبلــغ قبــل مشــاهدة الكميــة فأجــرى املدعــى عليــه‬\n‫اتصــاال ثــم دخــل املدعــى عليــه داخــل منزلــه واحضــر عــدد (‪ )22‬اثنــن‬\n‫وعشــرين حبــة أثبــت التقريــر الكيمــاوي الشــرعي رقــم () وتاريــخ‬\n‫‪ 1433/11/30‬ه ـ ايجابيــة عينتهــا ملــادة االمفيتامــن املنبهــة احملظــورة ‪،‬‬\n‫وســلمها لقائــد الفرقــة القابضــة وجــرى تســليمه مبلــغ مرقــم وقــدره‬\n\n\n                                                                                  ‫‪252‬‬\n\f      ‫(‪ )600‬ســتمائة ريــال ‪ ،‬وطلــب مــن املصــدر و مرافقــه االتصــال بــه بعــد‬\n      ‫يومــن إلخبــاره ان كانــت احلبــوب التــي ســلمها جيــدة لتســليمهما باقــي‬\n      ‫الكميــة املتفــق عليهــا‪ .‬وبتاريــخ ‪1433/11/20‬ه ـ جــرى االتصــال علــى‬\n      ‫املدعــى عليــه فذكــر أنــه بعملــه وأنــه ســيتصل بــه يــوم غــد لتســليمه‬\n      ‫الكميــة املتفــق عليهــا‪ ،‬ويف اليــوم التالــي جــرى االتصــال عليــه اال انــه‬\n      ‫اعتــذر مــن تســليم الكميــة لشــكه بالوضــع فتــم مراقبــة منزلــه ‪ ،‬ويف‬\n      ‫يــوم االثنــن املوافــق ‪1433/11/22‬ه ـ تقابــل املدعــى عليــه مــع احــد‬\n      ‫األشــخاص وركــب معــه واجتهــا إلــى شــارع ‪ ......‬ثــم عــادا حلــي ‪ ......‬علــى‬\n      ‫طريــق ‪ ......‬فتــم االســتعانة بالدوريــات األمنيــة الســتيقافهما فتــم القبــض‬\n      ‫علــى املدعــى عليــه‪ .‬وباســتجواب املدعــى عليــه اقــر بصحــة واقعــة‬\n      ‫الضبــط‪ ،‬وافــاد انــه قبــل القبــض عليــه بعشــرة أيــام اتصــل بــه املصــدر‬\n      ‫وطلــب منــه حبوب ـ ًا منبهــة وأخبــره أنــه ال ميلكهــا وقــام بتكــرار طلبــه‬\n      ‫عــدة مــرات‪ ،‬وألنــه يطالــب املصــدر مببلــغ (‪)700‬ريــال كســلفة فطلــب‬\n      ‫منــه أن يحضــر إليــه مبنزلــه وعنــد حضــور املصدر كان برفقته شــخص‬\n      ‫أخــر وطلــب منــه حبوبـ ًا منبهــة وأصــر علــى طلبــه فأخبــره أنــه إذا عــرف‬\n      ‫أحــد ســيحضر منــه احلبــوب‪ ،‬وبعدهــا بيومــن حضــر املصــدر وبرفقتــه‬\n      ‫الشــخص وطلــب منــه احلبــوب فأخبرهمــا أنــه ال يوجــد لديــه ســوى مــا‬\n      ‫يســتخدمه فقــام وســلم مرافــق املصــدر عــدد (‪ )22‬حبــة مــن احلبــوب‬\n      ‫املنبهــة التــي يتعاطاهــا فقــام مرافــق املصــدر وأخــرج مبلــغ (‪ )600‬ريــال‬\n      ‫وســلمه إياهــا وقــام بإعادتهــا إليــه فأصــر مرافــق املصــدر علــى أن‬\n      ‫يأخذهــا فاســتلمها وغــادر املصــدر ومرافقــه املنــزل ‪ ،‬كما اقــر بتعاطي‬\n      ‫احلبــوب املنبهــة منــذ ســنة وأخــر مــرة كانــت قبــل القبــض عليــه بأســبوع‪.‬‬\n      ‫وقــد انتهــى التحقيــق معــه إلــى توجيــه االتهــام إليــه ببيــع مــا عــدده (‪)22‬‬\n\n\n‫‪253‬‬\n\f‫اثنــن وعشــرين حبــة مــن حبــوب االمفيتامــن املنبهــة احملظــورة بقصــد‬\n‫االجتــار وتعاطــي احلبــوب املنبهــة احملظــورة ‪ ،‬وذلــك لألدلــة والقرائــن‬\n‫التاليــة ‪ -1 :‬مــا ورد باســتجوابه املنــوه عنــه املرفــق علــى اللفــات رقم(‪-12‬‬\n‫‪ -2 . )14‬محاضــر البــاغ و االتصــال و االنتقــال و القبــض والتفتيــش‬\n‫املنــوه عنهــا املدونــة علــى الصفحــات رقــم (‪ )14-12 ، 4 ، 2‬مــن ملــف‬\n‫التحقيــق‪ -3 .‬التقريــر الكيمــاوي الشــرعي املنــوه عنــه املرفــق علــى‬\n‫اللفــة رقــم(‪ .)15‬وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى أي‬\n‫ســوابق‪ .‬وحيــث إن مــا أقــدم عليــه املذكــور ‪ ،‬وهــو بكامــل أهليتــه‬\n‫املعتبــرة شــرع ًا ‪ ،‬فعــل محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا لــذا أطلــب‬\n‫إثبــات مــا أســند اليــه وفــق الفقــرة رقــم(‪ )2‬مــن املــادة رقــم(‪ )3‬مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم عليــه مبــا يلــي‪:‬‬\n‫‪-1‬بعقوبــة الســجن واجللــد والغرامــة الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة‬\n‫رقــم(‪ )38‬مــن النظــام‪ ،‬والتشــديد عليــه كــون املــادة املروجــة حبــوب‬\n‫منبهــة وفــق الفقــرة (‪/2‬ج) مــن املــادة رقــم(‪ )38‬مــن النظــام‪ ،‬و اســتنادا‬\n‫لبرقيــة صاحــب الســمو امللكــي وزيــر الداخليــة رقــم(‪2/8346/5/1‬ش)‬\n‫وتاريــخ ‪1427/2/8‬ه ـ ‪ ،‬و كونــه عســكري اســتناد ًا إلــى برقيتــي‬\n‫صاحــب الســمو امللكــي وزيــر الداخليــة رقم……………‪.‬وتاريــخ‬\n‫‪1429/11/4‬هـ‪ ،‬ورقم ……………‪ .‬وتاريخ ‪1429/2/15‬هـ‪-2 .‬منعه‬\n‫مــن الســفر وفــق الفقــرة رقــم(‪ )1‬مــن املــادة رقــم(‪ )56‬مــن النظــام‪.‬‬\n‫‪-3‬مصــادرة هاتفــه النقــال املســتخدم يف عمليــة الترويــج وفــق الفقــرة (‪)2‬‬\n‫مــن املــادة رقــم (‪ )53‬مــن النظــام ‪ ،‬وعــدم صرف الشــريحة لنفس املدعى‬\n‫عليــه وفق ـ ًا لتعميــم وزيــر الداخليــة رقــم (……………‪ ).‬وتاريــخ‬\n‫‪1428/2/10-9‬هــ‪-4 .‬إلزامــه بدفــع املبلــغ املرقــم الــذي لــم يتــم العثــور‬\n\n\n                                                                                        ‫‪254‬‬\n\f      ‫عليــه وفــق تعميــم وزيــر الداخليــة رقــم (……………‪ ).‬وتاريــخ ‪-22‬‬\n      ‫‪1428/10/23‬هــ‪ .‬وبــاهلل التوفيــق) ا‪ .‬ه ـ وبعــرض الدعــوى علــى املدعــى‬\n      ‫عليــه أجــاب بقولــه مــا جــاء يف الدعــوى مــن اتهامــي بتعاطــي حبــوب‬\n      ‫االمفيتامــن فهــو صحيــح ومــا عــداه فكلــه غيــر صحيــح هــذا جوابــي‬\n      ‫وبعــرض ذلــك علــى املدعــي العــام قــال الصحيــح مــا جــاء يف دعــواي‬\n      ‫وبســؤاله البينــة قــال بينتــي ذكرتهــا يف الدعــوى وأطلــب رصدهــا هــذا‬\n      ‫جوابــي وباالطــاع علــى أدلــة املدعــي العــام وجــدت علــى اللفــات ‪14-12‬‬\n      ‫اســتجوابا للمدعــى عليــه يتضمــن مــا نصــه ‪( :‬س‪ .‬اشــرح لنــا بالتفصيــل‬\n      ‫كيــف مت القبــض عليــك ؟ ج‪ .‬قبــل القبــض علــي بعشــرة أيــام اتصــل بــي‬\n      ‫املصــدر وطلــب منــي حبوبــا منبهــة وأخبرتــه بأنــي ال أملكهــا وقــام‬\n      ‫بتكــرار طلبــه عــدة مــرات‪ ،‬وألنــي أطالــب املصــدر مببلــغ (‪ )700‬ريــال‬\n      ‫كســلفة فطلبــت منــه أن يحضــر إلــى املنــزل وعنــد حضــوره إلــى املنــزل‬\n      ‫كان برفقتــه شــخص آخــر وطلــب منــي حبوبــا منبهــة وأصــر علــى طلبــه‬\n      ‫وأخبرتــه أنــه إذا عرفــت أحــدا ســأحضر منــه احلبوب‪،‬وبعدهــا بيومــن‬\n      ‫حضــر وبرفقتــه الشــخص وطلــب منــي احلبــوب فأخبرتــه أنــه ال يوجــد‬\n      ‫لــدي ســوى مــا أســتخدمه فقمــت وســلمته عــدد اثنــن وعشــرين حبــة مــن‬\n      ‫احلبــوب املنبهــة التــي أتعاطاهــا فقــام مرافــق املصــدر وأخــرج مبلــغ‬\n      ‫ســتمائة ريــال وســلمني إياهــا وقمــت بإعادتهــا إليــه وقــام وأصــر علــي أن‬\n      ‫آخذهــا فاســتلمتها وغــادر املصــدر ومرافقــه املنــزل وبعدهــا بأســبوع‬\n      ‫مــررت بزميــل لــي يف العمــل ليرافقنــي إلــى املعــارض لبيــع كفــرات‬\n      ‫مســتخدمة فتــم اســتيقايف مــن قبــل رجــال مكافحــة املخــدرات ودوريات‬\n      ‫أمنيــة فتــم القبــض علـ ّـي ‪ .‬س ‪ .‬مــا هدفــك مــن بيــع احلبــوب املنبهــة ؟ ج ‪.‬‬\n      ‫ألن املصــدر أصــر علــي أن احضــر لــه حبــوب فقمــت بإعطائــه مــا معــي‬\n\n\n‫‪255‬‬\n\f‫مــن حبــوب ‪ .‬س ‪ .‬ملــاذا اســتلمت املبلــغ مــن املصــدر ومرافقــه ؟ ج ‪ .‬ألن‬\n‫مرافــق املصــدر أصــر علــى أن اســتلم املبلــغ ‪ .‬س ‪ .‬ورد يف محضــر القبــض‬\n‫أنــك اتفقــت مــع املصــدر علــى أن تبيعــه خمســة وعشــرين شــد ًا مــن‬\n‫احلبــوب املنبهــة فمــا قولــك ؟ ج ‪ .‬نعــم صحيــح اتفقــت معــه علــى ذلــك‬\n‫بســبب أنــي أطالــب املصــدر مببلــغ مــن املــال وكلمــا اتصلــت بــه ال يــرد ‪،‬‬\n‫وعندمــا كلمنــي فرحــت باتصالــه وعندمــا طلــب منــي شــدا أجبتــه بأنــي‬\n‫ســأحضر إليــه الشـ ّـد أريــده أن يحضــر إلــى املنــزل ألتفاهــم معــه بشــأن‬\n‫الديــن ولكنــي ال أملــك هــذه الكميــة مــن احلبــوب‪ .‬س ‪ .‬ذكــرت‬\n‫للمصــدر ومرافقــه أنــك تعــرف أحــد األشــخاص بالقطيــف ســتحصل‬\n‫منــه علــى كميــة احلبــوب فمــا قولــك ومــن هــو هــذا الشــخص؟ ج ‪.‬‬\n‫ذكــرت ذلــك ألطمئــن املصــدر ولكنــي ال أعــرف أحــدا ) ا‪.‬ه ـ كمــا‬\n‫وجــدت علــى اللفــة رقــم ‪ 15‬التقريــر الكيمــاوي رقــم ك ش املتضمــن ‪:‬‬\n‫( إيجابيــة العينــة ملــادة االمفيتامــن) ا‪.‬ه ـ وبعــرض األدلــة علــى املدعــى‬\n‫عليــه قــال االســتجواب املرصــود بعاليــه صحيــح وال أنكــر شــيئا منــه‬\n‫هــذا جوابــي فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر‬\n‫املدعــى عليــه مبــا نســب لــه يف االســتجواب وهــو يتضمــن إقــرارا منــه‬\n‫بالترويــج مبقابــل وبنــاء علــى إقــراره يف مجلــس احلكــم بالتعاطي ولقوله‬\n‫تعالــى ‪ ( :‬وال تفســدوا يف األرض بعــد إصالحهــا ) وقولــه ‪ ( :‬وال تلقــوا‬\n‫بأيديكــم إلــى التهلكــة ) وبنــاء علــى املــواد ‪ 2/3‬و ‪ 1/38‬و ‪ 1/56‬و‬\n‫‪ 1/53‬مــن نظــام مكافحــة املخــدرات فقــد حكمــت مبــا يلــي ‪-1 :‬ثبــوت‬\n‫إدانــة املدعــى عليــه ببيــع اثنــن وعشــرين حبــة مــن حبــوب االمفيتامــن‬\n‫املنبهــة احملظــورة بقصــد االجتــار وتعاطــي احلبــوب املنبهــة احملظــورة ‪-2‬‬\n‫معاقبــة املدعــى عليــه للتعاطــي بجلــده ســبعني جلــدة دفعــة واحــدة‬\n\n\n                                                                                     ‫‪256‬‬\n\f      ‫‪-3‬معاقبتــه علــى بيــع املــواد املخــدرة بســجنه مــدة خمــس ســنوات وجلــده‬\n      ‫خمســن جلــدة تتكــرر عليــه عشــر مــرات بــن كل إيقــاع وآخــر خمســة‬\n      ‫عشــر يومــا وتغرميــه خمســة آالف ريــال ومنعــه مــن الســفر بعــد خروجــه‬\n      ‫مــن الســجن مــدة خمــس ســنوات ومصــادرة هاتفــه اجلــوال وعــدم صــرف‬\n      ‫نفــس الشــريحة للمدعــى عليــه ‪ -4‬إلزامــه بتســليم املبلــغ احلكومــي‬\n      ‫وقــدره ســتمائة ريــال وبعــرض احلكــم علــى الطرفــن قنــع بــه املدعــي‬\n      ‫العــام وقــرر املدعــى عليــه عــدم قناعتــه ورغبتــه تقــدمي الئحــة اعتراضيــة‬\n      ‫فجــرى إفهامــه بتعليمــات االســتئناف ففهمهــا كمــا أفهمتــه بــأال‬\n      ‫ينصــرف حتــى يتســلم صــورة مــن احلكــم وبــاهلل التوفيــق وقــد مت االنتهاء‬\n          ‫من حتريره يف متام الساعة ‪ 11 : 00‬من يوم السبت ‪1434/ 1 / 10‬هـ‬\n      ‫احلمد هلل وحده وبعد ففي يوم الثالثاء ‪1434/ 4 / 16‬هـ فتحت اجللسة‬\n      ‫الســاعة ‪ 8 : 00‬وقــد وردتنــا املعاملــة وبرفقهــا قــرار أصحــاب الفضيلــة‬\n      ‫قضــاة محكمــة االســتئناف باملنطقــة الشــرقية رقــم ‪ 34174231‬يف‬\n      ‫‪1434/3/29‬ه ـ املتضمــن املصادقــة علــى احلكــم وبــاهلل التوفيــق وقــد‬\n                                ‫مت االنتهــاء مــن حتريــره يف متــام الســاعة ‪. 8 : 10‬‬\n\n\n\n\n‫‪257‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":249,"source_page_end":257,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3c950e843de7c881b3025da7366152647cab41a6dd02dd97206137298e22a274","normalized_text_hash":"30ef54a676afe08b6b28a5989f84ecac56739d3ed9647b2d6472a49df712a1e8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p249-347121"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"a35e88cd-61e2-56c3-844b-971354eaf9fe","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج وتعاطي -قات -استغالل االبن يف الترويج - شهادة شاهد -قرينة تكذب إنكاره -اإلدانة -التعزير بالسجن والغرامة واملنع من السفر ومصادرة اجلوال .","document_number":"3441850","case_number":"344288","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف وباهلل التوفيق وصلى اهلل وسلم على نبينا محمد","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/19","year":"1434","subject":"مخدرات -ترويج وتعاطي -قات -استغالل االبن يف الترويج - شهادة شاهد -قرينة تكذب إنكاره -اإلدانة -التعزير بالسجن والغرامة واملنع من السفر ومصادرة اجلوال .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 3441850 :‬تاريخه‪1434/02/19:‬ه‬\n                      ‫رقم الدعوى‪344288:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34191328‬تاريخه‪1434/4/17 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬ترويــج وتعاطــي ‪ -‬قــات ‪ -‬اســتغالل االبــن يف الترويــج ‪-‬‬\n‫شــهادة شــاهد ‪ -‬قرينــة تكــذب إنــكاره ‪ -‬اإلدانــة ‪ -‬التعزيــر بالســجن‬\n                     ‫والغرامــة واملنــع مــن الســفر ومصــادرة اجلــوال ‪.‬‬\n\n\n\n\n               ‫‪ -1‬املادة (‪ )3‬من القرار الوزاري رقم(‪ )11‬يف ‪1374/2/1‬هـ ‪.‬‬\n‫‪ -2‬الفقــرة الثانيــة مــن املــادة (‪ )3‬مــن نظــام مكافحة املخــدرات واملؤثرات‬\n                                                                      ‫العقلية‪.‬‬\n‫‪ -3‬الفقــرة (‪-2‬د) مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخدرات واملؤثرات‬\n                                                                      ‫العقلية‪.‬‬\n‫‪ -4‬الفقــرة األولــى مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات‬\n                                                       ‫واملؤثــرات العقليــة‪.‬‬\n‫‪ -5‬الفقــرة األولــى مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات‬\n                                                       ‫واملؤثــرات العقليــة‪.‬‬\n‫‪ -6‬الفقــرة األولــى مــن املــادة (‪ )6‬مــن نظــام مكافحــة املخــدرات واملؤثرات‬\n                                                                      ‫العقلية‪.‬‬\n‫‪ -7‬تعميــم وزيــر العــدل رقــم‪/13‬ت‪ 2832/‬يف ‪1427/2/14‬ه املبنــي علــى‬\n            ‫برقيــة وزيــر الداخليــة رقــم‪ 1/5/7565/2‬يف ‪1427/2/5‬ه ـ ‪.‬‬\n\n\n\n                                                                                   ‫‪190‬‬\n\f      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بترويــج القــات بقصــد البيــع‬\n      ‫وتعاطــي لنوعــه والتغريــر بابنــه وجعلــه وســيلة للترويــج وطلــب إثبــات مــا‬\n      ‫أســند إليــه واحلكــم عليــه بعقوبــة الســجن والغرامــة واملنــع مــن الســفر‬\n      ‫وتعزيــره لقــاء قيامــه بالتغريــر بابنــه وجعلــه وســيلة للترويــج ومصــادرة‬\n      ‫اجلوال املستخدم يف الترويج وإسقاط الشريحة ‪ ،‬حيث مت التنسيق بني‬\n      ‫املصــدر واملدعــى عليــه لشــراء القــات منــه فطلــب مــن املصــدر احلضــور‬\n      ‫ملنزلــه وأن ابنــه الصغيــر ســوف يســلمه القــات وعنــد احلضــور إلــى املنــزل‬\n      ‫خــرج ابــن املدعــى عليــه وســلم املصــدر القــات واســتلم املبلــغ ومت القبــض‬\n      ‫عليــه ومبداهمــة املنــزل وتفتيشــه عثــر علــى املدعــى عليــه كمــا عثــر‬\n      ‫علــى نبــات يشــبه أن يكــون قــات ‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي‬\n      ‫إيجابيــة العينــة املضبوطــة لنبــات القــات احملظــور‪ ،‬وأقــر املدعــى عليــه‬\n      ‫بحيــازة القــات وارســال ابنــه لتســليم القــات وتعاطيــه لــه وأنكــر الترويــج‬\n      ‫والبيــع ‪ ،‬وملــا كانــت بينــة املدعــي العــام شــهادة الشــهود ‪،‬وبنــاء علــى مــا‬\n      ‫تقــدم حكمــت احملكمــة بســجنه ســنتني وتغرميــه عشــرة آالف ريــال‬\n      ‫ومصــادرة هاتفــه اجلــوال وإيــداع ثمنــه لــدى اجلهــة املختصــة مــع إســقاط‬\n      ‫الشــريحة ومنعــه مــن الســفر وقنــع املدعــى عليــه باحلكــم واعتــرض‬\n      ‫‪،‬وصــدق احلكــم مــن محكمة‬     ‫املدعــي العــام مكتفيـ ًا بالئحــة الدعــوى ُ‬\n                                                                            ‫االســتئناف‪.‬‬\n\n\n\n\n‫‪191‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي أنــا‬\n‫‪ .....‬القاضــي باحملكمــة اجلزائيــة بالدمــام بنــاء علــى املعاملــة الــواردة مــن‬\n‫هيئــة التحقيــق واالدعــاء العــام واملقيــدة لــدى احملكمة برقــم ‪3418637‬‬\n‫وتاريــخ ‪1434/1/4‬ه ـ واحملالــة لنــا مــن فضيلة رئيــس احملكمة اجلزائية‬\n‫بالدمــام برقــم ‪ 344288‬وتاريــخ ‪1434/1/4‬ه ـ افتتحــت اجللســة يف يــوم‬\n‫األربعــاء ‪1434/1/28‬ه ـ الســاعة احلاديــة عشــرة والنصــف وفيهــا قــدم‬\n‫املدعــي العــام ‪.....‬دعــواه ونصهــا اآلتــي‪ :‬بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة‬\n‫االدعــاء العــام لفــرع املنطقــة الشــرقية أدعــي علــى‪..... /‬مجهــول الهويــة‬\n‫مبوجــب البطاقــة البديلــة رقــم ‪.....‬حيــث إنــه بتاريــخ ‪1433/11/27‬ه ـ‬\n‫ورود بــاغ لشــعبة مكافحــة املخــدرات مــن أحــد املصــادر الســرية‬\n‫مبعلومــات مفادهــا عــن وجــود املدعــى عليــه يســكن حــي ‪.....‬بالدمــام‬\n‫ويقــوم بترويــج القــات املخــدر ويســتخدم اجلــوال رقــم ‪.....‬عليــه فقــد‬\n‫اســتعد املصــدر بالشــراء منــه واإلطاحــة بــه باجلــرم املشــهود عليــه مت‬\n‫مقابلــة املصــدر ومتكينــه مــن االتصــال علــى املدعــى عليــه علــى هاتفــه‬\n‫وطلــب حزمــة قــات مببلــغ ثالثمائــة ريــال فوافــق املدعــى عليــه وقــال‬\n‫للمصــدر بأنــه ســوف يرســل لــه ولــده الصغيــر لكــي يســلمه احلزمــة‬\n‫وطلــب منــه أن يحضــر إلــى منزلــه وبنــاء علــى مــا ذكــر مت تكليــف أحــد‬\n‫أفــراد الضبــط اجلنائــي مرافقــة املصــدر وتزويدهــم مببلــغ حكومــي‬\n‫مرقــم واالنتظــار عنــد إحــدى البنايــات وبعــد مــرور حوالــي خمــس دقائــق‬\n‫نــزل شــخص صغيــر الســن وتقابــل مــع املصــدر ومرافقــه وقــام بتســليمهم‬\n‫كيــس بداخلــه حزمــة قــات بلــغ وزنهــا (‪ )229‬جــرام وهــي الكميــة‬\n\n                                                                                        ‫‪192‬‬\n\f      ‫املروجــة وقــام باســتالم املبلــغ احلكومــي منهــم وبعدهــا مت متابعــة ابــن‬\n      ‫املــروج للقبــض علــى والــده الــذي كان متواجــد باملنــزل ولكــون االبــن‬\n      ‫متلبــس باجلــرم واســتنادا للمــادة الثالثــة واألربعــون مــن نظــام اإلجــراءات‬\n      ‫اجلزائيــة وباصطحــاب املفتشــة النســائية مت القبــض علــى االبــن داخــل‬\n      ‫املنــزل ومت مداهمــة املنــزل حيــث عثــر علــى والــده داخل املنزل وبتفتيشــه‬\n      ‫شــخصيا لــم يعثــر بحوزتــه علــى أي شــيء مــن املمنوعــات إال أنــه عثــر‬\n      ‫معــه علــى جــوال نــوع اســود اللــون يحمــل الرقــم املصنعــي (‪ ).....‬حيــث‬\n      ‫أتضــح أنــه نفــس الرقــم الــذي مت التنســيق عليــه وبتفتيــش املنــزل عثــر يف‬\n      ‫الثالجــة بداخــل املطبــخ علــى عــدد (‪ )29‬حزمــة يشــتبه أن تكــون القــات‬\n      ‫احملظــور بلــغ إجمالــي وزنهــا جميعــا (‪ )6.100‬جــرام ومبناقشــته أنكــر‬\n      ‫يف بدايــة األمــر إال أنــه أعتــرف الحقــا بأنــه قــد قــام بإرســال ابنــه الــذي‬\n      ‫يدعــى ‪.....‬لتســليم القــات إلــى املصــدر دون معرفة االبــن مبا قام بتوصيله‬\n      ‫وأخــذ عليــه أمــام الفرقــة إقــرار بذلــك مــع العلــم أنــه عثــر علــى املبلــغ‬\n      ‫احلكومــي مــع االبــن قبــل تســليمه لوالــده ومت إطــاق ســراح االبــن يف‬\n      ‫احلــال بعــد إقــرار والــده بترويجــه للقــات دون علــم ابنــه وقــد أثبــت التقرير‬\n      ‫الكيمــاوي الشــرعي رقــم (‪ ).....‬وتاريــخ ‪1433/12/5‬ه ـ ايجابيــة‬\n      ‫العينــات املضبوطــة واملروجــة لنبــات القــات احملظــور واملــدرج علــى‬\n      ‫الفقــرة رقــم (‪ )5‬مــن اجلــدول رقــم (‪ )4‬مــن نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة وباســتجواب املدعــى عليــه أقــر بأنــه قــام بترويــج‬\n      ‫حزمــة مــن القــات حيــث قــام بإرســال ابنــه الصغيــر الــذي يبلــغ مــن العمــر‬\n      ‫(‪ )12‬ســنة وطلــب منــه تســليم هــذه احلزمــة لشــخص ثــم مت القبــض عليــه‬\n      ‫كمــا ضبــط يف منزلــه علــى (‪ )29‬تســعة وعشــرون حزمــه مــن القــات‬\n      ‫وهــي عائــدة لــه لقصــد االســتخدام كمــا أقــر بأنــه تعاطــى القــات‬\n\n\n‫‪193‬‬\n\f‫وكان ذلــك قبــل القبــض عليــه بأســبوع وانتهــى التحقيــق إلــى توجيــه‬\n‫االتهــام للمدعــى عليــه بترويــج مــا وزنــه (‪ )229‬مائتــان وتســعة وعشــرون‬\n‫جرام ـ ًا و حيــازة (‪ )29‬تســعة وعشــرين حزمــة بلــغ إجمالــي وزنهــا‬\n‫(‪ )6.100‬ســتة كيلــو ومائــة جــرام مــن القــات املخــدر بقصــد البيــع و‬\n‫تعاطــي لنوعــه والتغريــر بأبنــه وجعلــه وســيلة للترويــج ‪:‬وذلــك لألدلــة‬\n‫والقرائــن التاليــة‪ -1 :‬مــا جــاء يف اقــراره مبحضــر االســتجواب املنــوه‬\n‫عنــه واملرفــق علــى اللفــات رقــم (‪ -2 )15-14-2‬مــا جــاء يف محاضــر‬\n‫البــاغ واالتصــال والقبــض والتفتيــش واملدونــة علــى اللفــات رقــم (‪-13‬‬\n‫‪ )2-4-12‬مــن ملــف ضبــط اجــراءات االســتدالل ‪ -3‬مــا جــاء يف التقريــر‬\n‫الكيماوي الشــرعي املشــار اليه واملرفق على اللفة رقم (‪ )20‬وبالبحث‬\n‫عــن ســوابقه لــم يعثــر لــه أي ســابقة وحيــث إن مــا أقــدم عليــه املذكــور‬\n‫وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محـ ّـرم ومعاقــب عليــه شــرع ًا‬\n‫أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه مبــا يلــي‪ -1 :‬بعقوبــة الســجن‬\n‫والغرامــة واملنــع مــن الســفر الــواردة باملــادة الثالثــة مــن القــرار رقــم‬\n‫(‪ )2057‬وتاريــخ ‪1404/5/26‬ه ـ ووفق ـ ًا للقــرار الــوزاري رقــم (‪)11‬‬\n‫الصــادر بتاريــخ ‪1374/2/1‬ه ـ لقــاء قيامــه بترويــج القــات وبحيازتــه‬\n‫بقصــد البيــع وقيامــه وتعاطيــه لنوعــه ‪ -2‬بعقوبــة تعزيريــة تزجــره وتــردع‬\n‫غيــره لقــاء قيامــه بالتغريــر بابنــه الصغيــر وجعلــه وســيلة للترويــج‬\n‫‪-3‬مصــادرة الهاتــف اجلــوال العائــد للمدعــى عليــه والــذي مــن نــوع أســود‬\n‫والــذي يحمــل الرقــم املصنعــي رقــم (‪ ).....‬ويحمــل رقــم االتصــال (‪).....‬‬\n‫الســتخدامه يف الترويــج وفقــا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )53‬مــن‬\n‫نظــام مكافحــة املخــدرات مــع املطالبــة بإســقاط شــريحة الهاتــف‬\n‫النقــال وعــدم صرفهــا لنفــس املدعــى عليــه وفقــا لتعميــم ســمو وزيــر‬\n\n\n                                                                                     ‫‪194‬‬\n\f      ‫الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1429/2/10-9‬ه ـ هكــذا ادعــى‬\n      ‫ا مــا ذكــره املدعــي‬   ‫وبعــرض الدعــوى علــى املدعــى عليــه أجــاب قائ ـ ً‬\n      ‫العــام مــن قيامــي بحيــازة القــات وإرســال ابنــي لتســليم القــات للمصــدر‬\n      ‫فذلــك صحيــح ولــم أقصــد البيــع علــى املصــدر وإمنــا إعــادة بعــض القــات‬\n      ‫لــه حيــث إنــه ســيتلف وهــو مــن باعــه علــي ولــم أتفــق معــه عندمــا تصــل‬\n      ‫بــي علــى بيــع القــات ولــم أتفــاوض معــه علــى البيع هكذا أجــاب وبعرض‬\n      ‫ذلــك علــى املدعــي العــام قــال مــا ذكــره املدعــى عليــه غيــر صحيــح‬\n      ‫والصحيــح مــا ذكــرت يف دعــواي مــن قيامــه بالتفــاوض علــى البيــع‬\n      ‫هكــذا أجــاب ثــم جــرى ســؤال املدعــي العــام البينــة علــى دعــواه فقــال‬\n      ‫أطلــب مهلــة إلحضارهــا ويف جلســة أخــرى حضــر الطرفــان ثــم جــرى‬\n      ‫ســؤال املدعــي العــام عــن البينــة علــى دعــواه فقــال إننــي أحضــرت معــي‬\n      ‫الشــاهد‪.....‬وأطلب ســماع مــا لديــه وبســؤال الشــاهد عــن شــهادته قــال‪:‬‬\n      ‫( أشــهد بــاهلل أننــي كنــت مــع املصــدر وأنــه مت متكــن املصــدر مــن‬\n      ‫االتصــال علــى جــوال املدعــى عليــه وطلــب منــه حزمــة قــات مببلــغ‬\n      ‫ثالثمائــة ريــال فوافــق املدعــى عليــه وقــال للمصــدر بأنــه ســوف يرســل لــه‬\n      ‫ولــده الصغيــر لكــي يســلمه احلزمــة وطلــب منــه أن يحضــر إلــى منزلــه‬\n      ‫وبنــاء علــى ذلــك مت تزويــد املصــدر باملبلــغ احلكومــي املرقــم وقــدره‬\n      ‫ثالثمائــة ريــال ثــم قمنــا باالنتظــار عنــد إحــدى البنايــات وبعــد مــرور‬\n      ‫حوالــي خمــس دقائــق نــزل طفــل صغيــر الســن وتقابــل مــع املصــدر وقــام‬\n      ‫بتســليمه كيــس بداخلــه حزمــة قــات بلــغ وزنهــا (‪ )229‬جــرام وهــي‬\n      ‫الكميــة املروجــة وقــام باســتالم املبلــغ احلكومــي منــه) هكــذا شــهد‬\n      ‫وبعــرض الشــاهد وشــهادته علــى املدعــى عليــه قــال أمــا الشــاهد فــا‬\n      ‫أعرفــه وشــهادته غيــر صحيحــة هكــذا أجــاب ثــم جــرى ســؤال املدعــي‬\n\n\n‫‪195‬‬\n\f‫العــام هــل لديــه زيــادة بينــة فقــال ال توجــد لــدي بينــة ســوى مــا قدمتــه‬\n‫وأطلــب الرجــوع إلــى املعاملــة ثــم جــرى ســؤال املدعــي العــام املزكــن‬\n‫للشــاهد فقــال إننــي أحضرتهمــا معــي وهمــا ‪.....‬و‪.....‬وبســؤالهما عــن‬\n‫الشــاهد قــال كل واحــد منهمــا مبفــرده( إننــي أعــرف الشــاهد ‪ .....‬وهــو‬\n‫عــدل ثقــة مقبــول الشــهادة يف الديــن واملــروءة) هكــذا شــهدا ثــم جــرى‬\n‫رفــع اجللســة لالطــاع علــى املعاملــة ويف يــوم األربعــاء ‪1434/02/13‬ه ـ‬\n‫افتتحــت اجللســة وفيهــا حضــر الطرفــان ثــم جــرى ســؤال املدعــى عليــه‬\n‫ا نعــم قــد تعاطيــت القــات احملظور‬   ‫هــل قــام بتعاطــي القــات فأجــاب قائـ ً‬\n‫وحيازتــي لــه ألجــل التعاطــي فقــط هكــذا أجــاب ثــم الرجــوع إلــى‬\n‫املعاملــة فوجــدت علــى لفــة رقــم (‪ )1‬ملــف ضبــط إجــراءات ص (‪)13-12‬‬\n‫محضــر واقعــة قبــض وضبــط وتفتيــش املتضمــن طبــق مــا ذكــر املدعــي‬\n‫العــام يف دعــواه كمــا وجــدت علــى لفــة رقــم (‪ )18-16‬كــرت بصمــات‬\n‫املدعــى عليــه املتضمــن وجــود ســابقة حيــازة واســتعمال قــات كمــا‬\n‫وجــدت علــى لفــة رقــم (‪ )20‬تقرير كيماوي شــرعي رقــم (‪ ).....‬املتضمن‬\n‫ـاء علــى مــا تقــدم‬\n                  ‫ايجابيــة العينــات املرســلة لنبــات القــات احملظــور فبنـ ً‬\n‫مــن دعــوى املدعــي العــام وإجابــة املدعــى عليــه وإقــراره بحيــازة وتعاطــي‬\n‫القــات والتغريــر بابنــه جلعلــه وســيلة لترويــج القــات ومبــا أن املدعــى عليــه‬\n‫ـاء علــى شــهادة الشــاهد املعــدل التعديــل الشــرعي‬    ‫أنكــر الترويــج وبنـ ً‬\n‫ونظــر ًا لوجــود كميــة كبيــرة مــن القــات يف منــزل املدعــى عليــه وهــذه‬\n‫قرينــة تؤيــد دعــوى املدعــي العــام ومــا دفــع بــه املدعــى عليــه مــن كونــه‬\n‫لــم يبــع القــات وإمنــا قــام بــرده عــذر غيــر مقبــول الســيما مــع وجــود كميــة‬\n‫أكبــر منهــا يف منزلــه وهــذه قرينــة تــدل علــى كذبــه وقيامــه بالترويــج‬\n‫ـاء علــى املــادة رقــم (‪ )3‬مــن القــرار الــوزاري رقــم (‪ )11‬الصــادر بتاريــخ‬\n                                                                                ‫وبنـ ً‬\n\n                                                                                          ‫‪196‬‬\n\f      ‫ـاء علــى الفقــرة (‪ )2‬مــن املــادة رقــم (‪ )3‬والفقــرة ( ‪-2‬د‬\n                                                                   ‫‪1374/2/1‬ه ـ وبنـ ً‬\n      ‫) مــن املــادة رقــم (‪ )38‬والفقــرة (‪ )1‬مــن املــادة (‪ )53‬والفقــرة (‪ )1‬مــن‬\n      ‫املــادة رقــم (‪ )56‬والفقــرة (‪ )1‬مــن املــادة رقــم (‪ )62‬مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة وبنــاء علــى تعميــم معالــي وزيــر العــدل رقــم‬\n      ‫‪/13‬ت‪ 2832/‬يف ‪1427/2/14‬ه ـ املبنــي علــى برقيــة صاحــب الســمو‬\n      ‫امللكــي وزيــر الداخليــة رقــم ‪2/7565/5/1‬ش وتاريــخ ‪1427/2/5‬ه ـ‬\n      ‫املتضمــن أن القــات مــن أخــف املــواد املخــدرة ويراعــى عنــد تطبيــق‬\n      ‫العقوبــة مــا نصــت عليــه املــادة (‪ )60‬مــن نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة لــذا كلــه فقــد ثبــت لــدي إدانــة املدعــى عليــه ‪.....‬‬\n      ‫بترويــج مــا وزنــه (‪ )229‬مائتــان وتســعة وعشــرون جرامـ ًا مــن نبــات القات‬\n      ‫احملظــور كمــا ثبــت لــدي حيازتــه لعــدد (‪ )29‬تســعة وعشــرين حزمــة‬\n      ‫قــات بلــغ إجمالــي وزنهــا (‪ )6.100‬ســتة كيلــو ومائــة جرام ـ ًا مــن نبــات‬\n      ‫القــات املخــدر بقصــد البيــع والتعاطــي كمــا ثبــت لــدي تعاطيــه للقــات‬\n      ‫احملظــور والتغريــر بابنــه وجعلــه وســيلة للترويــج وقــررت عقابــه علــى‬\n      ‫ـداء مــن تاريــخ إيقافــه وتغرميــه‬\n                                       ‫ذلــك مبــا يلــي‪ :‬أوالً‪ :‬ســجنه ملــدة ســنتني ابتـ ً‬\n      ‫عشــرة آالف ريــال تدفــع للجهــة املختصــة وذلــك لقــاء بيعــه وحيازتــه‬\n      ‫وتعاطيــه لنبــات القــات احملظــور والتغريــر بابنــه الصغيــر بجعلــه وســيلة‬\n      ‫للترويج‪ .‬ثانياً‪ :‬منعه من الســفر ملدة ســنتني تبدأ بعد انتهاء محكوميته‬\n      ‫املقــررة يف البنــد أوالً‪ .‬ثالث ـاً‪ :‬مصــادرة اجلــوال املوصــوف يف الدعــوى‬\n      ‫وإيداعــه أو ثمنــه لــدى اجلهــة املختصــة مــع إســقاط الشــريحة وعــدم‬\n      ‫صرفهــا لــه‪ .‬وبــكل مــا تقــدم حكمــت وبعــرض احلكــم علــى الطرفــن‬\n      ‫قــرر املدعــى عليــه القناعــة باحلكــم وأمــا املدعــي العــام فقــرر عــدم‬\n      ‫القناعــة باحلكــم وطلــب االســتئناف مكتفي ـ ًا بالئحــة الدعــوى العامــة‬\n\n\n‫‪197‬‬\n\f‫وأمــرت برفــع املعاملــة إلــى محكمــة االســتئناف وبــاهلل التوفيــق وصلــى‬\n                     ‫اهلل وسلم على نبينا محمد‪ .‬حرر يف ‪1434/02/19‬هـ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة القائــم بعمــل رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام‬\n‫برقــم ‪ 34/18637‬وتاريــخ ‪1434/2/24‬ه ـ املقيــدة لــدى احملكمــة برقم‬\n‫‪/34/510538‬ج‪ 1‬وتاريــخ ‪1434/2/30‬ه ـ املرفــق بهــا القــرار الصــادر‬\n‫مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪.....‬املســجل برقــم ‪3441850‬‬\n‫وتاريــخ ‪1434/2/19‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضد‪...../‬مجهــول‬\n‫الهويــة يف قضيــة قــات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو‬\n‫مــدون ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n‫قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                ‫وآلــه وصحبــه وســلم حــرر يف ‪1434/4/17‬هــ‪.‬‬\n\n\n\n\n                                                                                         ‫‪198‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":190,"source_page_end":198,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"be715999a494ee539a77f097ee61783db0cadf7eee55a7c0bfd6e4eb0f10a526","normalized_text_hash":"2da84c3447cd0d5a93ebc2a6ca8d666d37795f7bbae077ed7dfd0527d3d71447","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p190-3441850"},{"id":"6d9ed042-f765-591e-9bec-ae59eae10403","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة -وجود سوابق على املتهم قضى فيها باإلدانة -ندم وتوبة -رد دعوى القتل تعزير ا -غرامة وسجن وجلد -مصادرة ومنع من السفر.","document_number":"3381914","case_number":"3259536","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/02/14","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة -وجود سوابق على املتهم قضى فيها باإلدانة -ندم وتوبة -رد دعوى القتل تعزير ا -غرامة وسجن وجلد -مصادرة ومنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3381914 :‬تاريخه‪1433/02/14 :‬هـ‬\n                           ‫رقم الدعوى ‪3259536:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 3411657‬تاريخه‪1434/1/13 :‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة ‪ -‬وجــود ســوابق علــى املتهــم قضى‬\n       ‫فيهــا باإلدانــة ‪ -‬نــدم وتوبــة ‪ -‬رد دعــوى القتــل تعزيــر ًا ‪ -‬غرامــة وســجن‬\n                                             ‫وجلــد ‪ -‬مصــادرة ومنــع مــن الســفر‪.‬‬\n\n\n\n\n       ‫املــادة (‪ ، )3‬واملــادة (‪ ، )37‬واملــادة (‪ )60‬مــن نظــام مكافحــة املخــدرات‬\n                                                            ‫واﻤﻟﺆﺛﺮات اﻟﻌﻘﻠﻴﺔ‪.‬‬\n\n\n\n\n       ‫أقــام املدعــي العــام دعــواه ضــد املدعــى عليــه طالب ـ ًا إثبــات مــا أســند‬\n       ‫إليــه وفقــا للمــادة ‪ 3‬مــن نظــام اإلجــراءات اجلزائيــة واملــادة ‪ 64‬مــن نظــام‬\n       ‫مكافحــة املخــدرات واملؤثــرات العقليــة وذلــك لقيامــه ببيــع احلبــوب‬\n                    ‫احملظــورة بقصــد الترويــج وتعاطيــه لهــا واحلكــم عليــه بـ ــ‪:‬‬\n       ‫‪ .1‬عقوبــة القتــل املنصــوص عليهــا بالفقــرة اخلامســة مــن البنــد األول مــن‬\n                          ‫املــادة ‪ 37‬مــع مراعــاة مــا تقضــى بــه املــادة ‪ 62‬مــن النظــام‪.‬‬\n       ‫‪ .2‬مصــادرة الســيارة املســتخدمة يف عمليــة الترويــج وفــق الفقــرة (‪ )1‬مــن‬\n                                                                     ‫املــادة ‪ 53‬مــن النظــام‪.‬‬\n       ‫ومبواجهــة املدعــى عليــه أقــر بــكل مــا ورد بالئحــة االدعــاء وأبــدى ندمه‬\n                                                           ‫وتوبتــه عــن األفعــال املذكورة‪.‬‬\n\n‫‪199‬‬\n\f         ‫وبعد أن أطلعت احملكمة على كامل األوراق والتقارير قررت‪:‬‬\n‫‪ .1‬ثبــوت ترويــج املدعــى عليــه وبيــع ‪ 24‬حبــة محظــورة للمــرة الثانيــة‬\n‫والنــزول عــن عقوبــة القتــل لندمــه وتوبتــه وحكمــت بتعزيــره بالســجن ‪5‬‬\n‫ســنوات وجلــده خمســمائة جلــدة وتغرميــه مائــة ألــف ريــال ســعودي ومنعــه‬\n‫مــن الســفر خمــس ســنوات ومصــادرة الســيارة واجلــوال ‪،‬وقنــع املدعــى‬\n‫عليــه واعتــرض املدعــى العــام ‪،‬وجــرى تصديــق احلكــم مــن محكمــة‬\n‫االســتئناف بعــد زيــادة الســجن إلــى ثمــان ســنوات واجللــد إلــى ثمامنائــة‬\n                                     ‫جلــدة ومنعــه مــن الســفر ثمــان ســنوات‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلدينــا نحــن القضــاة باحملكمــة العامــة بالدمــام‬\n‫‪...........‬القائــم بعمــل املكتــب القضائــي ‪ ......................‬وبنــاء علــى‬\n‫املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالدمــام برقــم‬\n‫‪ ...........‬وتاريخ ‪1432/2/28‬هـ واملقيدة باحملكمة برقم ‪ ...........‬وتاريخ‬\n‫‪1432/2/28‬هـ ففي يوم األحد املوافق ‪1432/5/20‬هـ افتتحت اجللسة‬\n‫بخصــوص دعــوى املدعــي العــام ‪ ............ /‬ضــد ‪ ............ /‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...........‬ونصهــا بصفتــي مدعي ـ ًا‬\n‫عامـ ًا بدائــرة االدعــاء العــام لفــرع الهيئــة باملنطقــة الشــرقية أدعــي علــى‬\n‫املذكــور أعــاه حيــث إنــه باالطــاع علــى محاضــر االنتقــال والترقيــم‬\n‫والقبــض والتفتيــش املعــدة مــن قبــل رجــال الضبــط اجلنائــي مبكافحــة‬\n‫املخــدرات تبــن أنــه يف يــوم االثنــن املوافق‪1431/10/18‬ه ـ و بنــاء علــى‬\n‫بــاغ احــد املصــادر عــن وجــود شــخص يدعــى (‪ )...........‬يقــوم بترويــج‬\n‫احلبــوب احملظــورة فتــم بالتنســيق مــع املصــدر لشــراء كميــة مــن احلبــوب‬\n\n                                                                                       ‫‪200‬‬\n\f      ‫احملظــورة و مت متكــن املصــدر مــن االتصــال علــى هاتــف املتهــم و طلــب‬\n      ‫شــراء خمســة وعشــرين حبــة فأجابه املتهــم‪ .........../‬بقولــه طلبك موجود‬\n      ‫ثــم اتفقــا علــى أن يتقابــا بجــوار ســوق الســمك فتم تزويــد املصدر باملبلغ‬\n      ‫املرقم و مت تفتيش املصدر وســيارته أبراء للذمة ومرافقته من قبل أحد‬\n      ‫أفــراد الفرقــة القابضــة ومتركــزت الفرقــة القابضــة يف املوقــع احملــدد‬\n      ‫وبعــد حوالــي ربــع ســاعة حضــرت ســيارة مــن نــوع (‪ ).....‬يف املوقــع احملــدد‬\n      ‫تنطبــق عليهــا نفــس املواصفــات و يقودهــا شــخص تنطبــق عليــه أيضــا‬\n      ‫نفــس املواصفــات و احتــك باملصــدر وقــام املصــدر بالركــوب معه و اخذ‬\n      ‫لفــة صغيــرة حتــت أنظــار الفرقــة القابضــة ثــم قــام بإنــزال املصــدر الــذي‬\n      ‫قــام بتســليم الفــرد املرافــق مــا عــدده (‪ )24‬أربعــة وعشــرون حبــة اثبــت‬\n      ‫التقريــر الكيمــاوي الشــرعي الصــادر مــن املركــز اإلقليمــي ملراقبــة‬\n      ‫الســموم بالشــرقية رقــم (‪ ).........‬و تاريــخ ‪1431/10/26‬ه ـ ايجابيــة عينة‬\n      ‫احلبــوب املروجــة ملــادة االمفيتامــن املــدرج باجلــدول (‪ )2‬فئــة (ب) املرفــق‬\n      ‫بنظــام مكافحــة املخــدرات ‪ .‬و بعدهــا قــام املرافــق بإعطــاء اإلشــارة‬\n      ‫الدالــة علــى امتــام عمليــة الترويــج فتمــت متابعــة املــروج مــن بعــد حتــى‬\n      ‫توقــف بإحــدى احملطــات يف حــي ‪ .....‬و متــت مداهمتــه و بتفتيشــه عثــر‬\n      ‫علــى املبلــغ املرقــم وقــدره (‪ )350‬ريــال يف جيــب ثوبــه العلــوي كامــا‬\n      ‫ومبناقشــته اعتــرف بعمليــه الترويــج وانــه يحضــر احلبــوب مــن شــخص‬\n      ‫بحــي ‪ .....‬فتــم القبــض عليــه ‪ .‬و تبــن أنــه ســبق و أن أديــن يف قضيــة‬\n      ‫ترويــج مبوجــب القــرار الشــرعي رقــم ( ‪ ) 3/84‬و تاريــخ ‪1482/5/19‬ه ـ‬\n      ‫الصــادر مــن محكمــة اجلبيــل و باســتجواب املتهــم اقــر بصحــة واقعــة‬\n      ‫القبــض عليــه مــن قبــل رجــال الضبــط اجلنائــي مبكافحــة املخــدرات‬\n      ‫إثــر بيعــه للحبــوب احملظــورة و اســتالم مقابلهــا ثالثمائــة وخمســون ريــال‬\n\n\n‫‪201‬‬\n\f‫بقصــد الكســب املــادي وتعاطيــه للحبــوب احملظــورة و اخــر مــرة كانت‬\n‫قبــل القبــض عليــه بشــهر مضيفــا ان الســيارة التــي قــام بالترويــج عليهــا‬\n‫تعــود ملكيتهــا لــه و قــد انتهــى التحقيــق إلــى اتهــام املدعــى عليــه باآلتــي‬\n‫‪ -1:‬بيعــه مــا عــدده (‪ )24‬اربعــة وعشــرون حبــة مــن مــادة االمفيتامــن‬\n‫املنبهــة واحملظــورة بقصــد االجتــار للمــرة الثانيــة ‪ -2- .‬تعاطيــه احلبــوب‬\n‫احملظــورة‪ .‬وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬اعترافــه املــدون علــى‬\n‫الصفحــات رقــم (‪ )5-4‬مــن ملــف التحقيــق املرفــق علــى اللفــة رقــم‬\n‫(‪ )1‬واللفــات رقــم (‪ -2 )16-14‬محاضــر البــاغ والترقيــم واالنتقــال‬\n‫والقبــض والتفتيــش املنــوه عنهــا املدونــة علــى الصفحــات رقــم (‪ )3-1‬مــن‬\n‫امللــف املرفــق علــى لفــة (‪ -3- . )1‬التقريــر الكيمــاوي الشــرعي املنــوه‬\n‫عنــه واملرفــق علــى اللفــة رقــم (‪ . )19‬وحيــث إن مــا أقــدم عليــه املدعــى‬\n‫عليــه و هــو بكامــل أهليــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه و‬\n‫مجــرم نظامــا مبوجــب نظــام مكافحــة املخــدرات واملؤثــرات العقليــة يف‬\n‫عقوبــة األصليــة والتكميليــة أطلــب مــا يلــي‪ -:‬أوال‪ :‬إثبــات مــا أســند إليــه‬\n‫وفقــا للمــادة (‪ )3‬مــن نظــام االجــراءات اجلزائيــة و املــادة (‪ )64‬مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة و احلكــم عليــه باآلتــي‪-1:‬‬\n‫بعقوبــة القتــل املنصــوص عليهــا بالفقــرة (اخلامســة) مــن البنــد (االول)‬\n‫مــن املــادة (‪ )37‬مــع مراعــاة مــا تقضــي بــه املــادة (‪ )62‬مــن النظــام ‪-2‬‬\n‫مصــادرة الســيارة التــي مــن نوع ‪ .....‬رقم اللوحــة (‪ )...........‬صنع (‪2004‬م)‬\n‫الســتخدامها مــن قبلــه يف عمليــة الترويــج وفــق الفقــرة (‪ )1‬مــن املــادة‬\n‫(‪ )53‬مــن النظــام‪-3- .‬مصــادرة الهاتــف اجلــوال نــوع ‪ ....‬رقــم م املصنعــي‬\n‫(‪ ).........‬الســتخدامه مــن قبلــه يف إمتــام عمليــة الترويــج وفــق الفقــرة (‪)1‬‬\n‫مــن املــادة (‪ )53‬مــن النظــام وبعــرض دعــوى املدعــي العــام علــى املدعــى‬\n\n\n                                                                                        ‫‪202‬‬\n\f      ‫عليــه أجــاب قائــا كل مــا ورديف الئحــة الدعــوى كلــه صحيــح جملــة‬\n      ‫وتفصيــا وأنــا تائــب إلــى اهلل ونــادم علــى مــا فعلتــه وأقــر أن لــدي ســابقه‬\n      ‫ترويــج مخــدرات حكــم علــي فيهــا هــذه إجابتــي ثــم يف جلســه أخــرى‬\n      ‫لدينــا نحــن القضــاة بهــذه احملكمــة ‪...........‬و ‪...........‬و‪...........‬القائــم‬\n      ‫بعمــل املكتــب القضائــي الثالــث حضــر املدعــي العــام ‪...........‬الســعودي‬\n      ‫بالطاقــة رقــم ‪ ...........‬وحضــر حلضــوره املدعــى عليــه ‪...........‬فتــم الرجــوع‬\n      ‫الــى لفــات املعاملــة ومنهــا محضــر الضبــط اخلــاص بإجــراءات قضيــة‬\n      ‫مخــدرات حتمــل الرقــم ‪ ...........‬وقــد جــاء يف الصفحــة رقــم ‪ 2‬محضــر‬\n      ‫ترقــم مبلــغ ثالثمائــة وخمســن ريــال كمــا جــاء يف الصفحــة رقــم ‪3‬‬\n      ‫محضــر انتقــال وشــراء وقبــض وتفتيــش مــؤرخ ‪1431/10/18‬هـ ـ‬\n      ‫ومضمونــه ورود معلومــات لــدى املديريــة العامــة ملكافحــة املخدرات عن‬\n      ‫قيــام املدعــى عليــه بترويــج احلبــوب املخــدرة وأن أحــد املصــادر اتصــل بــه‬\n      ‫لشــراء خمســه وعشــرين حبــه فأجابــه بوجــود احلبــوب لديــه ثــم اتفــق معــه‬\n      ‫علــى مــكان لتســليمها لــه وانــه يف املــكان احملــدد حضــر املدعــى عليــه‬\n      ‫بســيارة ‪ .....‬حتمــل لوحــة برقــم ‪...........‬فركــب معــه املصــدر بعــد أن مت‬\n      ‫تفتيشــه قبــل ذلــك وســلمه لفــه مبــرأى مــن الفرقــة ثــم عــاد املصــدر وســلم‬\n      ‫للفرقــة اربعــة وعشــرين حبــه وهــي الكميــة املروجــة ثــم متــت متابعــة‬\n      ‫املدعــى عليــه ويف احــدى احملطــات علــى شــارع ‪.........‬مت القبــض عليــه‬\n      ‫وبتفتيشــه عثــر علــى املبلــغ احلكومــي املرقــم يف جيــب ثوبــه العلــوي ولــم‬\n      ‫يعثــر علــى شــيء مــن املمنوعــات معــه او يف ســيارته وقد أقــر املدعى عليه‬\n      ‫يف الصفحــة الرابعــة مــن احملضــر املذكــور أنــه يأخــذ احلبــوب مــن آخــر‬\n      ‫ويبيعهــا بنفــس الثمــن ليتحصــل علــى حبــه أو حبتــن ليتعاطاهــا كمــا‬\n      ‫وجــد يف الصفحــة رقــم ‪ 6‬محضــر حتريــر للحبــوب التــي روجهــا املدعــى‬\n\n\n‫‪203‬‬\n\f‫عليــه كمــا مت االطــاع علــى خطــاب مديــر املركــز اإلقليمــي ملراقبــة‬\n‫الســموم باملنطقــة الشــرقية ويحمــل الرقــم ‪...........‬يف ‪1431/10/26‬ه ـ‬\n‫ومضمونــه ثبــوت إيجابيــة احلبــوب املرســلة ملــادة االمفيتامــن املــدرج يف‬\n‫اجلــدول رقــم ‪ 2‬فئــة ب مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫كمــا مت االطــاع علــى كــرت الســوابق اخلــاص باملدعــى عليــه فتبــن‬\n‫أن عليــه ثــاث ســوابق هــي اســتعمال مخــدرات وحيــازة واســتعمال‬\n‫مخــدرات والثالثــة حيــازة واســتعمال وترويــج مخــدرات كمــا مت‬\n‫االطــاع علــى صــورة القــرار رقــم ‪ ...........‬يف ‪1428/5/19‬ه ـ الصــادر‬\n‫مــن محكمــة اجلبيــل العامــة وختــم علــى الصــورة بختــم طبــق األصــل‬\n‫ومضمــون القــرار املذكــور إدانــة املدعــى عليــه بترويــج عشــر حبــات مــن‬\n‫حبــوب الكبتاجــون احملظــورة عــن طريــق البيــع كمــا وجــد مــن ضمــن‬\n‫لفــات املعاملــة صــورة رخصــة الســير وتثبــت أن الســيارة املســتخدمة‬\n‫ملــك للمدعــى عليــه كمــا جــاء يف صحيفــة الدعــوى يــأن املدعــى عليــه‬\n‫مــن مواليــد ‪1389/5/20‬ه ـ ومســجون بســبب هــذه القضيــة مــن تاريــخ‬\n‫القبــض عليــه ‪1431/10/18‬ه ـ فبنــاء علــى مــا تقــدم وألن املدعــى عليــه‬\n‫أقــر مبــا نســب إليــه يف هــذه الدعــوى مــن ترويجــه ألربعــة وعشــرين حبــه‬\n‫كبتاجــون وأبــدى ندمــه علــى ذلــك الفعــل وملــا يف املخــدرات مــن أضــرار‬\n‫بالغــه وشــرور مســتطيره علــى الفــرد واملجتمــع ولذلــك حرمتهــا الشــريعة‬\n‫املطهــرة وحرمــت تعاطيهــا وترويجهــا األنظمــة الشــرعية ولتكــرار‬\n‫ســوابق املدعى عليه ومنها ســابقة ترويج وملا جاء يف املواد الثالثة واملادة‬\n‫الســابعة والثالثــن مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫ومضمونهــا حتــرمي مــن قــام بترويــج احلبــوب املخــدرة بالبيــع وعقوبــة مــن‬\n‫قــام بذلــك إذا كان الترويــج للمــرة الثانــي بالقتــل تعزيــرا وجــواز النــزول‬\n\n\n                                                                                     ‫‪204‬‬\n\f      ‫عــن عقوبــة القتــل وأســباب تقدرهــا احملكمــة إلــى عقوبــة الســجن التــي‬\n      ‫ال تقــل عــن خمســة عشــر ســنه وباجللــد الــذي ال يزيــد علــى خمســن جلــده‬\n      ‫وبالغرامــة التــي ال تقــل عــن مائــة ألــف ريــال وملــا جــاء يف املــادة الســتني‬\n      ‫مــن النظــام املذكــور مــن أن للمحكمــة ألســباب معتبــره النــزول عــن‬\n      ‫احلــد األدنــى يف هــذه القضيــة وملــا بــدر منهــم أثنــاء محاكمتــه مــن إظهــار‬\n      ‫للنــدم لــكل ذلــك تقــرر مــا يلــي ‪ :‬أوال‪ :‬ثبــت لدينــا ترويــج املدعــى عليــه‬\n      ‫بيــع أربعــه وعشــرين حبــة كبتاجــون وهــذا ترويــج للمــرة الثانيــة ‪ .‬ثانيــا‪:‬‬\n      ‫قررنــا النــزول عــن عقوبــة القتــل ملــا ذكــر يف حيثيــات احلكــم وحكمنــا‬\n      ‫بتعزيــره عوضــا عــن ذلــك بســجنه خمــس ســنوات حتســب منها املــدة التي‬\n      ‫أوقــف فيهــا بســبب هــذه القضيــة وجلــده خمســمائة جلــده علــى عشــر‬\n      ‫دفعــات متســاوية قــدر الدفعــة خمســون جلــده وبــن كل دفعــه والتــي‬\n      ‫تليهــا مــدة شــهر ومصــادرة ســيارته وجوالــه املذكوريــن الســتخدامه‬\n      ‫لهمــا يف هــذه اجلرميــة وتغرميــه مائــة ألــف ريــال ومنعــه مــن الســفر إلــى‬\n      ‫خــارج اململكــة بعــد انتهــاء محكوميتــه مــدة خمــس ســنوات وبعــرض‬\n      ‫احلكــم علــى الطرفــن اعتــرض عليــه املدعــي العــام أمــا املدعــى عليــه‬\n      ‫فقــرر قناعتــه باحلكــم فأفهــم املدعــي العــام بأنــه ســيتم تزويــده بصــوره‬\n      ‫مــن احلكــم لتقــدمي اعتراضــه عليــه خــال ثالثــة أيــام وأن عليــه أن يقــدم‬\n      ‫الئحتــه االعتراضيــة يف مــده ال تتجــاوز ثالثــن هــي مــدة االعتــراض‬\n      ‫كمــا أفهــم بأنــه إن مضــت هــذه املــدة دون أن يقــدم الئحتــه االعتراضيــة‬\n      ‫فســيتم رفــع املعاملــة إلــى محكمــة االســتئناف كاملتبــع بــدون الئحــة‬\n      ‫ففهــم ذلــك ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                           ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1433/2/14‬هــ‪.‬‬\n      ‫تابــع دعــوى املدعــي العــام ضــد ‪...........‬ثــم انــه يف هــذا اليــوم الثالثــاء‬\n\n\n‫‪205‬‬\n\f‫املوافــق ‪1433/10/17‬ه ـ حضــر املدعــي العــام ‪...........‬وحضــر حلضــوره‬\n‫املدعــى عليــه ‪ ...........‬ويف هــذه اجللســة مت اســتعراض قــرار محكمــة‬\n‫االستئناف باملنطقة الشرقية رقم ‪ ...........‬يف ‪1433/6/10‬هـ ومضمونه‬\n‫أن ماحكــم بــه علــى املدعــى عليــه قليــل وذلــك لتعــدد ســوابقه ولعــدم‬\n‫تبريــر أســباب معتبــرة للنــزول لتوافــق مــا جــاء يف املــادة الســتني مــن نظــام‬\n‫مكافحــة املخــدرات وعليــه وملــا ذكــر أصحــاب الفضيلــة يف قرارهــم‬\n‫املذكــور فــإن ســبب النــزول عــن احلــد األدنــى هــو مــا بــدر مــن املدعــى‬\n‫عليــه أثنــاء محاكمتــه مــن النــدم ولقلــة احلبــوب التــي ثبــت ترويجهــا‬\n‫ولتوجيــه أصحــاب الفضيلــة فقــد قررنــا زيــادة الســجن احملكــوم بــه‬\n‫عليــه ثــاث ســنوات واجللــد ثالثمائــة جلــدة مفرقــة وزيــادة مــدة منعــه‬\n‫مــن الســفر إلــى خــارج اململكــة مــدة ثــاث ســنني ولذلــك قررنــا تعديــل‬\n‫الفقــرة الثانيــة مــن احلكــم ليكــون نصهــا كالتالــي ‪.‬ثانيــا قررنــا‬\n‫النــزول عــن عقوبــة القتــل ملــا ذكــر يف حيثيــات احلكــم وحكمنــا‬\n‫بتعزيــره عوضــا عــن ذلــك بســجنه ثمــان ســنوات حتســب منهــا املــدة التــي‬\n‫أوقــف فيهــا بســبب هــذه القضيــة وجلــد ثمامنائــة جلــده علــى ســت عشــرة‬\n‫دفعــة متســاوية قــدر الدفعــة خمســون جلــدة وبــن كل منهــا والتــي تليهــا‬\n‫مــدة شــهر ومصــادرة ســيارته وجوالــه املذكوريــن الســتخدامه لهمــا‬\n‫يف هــذه اجلرميــة وتغرميــه مائــة ألــف ريــال ومنعــه مــن الســفر إلــى خــارج‬\n‫اململكــة بعــد انتهــاء محكوميتــه مــدة ثمــان ســنوات وبعــرض احلكــم‬\n‫علــى الطرفــن ذكــر املدعــي العــام أنــه ال يــزال علــى معارضتــه امــا‬\n‫املدعــى عليــه فقــرر قناعتــه باحلكــم‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/10/17‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعنــا نحــن ق ــضاة الدائـ ــرة اجلزائـي ــة‬\n\n\n                                                                                         ‫‪206‬‬\n\f      ‫اخلماسـي ــة األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبدينــة الدمــام‬\n      ‫برقــم ‪ ...........‬وتاريــخ ‪1433/11/2‬ه ـ واملقيــدة لــدى احملكمــة برقــم‬\n      ‫‪...........‬وتاريــخ ‪1433/11/10‬ه ـ املرفــق بهــا القــرار الشــرعي ذو الرقــم‬\n      ‫‪ ...........‬والتاريــخ ‪1433/2/14‬ه ـ الصــادر مــن أصحــاب الفضيلــة‬\n      ‫القضــاة باحملكمــة الشــيخ‪ .........../‬والشيخ‪.........../‬والشــيخ‪.........../‬‬\n      ‫اخلــاص بدعــوى‪ /‬املدعــي العــام ضــد‪ .........../‬يف قضيــة مخــدرات وقــد‬\n      ‫تضمــن القــرار حكــم أصحــاب الفضيلــة مبــا هــو مــدون ومفصــل فيــه ‪.‬‬\n      ‫وحيــث ســبق دراســة القــرار وصــورة ضبطــه وأوراق املعاملــة وباالطــاع‬\n      ‫علــى مــا أجــاب بــه أصحــاب الفضيلــة علــى قرارنــا رقــم ‪...........‬وتاريــخ‬\n      ‫‪1433/6/10‬ه ـ قررنــا املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر‪.‬‬\n      ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف‬\n                                                                ‫‪ 1434/11/13‬هـ ـ ـ ـ ‪.‬‬\n\n\n\n\n‫‪207‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":199,"source_page_end":207,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"52ac9d2d2c2ae8e7ef8af296dda5695b399704227bfbcbd90808835bc8b8e25d","normalized_text_hash":"dea1beb0360da0ca3a985a4ba6e5351dcff36d0eaaaa4f932e75b7281e285a10","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p199-3381914"},{"id":"ee9565af-5100-5196-886b-f7ef481324a4","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج املخدرات -ترويج الهيروين املخدر -إقرار - التعزير بالسجن و اجللد و الغرامة و اإلبعاد عن الباد و مصادره الهاتف اجلوال وإلغاء الشريحة .","document_number":"34265704","case_number":"3300695","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/11","year":"1434","subject":"مخدرات -ترويج املخدرات -ترويج الهيروين املخدر -إقرار - التعزير بالسجن و اجللد و الغرامة و اإلبعاد عن الباد و مصادره الهاتف اجلوال وإلغاء الشريحة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34265704 :‬تاريخه ‪1434/07/11 :‬هـ‬\n                     ‫رقم الدعوى ‪3300695 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34318256‬تاريخه‪1434/9/14 :‬هـ‬\n\n\n ‫مخــدرات ‪ -‬ترويــج املخــدرات ‪ -‬ترويــج الهيرويــن املخــدر ‪ -‬إقــرار ‪-‬‬\n ‫التعزيــر بالســجن و اجللــد و الغرامــة و اإلبعــاد عــن البــاد و مصــادره‬\n                                      ‫الهاتــف اجلــوال وإلغــاء الشــريحة ‪.‬‬\n\n\n\n\n         ‫‪ .1‬املادة ( ‪ ) 38‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n         ‫‪ .2‬املادة ( ‪ ) 53‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n         ‫‪ .3‬املادة ( ‪ ) 56‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n         ‫‪ .4‬املادة ( ‪ ) 60‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n         ‫‪ .5‬تعميم سمو وزير الداخلية رقم ( ‪ )9778‬يف ‪1428/2/10-9‬هـ‬\n\n\n\n\n ‫ادعــى املدعــي العــام علــى املدعــى عليــه ببيــع جــرام واحــد يحتــوي علــى‬\n ‫مــادة امليثامفيتامــن ‪ ،‬طلــب املدعــي العــام تعزيــر املدعــى عليــه بالســجن‬\n ‫واجللــد والغرامــة واإلبعــاد ومصــادرة الهاتــف اجلــوال وإلغــاء الشــريحة‬\n ‫وذلــك تطبيقـ ًا للمــواد أرقــام (‪ )56( ، )53( ، )38‬مــن نظــام مكافحــة‬\n ‫املخــدرات واملؤثــرات العقليــة ‪ ،‬حيــث توافــرت معلومــات لــدى اجلهــات‬\n ‫األمنيــة عــن قيــام املدعــى عليــه بترويــج الهيرويــن املخــدر‪ ،‬مت االتفــاق‬\n ‫معــه علــى شــراء الهرويــن مببلــغ ألــف ريــال واتفــق علــى املــكان‪،‬‬\n\n                                                                                    ‫‪208‬‬\n\f      ‫وحضــر املدعــى عليــه‪ ،‬وركــب الســيارة ‪ ،‬وأخــرج مــن جيبــه كيــس‬\n      ‫نايلــون بداخلــه مــادة بيضــاء اللــون‪ ،‬يشــتبه أن تكــون مخــدره بلــغ وزنهــا‬\n      ‫جرامــا واحـ ًـدا‪ ،‬فتــم القبــض عليــه قبــل تســلمه املبلــغ املرقــم‪ ،‬وقــد أثبــت‬\n                                                                                       ‫ً‬\n      ‫التقريــر الكيميائــي إيجابيــة العينــة علــى مــادة امليثامفيتامــن املؤثــرة‬\n      ‫عقليــا وأقــر املدعــى عليــه مبــا جــاء يف دعــوى املدعــي العــام وظهــر لناظر‬ ‫ً‬\n      ‫القضيــة ندمــه وتوبتــه وعــدم وجــود ســوابق مســجله بحقــه إضافــة إلــى‬\n      ‫قلــة الكميــة ‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة بإدانــة املدعــى‬\n      ‫عليــه مبــا نســب إليــه بتعزيــر املدعــى عليــه بالســجن و اجللــد واإلبعــاد عــن‬\n      ‫البــاد ومصــادرة اجلــوال وإلغــاء الشــريحة‪ ،‬و النــزول عــن احلــد األدنــى‬\n      ‫للعقوبــة ملقتضــى املــادة ( ‪ )60‬مــن نظــام مكافحــة املخــدرات و املؤثــرات‬\n      ‫العقليــة ‪ ،‬قنــع املدعــى عليــه باحلكــم ‪ ،‬وقــرر املدعــي العــام اعتراضــه‬\n             ‫علــى احلكــم بالئحــة‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..............‬القاضــي يف احملكمــة‬\n      ‫اجلزائيــة مبحافظــة جــدة وبنــاء علــى املعاملــة احملالة لنا مــن فضيلة رئيس‬\n      ‫احملكمــة اجلزائيــة مبحافظــة جــدة برقــم وتاريــخ ‪1434/07/01‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم وتاريــخ ‪1434/06/28‬ه ـ ففــي يــوم األثنــن‬\n      ‫املوافق‪1434/07/10‬ه ـ افتتحــت اجللســة الســاعة ‪ 11 : 00‬وفيهــا حضــر‬\n      ‫املدعــي العــام ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫ومبوجــب التكليــف رقــم ه ـ وتاريــخ ‪1430/12/29‬هـ وادعــى على ‪........‬‬\n      ‫(‪ )30‬عامـ ًا هنــدي اجلنسي ــة مبوجــب البطاقــة البديلــة رقــم ‪ ........‬بتاريــخ‬\n      ‫‪1434/5/4‬ه ـ الصــادرة مــن مكافحــة املخــدرات مبحافظة جدة عاطل‬\n\n‫‪209‬‬\n\f‫موقــوف بالســجن العــام مبحافظــة جــدة مبوجــب أمــر متديــد التوقيــف‬\n‫رقــم ‪ .......‬وتاريــخ ‪1434/5/7‬ه ـ اســتناد ًا للقــرار الــوزاري رقــم (‪)1900‬‬\n‫وتاريــخ ‪1428/7/9‬ه ـ املبنــي علــى املــادة (‪ ) 112‬مــن نظــام اإلجــراءات‬\n‫ا يف دعــواه‪ :‬إنــه بتاريــخ ‪1434/5/4‬ه ـ مت القبــض علــى‬          ‫اجلزائيــة قائ ـ ً‬\n‫املدعــى عليــه مــن قبــل أمــن املهمــات والواجبــات اخلاصــة بشــرطة منطقــة‬\n‫مكــة املكرمــة بعــد توافــر معلومــات عــن ترويجــه للهيرويــن املخــدر‬\n‫ويتواجــد علــى جــوال ومت االتفــاق معــه علــى شــراء الهيرويــن مببلــغ‬\n‫(‪ )1000‬ريــال وباالنتقــال للموقــع املتفــق عليــه حضــر املدعــى عليــه‬\n‫وركــب ســيارة الفــرد وأخــرج مــن جيبــه كيــس نايلــون بداخلــه مــادة‬\n‫بيضــاء يشــتبه أن تكــون مخــدرة بلــغ وزنهــا (‪ )1‬جــرام فتــم القبــض عليــه‬\n‫قبــل تســلمه املبلــغ املرقــم وقــد أثبــت التقريــر الكيميائــي الشــرعي رقــم‬\n‫(‪/1667‬ك ش م) لعــام ‪1434‬ه ـ احتــواء الكميــة املضبوطــة واملرســلة‬\n‫للتحليــل علــى مــادة امليثامفيتامــن املؤثــرة عقليـ ًا املدرجــة باجلــدول رقــم‬\n‫(‪ )2‬فئــة (ب) امللحقــة بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫وباســتجواب املدعــى عليــه اعتــرف مبــا نســب إليــه وأفــاد بأنــه ســلم‬\n‫الكميــة املضبوطــة ألحــد األشــخاص مقابــل خمســن ريــا ًال وأنهــا تعــود‬\n‫لشــخص هنــدي يدعــى (‪ ).....‬ال يعــرف مــكان تواجــده وانتهــى التحقيــق‬\n‫معــه إلــى توجيــه االتهــام إليــه ببيــع جــرام واحــد يحتــوي علــى مــادة‬\n‫امليثامفيتامــن املؤثــرة عقلي ـ ًا بقصــد االجتــار اســتناد ًا للفقــرة (‪ )2‬مــن‬\n‫املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وذلــك‬\n‫لألدلــة والقرائــن املرصــودة يف الئحــة الدعــوى وباالطــاع علــى ســوابقه‬\n‫لــم يعثــر لــه علــى ســوابق جنائيــة مســجلة وحيــث إن مــا أقــدم عليــه‬\n‫املدعــى عليــه فعــل محــرم شــرع ًا ومجــرم نظام ـ ًا طبق ـ ًا للمــادة الثالثــة‬\n\n\n                                                                                        ‫‪210‬‬\n\f      ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n      ‫امللكــي رقــم م‪ 39/‬وتاريــخ ‪1426/7/8‬ه ـ واملعاقــب عليهــا اســتناد ًا‬\n      ‫للمــواد (‪ )59،38‬مــع مراعــاة مــا ورد باملــادة (‪ )62‬مــن ذات النظــام‬\n      ‫لــذا أطلــب إثبــات إدانتــه مبــا نســب إليــه وملعاقبتــه بالعقوبــات األصليــة‬\n      ‫والتكميليــة التاليــة‪ :‬أوالً‪ /‬بالســجن واجللــد والغرامــة اســتناد ًا للفقــرة‬\n      ‫(‪ )1‬مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات املشــار إليــه ثاني ـاً‪/‬‬\n      ‫مصــادرة جهــازه اجلــوال املضبــوط معــه الســتخدامه يف اجلرميــة اســتناد ًا‬\n      ‫للفقــرة (‪ )1‬مــن املــادة (‪ )53‬مــن نظــام وإلغــاء اخلدمــة عــن الشــريحة لســوء‬\n      ‫اســتخدامه وعــدم صرفهــا لــه اســتناد ًا لتعميــم ســمو وزيــر الداخليــة رقــم‬\n      ‫(‪ )9778‬يف ‪1428/2/10-9‬ه ـ ثالث ـاً‪ /‬إبعــاده عــن اململكــة بعــد تنفيــذ‬\n      ‫عقوبتــه وعــدم الســماح لــه بالعــودة إليهــا وفق ـ ًا للفقــرة (‪ )2‬مــن املــادة‬\n      ‫(‪ )56‬مــن النظــام املشــار إليــه هكــذا ادعــى املدعــي العــام وبعرضــه على‬\n      ‫ا وهــو يعــرف العربيــة‪ :‬مــا ذكــره املدعــي العــام‬   ‫املدعــى عليــه أجــاب قائـ ً‬\n      ‫مــن قيامــي ببيــع جــرام واحــد يحتــوي علــى مــادة امليثامفيتامــن املؤثــرة‬\n      ‫عقلي ـ ًا بقصــد االجتــار صحيــح وأنــا نــادم علــى مــا بــدر منــي وتائــب هلل‬\n      ‫ثــم جــرى منــي االطــاع علــى أوراق املعاملــة وملــف التحقيــق ومــا ورد‬\n      ‫يف اعترافــه املــدون مبلــف االســتجواب لفــة (‪ )18-16‬ومــا ورد مبحضــر‬\n      ‫الضبــط لفــة ( ‪ ) 2-1‬ومــا ورد بالتقريــر الكيميائــي الشــرعي رقــم ()‬\n      ‫لعــام ‪1434‬ه ـ لفــة (‪ )19‬املتضمــن احتــواء الكميــة املضبوطــة واملرســلة‬\n      ‫للتحليــل علــى مــادة امليثامفيتامــن املؤثــرة عقلي ـ ًا فبنــاء علــى مــا تقــدم‬\n      ‫مــن الدعــوى واإلجابــة واإلقــرار وملــا ظهــر لــي مــن ندمــه وتوبتــه وعــدم‬\n      ‫وجــود ســوابق مســجلة عليــه ونظــر ًا لقلــة الكميــة فقــد ثبــت لــدي إدانــة‬\n      ‫املدعــى عليــه مبــا أســند إليــه وحكمــت عليــه مبــا يلــي‪-1 :‬ســجنه ملــدة‬\n\n\n‫‪211‬‬\n\f‫ســنة يحتســب منهــا مــدة إيقافــه علــى ذمــة هــذه القضيــة وجلــده خمســن‬\n‫جلــدة مكــررة ثمانــي مــرات بــن كل مــرة وأخــرى مــا ال يقــل عــن‬\n‫أســبوع وتغرميــه ( ‪ ) 1000‬ريــال اســتناد ًا للمــادة ( ‪ ) 60 ،38‬مــن نظــام‬\n‫مكافحــة املخــدرات ‪ -2‬إبعــاده خلــارج اململكــة بعــد االنتهــاء مــن تنفيــذ‬\n‫عقوبتــه وعــدم الســماح لــه بالعــودة إليهــا ومنعــه مــن دخولهــا اســتناد ًا‬\n‫للمــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات املشــار إليــه ‪ -3‬مصــادرة‬\n‫جهــازه اجلــوال املضبــوط معــه الســتخدامه يف اجلرميــة اســتناد ًا للفقــرة (‪)1‬‬\n‫مــن املــادة (‪ )53‬مــن نظــام وإلغــاء اخلدمــة عــن الشــريحة لســوء اســتخدامه‬\n‫وعــدم صرفهــا لــه اســتناد ًا لتعميــم ســمو وزيــر الداخليــة رقــم (‪)9778‬‬\n‫يف ‪1428/2/10-9‬ه ـ وبجميــع ذلــك حكمــت وبعرضــه علــى املدعــى‬\n‫عليــه قــرر قناعتــه باحلكــم فيمــا طلــب املدعــي العــام رفعهــا حملكمــة‬\n‫االســتئناف بالئحــة تقــدم خــال ثالثــن يومـ ًا مــن تاريــخ تســجيل القــرار‬\n‫وإال ســقط حقــه يف االعتــراض ورفعــت دون الئحــة وعليــه جــرى التوقيــع‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                               ‫‪1434/07/10‬ه ـ‬\n           ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد ‪-:‬‬\n‫فقــد جــرى منــا نحــن قضــاة االســتئناف بالدائــرة اجلزائيــة السادســة‬\n‫مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة جــرى منــا اإلطــاع‬\n‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة‬\n‫جــدة برقــم (‪ )....‬وتاريــخ (‪1434/9/6‬هــ) املرفــق بهــا القــرار الصــادر‬\n‫مــن فضيلــة الشــيخ‪ /‬القاضــي باحملكمــة اجلزائيــة بجــدة برقــم (‪)....‬‬\n‫وتاريــخ (‪1434/7/11‬هــ) املتضمــن دعــوى املدعــي العــام ضــد‪....../‬‬\n‫هنــدي اجلنســية املتهــم يف مخــدرات‪ ،‬احملكــوم فيــه مبــا دون باطنــه‪،‬‬\n\n\n                                                                                     ‫‪212‬‬\n\f      ‫وبدراســة القــرار وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة‬\n      ‫علــى احلكــم‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                 ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪213‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":208,"source_page_end":213,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2e87e2c45b101d8c08c764bdda1181efd2f5572a5e9437a6d8d3698cd8976e92","normalized_text_hash":"e3482445e50a3cfb42c171515d88cb2c185ad2644677601652a199776ae14345","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p208-34265704"},{"id":"8e2a0c50-9ddd-51d2-b2be-b8917cf0a8a4","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر -ترويج اخلمر املسكر -حيازة املسكر -حيازة احلشيش املخدر -حيازة عدد من حبوب محظورة -شرب املسكر -تعاطي احلشيش -تعاطي احلبوب احملظورة - احليازة بقصد التعاطي والترويج -إقامة حد املسكر -التعزير بالسجن واجللد والغرامة واملنع من السفر واملصادرة وإعادة املبلغ","document_number":"3432371","case_number":"3319993","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/9","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر -ترويج اخلمر املسكر -حيازة املسكر -حيازة احلشيش املخدر -حيازة عدد من حبوب محظورة -شرب املسكر -تعاطي احلشيش -تعاطي احلبوب احملظورة - احليازة بقصد التعاطي والترويج -إقامة حد املسكر -التعزير بالسجن واجللد والغرامة واملنع من السفر واملصادرة وإعادة املبلغ","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 3432371 :‬تاريخه ‪1434/02/9 :‬هـ‬\n                   ‫رقم الدعوى ‪3319993 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34191153‬تاريخه‪1434/4/22 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬ترويــج احلشــيش املخــدر ‪ -‬ترويــج اخلمــر املســكر ‪ -‬حيــازة‬\n‫املســكر ‪ -‬حيــازة احلشــيش املخــدر ‪-‬حيــازة عــدد مــن حبــوب محظــورة‬\n‫‪ -‬شــرب املســكر ‪ -‬تعاطــي احلشــيش ‪ -‬تعاطــي احلبــوب احملظــورة ‪-‬‬\n‫احليــازة بقصــد التعاطــي والترويــج ‪ -‬إقامــة حــد املســكر ‪ -‬التعزيــر‬\n‫بالســجن واجللــد والغرامــة واملنــع مــن الســفر واملصــادرة وإعــادة املبلــغ‬\n                                                                      ‫احلكومــي‪.‬‬\n\n\n\n‫‪ -1‬الفقــرة (‪ )2‬مــن املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                    ‫العقليــة‪.‬‬\n‫‪ -2‬الفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                    ‫العقليــة‪.‬‬\n        ‫‪ -3‬الفقرة (‪ )53‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n‫‪ -4‬الفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                    ‫العقليــة‪.‬‬\n‫‪ -5‬الفقــرة (‪ )1‬مــن املــادة (‪ )62‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                    ‫العقليــة‪.‬‬\n\n\n\n\n                                                                                   ‫‪214‬‬\n\f      ‫ادعــى املدعــي العــام علــى املدعــى عليــه ببيــع قطعــة مــن احلشــيش بقصــد‬\n      ‫االجتــار وترويجــه لزجاجتــن مــن املســكر وحيــازة خمــس زجاجــات مــن‬\n      ‫املســكر وعــدد ثــاث قطــع مــن احلشــيش وعــدد (‪ )37‬حبــة مــن حبــوب‬\n      ‫الكلوفازيبــام احملظــورة بقصــد التعاطــي والترويــج وشــرب املســكر‬\n      ‫وتعاطــي احلشــيش واحلبــوب احملظــورة حيــث ورد بــاغ لشــعبة مكافحــة‬\n      ‫املخــدرات مــن أحــد مصادرهــا عــن قيــام املتهــم بترويــج مــادة احلشــيش‬\n      ‫املخــدر ومت متكــن املصــدر مــن االتصــال علــى املدعــى عليــه وطلــب‬\n      ‫منــه قطعــه مــن احلشــيش وحضــر املتهــم بســيارته ملنــزل املصــدر وســلمه‬\n      ‫القطعــة واســتلم منــه املبلــغ املرقــم وأعطــى املصــدر الفرقــة القابضــة نــوع‬\n      ‫الســيارة ورقــم اللوحــة ‪ ،‬مت التعميــم علــى املتهــم وســيارته ‪ ،‬ورد بــاغ مــن‬\n      ‫أحــد املصــادر الســرية عــن وجــود شــخص يقــوم بترويــج احلشــيش املخــدر‬\n      ‫والشــراب املســكر وحبــوب الــروش ومت رصــد املنــزل وشــوهد املتهــم‬\n      ‫وهــو يقــود الســيارة املذكــورة وقــام بتســليم أحــد األشــخاص زجاجتــن‬\n      ‫يشــتبه أن تكــون مــن شــراب املســكر ومت اســتيقافه بتفتيــش الســيارة‬\n      ‫وجــد بهــا خمــس زجاجــات مســكر وبعــد أخــذ األذن مت الدخــول ملنــزل‬\n      ‫املدعــى عليــه وبتفتيــش غرفتــه عثــر علــى قطــع مــن احلشــيش وحبــوب‬\n      ‫الــروش ومبلــغ مالــي بجانبهــا وأربــع زجاجــات بهــا خمــر‪ .‬طلــب املدعــي‬\n      ‫العــام إثبــات إدانــة املدعــى عليــه مبــا هــو منســوب إليــه وأقــر املدعــى عليه‬\n      ‫مبــا نســب إليــه ‪ ،‬كمــا أنكــر اســتخدام ســيارته يف الترويــج وأنكــر‬\n      ‫ترويــج املســكر وقــرر بــأن املبلــغ املضبــوط يف منزلــه عائــد لــه وهــو جــزء‬\n      ‫مــن راتبــه وليــس مــن ترويــج املخــدرات او املســكرات ‪ ،‬وبنــاء علــى مــا‬\n\n‫‪215‬‬\n\f‫ســبق حكمــت احملكمــة بإقامــة حــد املســكر وتعزيــر املدعــى عليــه‬\n‫بالســجن واجللــد والغرامــة ومنعــه مــن الســفر وإعــادة املبلــغ احلكومــي‬\n‫ومصــادرة الهاتــف اجلــوال وإلغــاء شــريحته وصــرف النظــر عــن طلــب‬\n‫املدعــي العــام مصــادرة ســيارة املدعــى عليــه واملبلــغ املضبــوط يف بيتــه‬\n                                 ‫وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫اجلزئيــة‬\n   ‫ّ‬       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة‬\n‫بالدمــام وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزئيــة بالدمــام برقــم ‪ ......‬وتاريــخ ‪1433/01/08‬ه ـ املقيــدة باحملكمة‬    ‫ّ‬\n‫برقم وتاريخ ‪1433/01/08‬هـ ففي يوم االثنني املوافق‪1433/01/24‬هـ‬\n‫افتتحــت اجللســة الســاعة ‪ 10 : 32‬وفيهــا قــدم املدعــي العــام ‪ ......‬دعــواه‬\n‫ا فيهــا حيــث إنــه باالطــاع علــى محضــر‬      ‫ضــد املدعــى عليــه ‪ ......‬قائ ـ ً‬\n‫بــاغ املعــد مــن قبــل شــعبة مكافحــة املخــدرات يف األحــد‬\n‫‪1432/11/11‬ه ـ تبــن ورود بــاغ مــن أحــد مصادرهــم الســرية عــن‬\n‫قيــام املتهــم بترويــج مــادة احلشــيش املخــدر ويحمــل جــوال رقــم‪)......( :‬‬\n‫وقــد أفــاد املصــدر باســتعداده التــام للشــراء منــه واإلطاحــة بــه باجلــرم‬\n‫املشــهود عليــه مت متكــن املصــدر مــن االتصــال علــى جوالــه املشــار لــه‬\n‫ولقــد طلــب املصــدر منــه يف االتصــال قطعــة حشــيش بقيمــة (‪ )200‬ريــال‬\n‫ورد عليــه املتهــم أنــه يوجــد عنــده قطعــة حشــيش مخــدر بقيمــة (‪)250‬‬\n‫ريــا ًال فأجــاب املصــدر بأنــه ســوف يشــتريها فســأله املتهــم هــل لديــه‬\n‫ســيارة لكــي يحضــر إليــه؟ فــرد عليــه املصــدر بأنــه ال توجــد لديه ســيارة‬\n‫فقــال املتهــم إنــه ال ميلــك أيضـ ًا ســيارة وطلــب منــه االنتظــار لدقائــق حيــث‬\n\n                                                                                         ‫‪216‬‬\n\f      ‫ســيتصل عليــه الحق ـ ًا وفجــأة قــام املتهــم باالتصــال علــى املصــدر وقــال‬\n      ‫لــه ‪« :‬أنــا عنــد البيــت انــزل» فتــم إعطــاء املصــدر املبلــغ احلكومــي املرقــم‬\n      ‫ـراء للذمــة ومت‬\n                     ‫وقــدره (‪ )250‬ريــال وذلــك بعــد تفتيشــه تفتيشـ ًا دقيقـ ًا إبـ ً‬\n      ‫بعــث املصــدر للمتهــم وأثنــاء تــرك الغرفــة ملراقبــة املوقــع من اجلهــة املقابلة‬\n      ‫أفــاد املصــدر بــأن املتهــم قــام بتســليمه قطعــة مــن احلشــيش املخــدر يبلــغ‬\n      ‫وزنهــا (‪ )6.9‬جــم وأنــه حتــرك علــى الفــور كمــا أفــاد املصــدر بــأن املتهــم‬\n      ‫أتــى علــى ســيارة مــن نــوع ‪ ....‬موديــل ‪1992‬م لونهــا أخضــر حتمــل لوحــة‬\n      ‫رقــم (‪ )......‬علمـ ًا بــأن املصــدر ال يعــرف موقــع بيــت املتهــم عليــه مت جمــع‬\n      ‫املعلومــات ومت التعميــم عليــه وعلــى ســيارته املذكــورة ويف يــوم الثالثــاء‬\n      ‫‪1432/11/27‬ه ـ ورد بــاغ مــن أحــد مصادرهــم الســرية مفــاده وجــود‬\n      ‫شــخص يســكن حــي ‪ ....‬بجــوار محطــة ‪ .....‬يقــوم بترويــج مــادة احلشــيش‬\n      ‫املخــدر والشــراب املســكر وحبــوب الــروش احملظــورة وقد أفــاد املصدر‬\n      ‫بأنــه علــى أمت االســتعداد بالداللــة علــى املنــزل ويف اليــوم نفســه مت رصــد‬\n      ‫املنــزل املذكــور وشــوهد شــخص يقــود ســيارة مــن نــوع ‪ .....‬أخضــر اللــون‬\n      ‫يحمــل اللوحــة رقــم (‪ )......‬وهــو يقــوم بتســليم أحــد األشــخاص قارورتــن‬\n      ‫يشــتبه أن تكــون مــن الشــراب املســكر وأثنــاء اســتيقاف الشــخص‬\n      ‫املذكــور أعــاه اتضــح أنــه املتهــم وكان االســتيقاف بعيــد ًا عــن ســيارته‬\n      ‫وبتفتيشــه شــخصي ًا لــم ُيعثــر معــه علــى أي شــيء مــن املمنوعــات وبســؤاله‬\n      ‫عــن ســيارته التــي كان يقودهــا قــام بإنكارهــا وبتفتيــش الســيارة‬\n      ‫املذكــورة أعــاه وجــد بهــا خمســة قواريــر ميــاه معدنيــة مــن نــوع ‪ ....‬ســعة‬\n      ‫‪ 500‬مــل تفــوح منهــا رائحــة املســكر يشــتبه أن تكــون مــن الشــراب‬\n      ‫املســكر وبالضغــط عليــه مبــا يحــوزه يف منزلــه الواقــع يف حــي ‪ ....‬بجــوار‬\n      ‫محطــة ‪ ....‬قــام باالعتــراف بأنــه يوجــد بهــا كميــة من الشــراب املســكر‬\n\n\n‫‪217‬‬\n\f‫يف غرفتــه باإلضافــة إلــى قطــع مــن احلشــيش املخــدر وحبــوب الــروش‬\n‫وبعــد أخــذ اإلذن الــازم واصطحــاب املفتشــة النســائية وعضــو الهيئــة مت‬\n‫الدخــول ملنزلــه وإلــى غرفتــه مباشــرة وبرفقتــه شــخصي ًا حيــث عثــر‬\n‫الوكيــل رقيــب‪ ...... :‬علــى قطعــة ســمراء اللــون بلــغ وزنهــا ( ‪ ) 71.3‬جــم‬\n‫يشــتبه أن تكــون مــن مــادة احلشــيش املخــدر وكانــت موجــودة حتــت‬\n‫املالبــس املوجــودة يف خزانــة املالبــس كمــا عثــر حتــت الســرير علــى‬\n‫علبــة دخــان بداخلــه قطعتــن ســمراء اللــون يشــتبه أن تكــون مــن مــادة‬\n‫احلشــيش املخــدر بلــغ وزنهمــا (‪ )6‬جــم كمــا عثــر علــى عــدد ســبعة‬\n‫وثالثــن حبــة بيضــاء اللــون يشــتبه أن تكــون مــن حبــوب الــروش‬\n‫احملظــورة كانــت حتــت وســادة الســرير وبجانبهــا مبلــغ مالــي وقــدره‬\n‫(‪ )1300‬ريــال بجانــب احلبــوب حتــت الوســادة كمــا عثــرت الفرقــة علــى‬\n‫عــدد أربعــة جوالــن زرقــاء اللــون مملــوءة بشــراب يشــتبه أن يكــون مــن‬\n‫الشــراب املســكر وكانــت موجــودة يف نفــس الغرفــة وقــد أثبــت التقرير‬\n‫الكيمــاوي الشــرعي رقــم (‪ )......‬وتاريــخ ‪1432/11/21‬ه ـ الصــادر مــن‬\n‫املركــز اإلقليمــي ملراقبــة الســموم باملنطقــة الشــرقية إيجابيــة عينــة‬\n‫القطعــة املروجــة ملــادة احلشــيش املخــدر املدرجــة باجلــدول األول فئــة (أ)‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وقــد أثبــت التقريــر‬\n‫الكيمــاوي الشــرعي رقــم (‪ ).....‬وتاريــخ ‪1432/12/6‬ه ـ الصــادر مــن‬\n‫املركــز اإلقليمــي ملراقبــة الســموم باملنطقــة الشــرقية مــا يلــي‪-1:‬‬\n‫إيجابيــة احتــواء عينــة قواريــر املســكر املضبوطــة يف ســيارته علــى مــادة‬\n‫الكحــول اإليثيلــي وبنســبة مســكرة‪ -2‬إيجابيــة عينــة القطعــة‬\n‫املضبوطــة يف منــزل املتهــم ملــادة احلشــيش املخــدر املدرجــة باجلــدول األول‬\n‫فئــة (أ) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ -3‬إيجابيــة‬\n\n\n                                                                                    ‫‪218‬‬\n\f      ‫عينــة القطعتــن املضبوطتــن داخــل الباكيــت الــذي ُعثــر عليــه يف منــزل‬\n      ‫املتهــم ملــادة احلشــيش املخــدر املدرجــة باجلــدول األول فئــة (أ) مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪ -4‬إيجابيــة عينــة احلبــوب‬\n      ‫املضبوطــة يف منــزل املتهــم لعقــار الكلونازيبــام املــدرج باجلــدول الثانــي‬\n      ‫فئــة (د) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ -5‬احتــواء‬\n      ‫عينــة اجلوالــن املضبوطــة يف منــزل املتهــم علــى مــادة الكحــول اإليثيلــي‬\n      ‫وبنســبة مســكرة ‪ .‬وباســتجواب املتهــم اعتــرف بحيازتــه للهاتــف اجلــوال‬\n      ‫رقــم (‪ )......‬وبعائديــة ســيارة ‪ ....‬موديــل ‪ ......‬رقــم اللوحــة (‪ )......‬وأنكــر‬\n      ‫قيامــه بترويــج احلشــيش املخــدر يف يــوم األحــد ‪1432/11/11‬ه ـ وقــد‬\n      ‫اعتــرف بحيازتــه ملــا مت ضبطــه معــه ويف منزلــه مــن شــراب مســكر‬\n      ‫وحشــيش مخــدر وحبــوب محظــورة يف يــوم الثالثــاء ‪1432/11/27‬ه ـ‬\n      ‫وذلــك بقصــد االســتعمال الشــخصي وأنكــر قيامــه يف ذلــك اليــوم‬\n      ‫ترويجــه للمســكر وأن املبلــغ املضبــوط يف منزلــه هــو املتبقــي مــن راتبــه‬\n      ‫الشــهري كمــا اعتــرف بتعاطيــه للحشــيش املخــدر والشــراب املســكر‬\n      ‫واحلبــوب احملظــورة وانتهــى التحقيــق معــه الــى اتهامــه مبــا يلــي‪ -1/‬بيــع‬\n      ‫قطعــة مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )6.9‬ســتة جــرام وتســعة مــن‬\n      ‫العشــرة مــن اجلــرام بقصــد االجتــار وترويجــه لقارورتــن مــن املســكر‪-2‬‬\n      ‫حيــازة عــدد (‪ )5‬خمســة قواريــر مــن املســكر ســعة ‪ 500‬مــل وعــدد (‪)3‬‬\n      ‫ثــاث قطــع مــن احلشــيش املخــدر بلــغ وزنهــا ( ‪ ) 77.3‬ســبعة وســبعون‬\n      ‫جرام ـ ًا وثالثــة مــن العشــرة مــن اجلــرام وعــدد (‪ )37‬ســبعة وثالثــن حبــة‬\n      ‫بيضــاء اللــون مــن عقــار الكلونازيبــام احملظــور بقصــد التعاطــي‬\n      ‫والترويــج‪ -3‬شــرب املســكر‪ -4‬تعاطــي احلشــيش املخــدر واحلبــوب‬\n      ‫احملظــورة‪ .‬وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬مــا جــاء يف أقوالــه املنــوه‬\n\n\n‫‪219‬‬\n\f‫عنهــا واملرفقــة علــى اللفــات (‪ -2) 31.30.29.17.16.15‬محاضــر‬\n‫الضبــط املنــوه عنهــا واملدونــة علــى الصفحة رقم (‪ )11‬مــن ملف التحقيق‬\n‫املرفــق لفــة (‪ )1‬والصفحتــن رقــم (‪ )12.11‬مــن ملــف التحقيــق املرفــق‬\n‫لفــة (‪-3)18‬التقاريــر الكيماويــة الشــرعية املنــوه عنهــا واملرفقــة لفــة‬\n‫(‪ )7‬واللفــة رقــم (‪ -4)32‬وجــود املبلــغ املالــي قــرب احلبــوب احملظــورة‬\n‫املضبوطــة يف منــزل املتهــم قرينــة علــى أنهــا نتــاج عمليــات الترويــج‪-5‬‬\n‫اعتــراف املتهــم بعائديــة الســيارة املســتخدمة يف الترويــج وعائديــة‬\n‫الهاتــف اجلــوال املســتخدم بالتنســيق لعمليــة الترويــج قرينــة علــى اتهامــه‬\n‫بالقيــام بعمليــة ترويــج احلشــيش املخــدر وحيــث إن مــا أقــدم عليــه املدعــى‬\n ‫عليــه ‪ -‬وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ‪ -‬فعــلٌ محــرم ومعاقـ ٌ‬\n‫ـب‬\n‫عليــه شــرع ًا ونظامـ ًا اطلــب مــا يلــي أوالً‪ :‬إثبــات إدانتــه بشــرب املســكر‬\n‫واحلكــم عليــه بحــد الســكر لقــاء ذلــك ولتعاطيــه احلشــيش املخــدر‬\n‫ثاني ـاً‪ :‬إثبــات مــا ُأســند إليــه مــن اتهــام وفق ـ ًا للفقــرة رقــم (‪ )2‬مــن املــادة‬\n‫رقــم (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم‬\n‫عليــه مبــا يلــي‪ -1:‬بعقوبــة الســجن واجللــد والغرامــة الــواردة بالفقــرة رقــم‬\n‫(‪ )1‬مــن املــادة رقــم (‪ )38‬مــن النظــام مــع مراعــاة تطبيــق الفقــرة (‪ )1‬مــن‬\n‫املــادة (‪ )62‬مــن النظــام املتضمنــة تطبيــق العقوبــة األشــد ‪ -2‬منعــه مــن‬\n‫الســفر إعمــا ًال ملقتضــى الفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )56‬مــن‬\n‫النظــام‪ -3‬مصــادرة الهاتــف اجلــوال العائــد للمذكــور ويحمــل الرقــم‬\n‫املصنعــي (‪ )......‬ومصــادرة الســيارة املســتخدمة يف اجلرميــة وهــي مــن نــوع‬\n‫‪ ....‬أخضــر اللــون يحمــل اللوحــة رقــم (‪ )......‬وحتمــل رقــم الهيــكل (‪)......‬‬\n‫وهــي مــن نــوع ‪ .....‬الســتخدامه يف اجلرميــة وفق ـ ًا للفقــرة رقــم (‪ )1‬مــن‬\n‫املــادة رقــم (‪ )53‬مــن النظــام ‪ ،‬مــع املطالبــة بإســقاط شــريحة الهاتــف‬\n\n\n                                                                                               ‫‪220‬‬\n\f      ‫النقــال وعــدم صرفهــا لنفــس املتهــم وفقــا لتعميــم ســمو وزيــر الداخليــة‬\n      ‫رقــم ( ) وتاريــخ ‪1428/2/10-9‬ه ـ ‪ -4‬املطالبــة باملبلــغ احلكومــي املرقم‬\n      ‫والــذي لــم يتــم العثــور عليــه وفــق تعميــم صاحــب الســمو امللكــي ولــي‬\n      ‫العهــد وزيــر الداخليــة رقــم ( ) وتاريــخ ‪1428/10/23‬ه ـ ثالث ـاً‪ :‬إثبــات‬\n      ‫إدانــة املتهــم بترويــج املســكر وحيازتــه بقصــد االســتعمال الشــخصي‬\n      ‫والترويــج واحلكــم عليــه بعقوبــة تعزيريــة لقــاء ذلــك رابع ـاً‪ :‬مصــادرة‬\n      ‫املبلــغ املالــي وقــدره (‪ )1300‬ريــال كونهــا نتــاج جتــارة املخــدرات‬\n      ‫واملســكرات وبــاهلل التوفيــق ويف هــذه اجللســة حضــر املدعــى عليــه ‪......‬‬\n      ‫مبوجــب بطاقــة الهويــة الوطنيــة املــدون بهــا الرقــم ‪ ......‬وبعــرض دعــوى‬\n      ‫ا ‪ :‬صحيـ ٌـح أننــي بعــت علــى املصــدر‬   ‫املدعــي العــام عليــه أجــاب قائ ـ ً‬\n      ‫قطعــة احلشــيش املخــدر املذكــورة يف الدعــوى حيــث ســلمت لــه القطعــة‬\n      ‫واســتلمت منــه املبلــغ احلكومــي املرقــم وقــدره ( ‪ ) 250‬مائتــان وخمســون‬\n      ‫ريــا ًال وقــد صرفــت هــذا املبلــغ يف شــؤوني اخلاصــة وصحيـ ٌـح أننــي‬\n      ‫اســتخدمت هاتفــي اجلــوال املذكــور يف الدعــوى يف التنســيق مــع املصدر‬\n      ‫يف بيــع القطعــة املذكــورة وغيــر صحيــح أننــي اســتخدمت ســيارتي‬\n      ‫املذكــورة يف بيــع القطعــة املذكــورة وصحيـ ٌـح أنــه وجــد يف منزلــي مــا‬\n      ‫ـيش مخــدر وحبــوب روش وجوالــن مســكر‬           ‫ُذكــر يف الدعــوى مــن حشـ ٍ‬\n      ‫وهــذا كلــه يف حيازتــي بقصــد التعاطــي فقــط وليــس الترويــج وصحيـ ٌـح‬\n      ‫أنــه عنــد القبــض علــي كان يف حيازتــي قارورتــي املســكر املذكــورة‬\n      ‫يف الدعــوى بقصــد الشــرب وغيــر صحيـ ٌـح اتهامــي بترويجهــا وصحيـ ٌـح‬\n      ‫أننــي شــربت املســكر يــوم القبــض علــي وتعاطيت احلشــيش قبــل القبض‬\n      ‫بحوالــي ســبعة أشــهر وتعاطيــت حبــوب الكلونازيبــام قبــل خمــس‬\n      ‫ســنوات وأمــا بالنســبة للمبلــغ املالــي املوجــود يف املنــزل فلــم يكــن قــدره‬\n\n\n‫‪221‬‬\n\f‫(‪ ) 1300‬ألــف وثالثمائــة ريــال كمــا جــاء يف الدعــوى وإمنــا كان مبل ـ ٌغ‬\n‫وقــدره ( ‪ )2005‬ألفــان وخمســة ريــاالت وهــو جــزء مــن راتبــي وليــس مــن‬\n‫نتــاج املخــدرات أو املســكرات هــذه إجابتــي ‪ .‬وبســؤال املدعــي العــام‬\n‫عــن بينتــه فيمــا أنكــره املدعــى عليــه قــال لــدي البينــة معــدي محضــر‬\n                                ‫القبض وسوف أحضرهم يف اجللسة املقبلة ‪.‬‬\n‫ويف جلس ـ ٍة أخــرى حضــر الطرفــان كمــا حضــر ‪ ......‬مبوجــب بطاقــة‬\n‫الهويــة الوطنيــة املــدون بهــا الرقــم ‪ ......‬وقــال املدعــي العــام هــذا احلاضــر‬\n‫مــن ضمــن معــدي محضــر القبــض وأطلــب ســؤاله عمــا لديــه مــن شــهادة‬\n‫ا ‪ :‬أشــهد بــاهلل أننــي يف عمليــة بيــع قطعــة احلشــيش‬   ‫وبســؤاله شــهد قائـ ً‬\n‫املخــدر لــم أرى الســيارة التــي حضــر عليهــا املدعــى عليــه ولــم يرهــا أحــد‬\n‫مــن معــدي محضــر القبــض كمــا أشــهد بــاهلل أنــه عنــد القبــض علــى‬\n‫املدعــى عليــه توقــف بســيارة ‪ ...‬أخضــر مظللــه بجانــب ســيارة ‪ ....‬أســود‬\n‫وقــام أحــد داخــل الســيارة ‪ ....‬بتســليم كيــس لشــخص داخــل الســيارة‬\n‫‪ ....‬ومت إيقــاف الســيارة ‪ ....‬بعــد حوالــي ســاعة ونصــف أو ســاعتني وتبــن‬\n‫وجــود كيــس بداخلــه قارورتــن مســكر يحتمــل بشــكل كبيــر أنــه‬\n‫نفــس الكيــس الــذي مت تســليمه مــن قبــل شــخص يف الســيارة ‪ ....‬كمــا‬\n‫تبــن بتفتيــش الســيارة ‪ ....‬التــي حضــر عليهــا املدعــى عليــه وجــود خمــس‬\n‫قواريــر مســكر علمـ ًا أننــي لــم أرى الشــخص الــذي كان يف الســيارة‬\n‫ـخص الــذي كان يف‬      ‫‪ ....‬والــذي قــام بتســليم الكيــس املذكــور للشـ ٍ‬\n‫الســيارة ‪ ....‬كمــا مت تفتيــش منــزل املدعــى عليــه ووجدنــا املضبوطــات‬\n‫املذكــورة يف احملضــر يف غرفــة ذكــرت لنــا أخــت املدعــى عليــه وبعــض‬\n‫األطفــال الذيــن يف املنــزل أن هــذه الغرفــة تخــص ابــن أخــت املدعــى عليــه‬\n‫ولكــن املدعــى عليــه ذكــر أنــه ســيعترف بحيــازة مــا بداخــل هــذه‬\n\n\n                                                                                          ‫‪222‬‬\n\f      ‫الغرفــة حتــى ال ُيدخــل ابــن أختــه يف قضيــة علم ـ ًا أنــه ليــس ألحــد مــن‬\n      ‫معــدي احملضــر زيــادة عمــا ذكرتــه هــذا مــا لــدي مــن شــهادة وبعــرض‬\n      ‫ا ‪ :‬أمــا الشــاهد فــا‬    ‫الشــاهد وشــهادته علــى املدعــى عليــه أجــاب قائ ـ ً‬\n      ‫أقــول فيــه شــيئ ًا وأمــا شــهادته فالصحيــح أن مــن قــام بتســليم الكيــس‬\n      ‫الــذي بداخلــه قارورتــي املســكر شــخص كان معــي يف الســيارة يدعــى‬\n      ‫‪ ......‬وال اعــرف بقيــة اســمه ولــم أســلم أنــا هــذا الكيــس وال عالقــة لــي‬\n      ‫بترويــج هــذا املســكر وأمــا قواريــر املســكر التــي كانــت يف ســيارتي‬\n      ‫وهــي خمــس قواريــر فــا تخصنــي وتخــص الشــخص الــذي يدعــى ‪......‬‬\n      ‫وال أعــرف عنوانــه وقــد أحضــر هــذه القواريــر حتــى نشــربها ســوي ًا‬\n      ‫وصحيــح أن املضبوطــات التــي ذكرهــا الشــاهد هــي نفــس املضبوطــات‬\n      ‫التــي اعترفــت بحيازتهــا يف اجللســة الســابقة وهــي يف احلقيقــة تخــص‬\n      ‫ابــن اختــي ‪ ..........‬مــا عــدا قطعــة احلشــيش الصغيــرة التــي وزنهــا ( ‪) 6‬‬\n      ‫ســتة جرامــات فهــي لــي بقصــد التعاطــي وقــد اعترفــت بحيــازة جميــع‬\n      ‫املضبوطــات التــي يف املنــزل يف اجللســة الســابقة حتــى ُأخــرج ابــن أختــي‬\n      ‫مــن املوضــوع ‪ .‬وبطلــب معدلــن للشــاهد املذكــور قــرر املدعــي العــام‬\n      ‫إحضــار املعدلــن يف اجللســة املقبلــة ‪ .‬ويف جلس ـ ٍة أخــرى حضــر كل‬\n      ‫مــن ‪ ......‬ســعودي اجلنســية مبوجــب بطاقــة الهويــة الوطنيــة املــدون بهــا‬\n      ‫الرقــم ‪ ......‬ســعودي اجلنســية مبوجــب بطاقــة الهويــة الوطنيــة املــدون بهــا‬\n      ‫الرقــم ‪ ......‬وقــال املدعــي العــام احلاضــران معــدالن للشــاهد ‪ ......‬وأطلــب‬\n      ‫ســؤالهما عمــا لديهمــا مــن شــهادة وبســؤالهما شــهدا بعدالــة وديانــة‬\n      ‫ومــروءة الشــاهد ‪ ......‬ثــم جــرى ســؤال املدعــي العــام هــل لديــه مزيــد بينــة‬\n      ‫علــى الدعــوى فقــال ســوف أجيــب عــن ذلــك يف اجللســة املقبلــة ويف جلسـ ٍة‬\n      ‫أخــرى حضــر الطرفــان وجــرى ســؤال املدعــي العــام هــل لديــه زيــادة بينـ ٍة‬\n\n\n‫‪223‬‬\n\f‫علــى الدعــوى فقــال ‪ :‬ليــس لــدي ســوى مــا ورد يف الئحــة الدعــوى وأوراق‬\n                                           ‫املعاملــة ثــم جــرى رفــع اجللســة للتأمــل‪.‬‬\n‫احلمــد هلل وحــده وبعــد ويف يوم األربعاء املوافق‪1434/01/28‬هـ افتتحت‬\n‫اجللســة وفيهــا حضــر الطرفــان ثــم جــرى ســؤال املدعــى عليــه هــل ســيارة‬\n‫‪ ....‬التــي كانــت معــه عنــد القبــض تخصــه فقــال نعــم إنهــا ســيارتي وأنــا‬\n‫مــن كان يقودهــا ثــم جــرى ســؤاله هــل لديــه بينــة علــى مــا ذكــره مــن‬\n‫أن شــخص ًا معــه هــو مــن قــام بتســليم قارورتــي املســكر املذكورتــن يف‬\n‫الدعــوى فقــال ال بينــة لــدي علــى ذلــك ثــم جــرى االطــاع علــى أقــوال‬\n‫املدعــى عليــه لــدى هيئــة التحقيــق واالدعــاء العــام املرفقــة علــى اللفــات‬\n‫رقــم ( ‪ ) 28-30‬مــن طيــات املعاملــة وممــا تضمنتــه مــا نصــه ( ُعثــر داخــل‬\n‫ســيارتك علــى خمــس قواريــر ميــاه معدنيــة مــن نــوع ‪ ....‬تفــوح منهــا رائحــة‬\n‫املســكر فلمــن تعــود هــذه املضبوطــات ومــا هــو قصــدك مــن حيازتهــا ؟‬\n‫ج‪ /‬تعــود لــي شــخصي ًا بقصــد الشــرب ) وبعــرض هــذه األقــوال علــى‬\n‫ا ‪ :‬لقــد بصمــت علــى أقوالــي وصحيــح أننــي أن‬         ‫املدعــى عليــه أجــاب قائـ ً‬\n‫هــذه القواريــر لــي ويف حيازتــي بقصــد الشــرب ثــم جــرى االطــاع علــى‬\n‫بيانــات املدعــى عليــه يف بدايــة الئحــة الدعــوى وممــا تضمنتــه أن عليــه‬\n‫ســابقة حيــازة واســتعمال مخــدرات وبعــرض ذلــك علــى املدعــى عليــه‬\n‫ا الســابقة املذكــورة تخصنــي ثــم جــرى ســؤال املدعــى عليــه‬         ‫أجــاب قائـ ً‬\n‫هــل كانــت حيازتــه وتعاطيــه حلبــوب الكلونازيبــام ( الــروش ) بوصفـ ٍة‬\n‫طبيــة فقــال ‪ :‬ال بــدون وصفـ ٍة طبيــة فنظــر ًا ملا تقدم مــن الدعوى واإلجابة‬\n‫وحيــث أقــر املدعــى عليــه ببيــع قطعــة احلشــيش املخــدر املذكــورة يف‬\n‫الدعــوى وتســليمه لهــذه القطعــة واســتالمه للمبلــغ املرقــم وقــدره ( ‪250‬‬\n‫) مائتــان وخمســون ريــا ًال وصــرف هــذا املبلــغ يف شــؤونه اخلاصــة‬\n\n\n                                                                                            ‫‪224‬‬\n\f      ‫واســتخدامه لهاتفــه اجلــوال املذكــور يف الدعــوى للتنســيق مــع املصــدر‬\n      ‫يف بيــع القطعــة املذكــورة وأنكــر اســتخدامه لســيارته املشــار إليهــا يف‬\n      ‫الدعــوى يف عمليــة بيــع هــذه القطعــة وحيــث أقــر املدعــى عليــه يف جوابــه‬\n      ‫ـيش‬‫عــن الدعــوى بأنــه ُوجــد يف منزلــه مــا ُذكــر يف الدعــوى مــن حشـ ٍ‬\n      ‫مخــدر وحبــوب روش وجوالــن مســكر وأن ذلــك كلــه يف حيازتــه‬\n      ‫بقصــد التعاطــي وأنكــر قصــد الترويــج وحيــث رجــع املدعــى عليــه عــن‬\n      ‫اعترافــه بهــذه احليــازة يف جلس ـ ٍة أخــرى وقــرر أن جميــع املضبوطــات‬\n      ‫التــي يف املنــزل كانــت البــن أختــه وحيــث أن رجوعــه عــن اإلقــرار‬\n      ‫بحيازتهــا ال ُيقبــل منــه كــون اإلقــرار حج ـ ٌة قاصــر ٌة علــى املقــر وحيــث‬\n      ‫أقــر املدعــى عليــه بأنــه عنــد القبــض عليــه كان يف حيازتــه قارورتــي‬\n      ‫املســكر املذكورتــن يف الدعــوى بقصــد الشــرب وأنكــر اتهامــه‬\n      ‫بترويجهــا وأقــر بشــربه للمســكر وبتعاطيــه للحشــيش املخــدر وحلبــوب‬\n      ‫الكلونازيبــام وأقــر بــأن املبلــغ املالــي املوجــود يف املنــزل لــم يكــن قــدره‬\n      ‫( ‪ ) 1300‬ألــف وثالثمائــة ريــال وأنــه مبلغ ـ ًا وقــدره ( ‪ ) 2005‬ألفــان‬\n      ‫وخمســة ريــاالت وأنكــر أن يكــون هــذا املبلــغ مــن نتــاج املخــدرات أو‬\n      ‫املســكرات ولعــدم وجــود البينــة القاطعــة يف ذلــك ولعــدم وجــود البينــة‬\n      ‫كذلــك يف اســتعمال املدعــى عليــه لســيارته املذكــورة يف الدعــوى يف‬\n      ‫عمليــة بيــع قطعــة احلشــيش املخــدر ال ســيما وأن الشــاهد املعــدل شــرع ًا‬\n      ‫مشــعل العنــزي قــرر عــدم رؤيتــه للســيارة التــي حضــر عليهــا املدعــى عليه‬\n      ‫يف عمليــة بيــع قطعــة احلشــيش املخــدر وأنــه أيض ـ ًا لــم يرهــا أحـ ٌـد مــن‬\n      ‫معــدي محضــر القبــض ولعــدم وجــود البينــة القاطعــة يف إثبــات إدانــة‬\n      ‫املدعــى عليــه بترويــج قارورتــي املســكر املشــار إليهمــا يف الدعــوى‬\n      ‫ـاء على ما ورد يف شــهادة الشــاهد‬      ‫وحيــث أن التهمــة متوجـ ٌة لــه يف ذلــك بنـ ً‬\n\n‫‪225‬‬\n\f‫املعــدل شــرع ًا ‪ ......‬وممــا تضمنتــه أنــه عنــد القبــض علــى املدعــى عليــه‬\n‫توقــف بســيارة ‪ ....‬أخضــر مظللــه بجانــب ســيارة ‪ ....‬أســود وقــام أحــد‬\n‫داخــل الســيارة ‪ ....‬بتســليم كيــس لشــخص داخــل الســيارة ‪ ....‬وأنــه بعــد‬\n‫إيقــاف ‪ ....‬تبــن وجــود كيــس بداخلــه قارورتــي مســكر ويحتمــل‬\n‫بشــكل كبيــر أنــه نفــس الكيــس الــذي مت تســليمه مــن قبــل شــخص‬\n‫يف الســيارة ‪ ....‬وقــرر الشــاهد بأنــه لــم يــرى الشــخص الــذي يف كان يف‬\n‫الســيارة ‪ ....‬والــذي قــام بتســليم الكيــس املذكــور وحيــث أقــر املدعــى‬\n‫عليــه يف معــرض ســماع شــهادة الشــاهد املذكــور بــأن مــن قــام بتســليم‬\n‫الكيــس الــذي بداخلــه قارورتــي املســكر شــخص كان معــه يف‬\n‫الســيارة وأنكــر أن يكــون هــو مــن ســلم هــذا الكيــس أو أن يكــون‬\n‫لــه عالقــة بترويــج املســكر وحيــث أن يف ذلــك مــا يوجــه التهمــة يف حــق‬\n‫املدعــى عليــه باالشــتراك يف ترويــج هاتــن القارورتــن وممــا يزيــد يف‬\n‫جانــب التهمــة يف هــذا أيضـ ًا بــأن مــا أقــر بــه يتناقــض مــع مــا أقــر بــه يف‬\n‫جوابــه عــن الدعــوى مــن أن هاتــن القارورتــن يف حيازتــه بقصــد الشــرب‬\n‫وحيــث أنكــر املدعــى عليــه يف معــرض ســماع شــهادة الشــاهد املذكور‬\n‫حيــازة قواريــر املســكر املوجــود يف الســيارة ‪ ....‬وأقــر بأنهــا تخــص‬\n‫الشــخص الــذي ُيدعــى ‪ ......‬وأن هــذا الشــخص أحضرهــا لكــي‬\n‫يشــرباها ســوي ًا بينمــا أقــر يف هــذه اجللســة بحيازتــه لهــذه القوارير بقصد‬\n‫ـض يوجــه التهمــة لــه يف حيــازة هــذه القواريــر‬         ‫الشــرب ويف هــذا تناقـ ٌ‬\n‫بقصــد الترويــج باإلضافــة للشــرب ولتوجــه التهمــة يف حــق املدعــى عليــه‬\n‫بــأن قصــده مــن حيــازة املضبوطــات املوجــودة يف منزلــه كانــت بقصــد‬\n‫الترويــج باإلضافــة للتعاطــي بداللــة قيامــه ببيــع قطعــة احلشــيش املخــدر‬\n‫املذكــورة يف الدعــوى وبعــد االطــاع علــى طيــات املعاملــة ومــن ضمنهــا‬\n\n\n                                                                                          ‫‪226‬‬\n\f      ‫التقريــر الكيمــاوي الشــرعي الصــادر مــن املركــز اإلقليمــي ملراقبــة‬\n      ‫الســموم باملنطقــة الشــرقية برقــم ‪ .........‬املتضمــن احتــواء العينتــن رقــم‬\n      ‫( ‪ ) 32/1082‬ورقــم ( ‪/1082‬د ) علــى مــادة الكحــول اإليثيلــي وبنســب ٍة‬\n      ‫مســكرة وإيجابيــة العينتــن رقــم ( ‪/1082‬أ ) ورقــم ( ‪/1082‬ب ) ملــادة‬\n      ‫احلشــيش املخــدر وإيجابيــة العينــة رقــم ( ‪/1082‬ج ) لعقــار الكلونازيبــام‬\n      ‫وبعــد االطــاع علــى التقريــر الكيمــاوي الشــرعي الصــادر مــن املركــز‬\n      ‫اإلقليمــي ملراقبــة الســموم باملنطقــة الشــرقية برقــم () املتضمــن إيجابيــة‬\n      ‫العينــة ملــادة احلشــيش املخــدر وبعــد االطــاع علــى أقــوال املدعــى عليــه‬\n      ‫لــدى هيئــة التحقيــق واالدعــاء العــام املشــار إليهــا بعاليــه وبعــد االطــاع‬\n      ‫علــى إيضاحــات واقعــة القبــض والضبــط والتفتيــش املدونــة علــى‬\n      ‫الصفحــة رقــم ( ‪ ) 11‬مــن ملــف ضبــط إجــراءات االســتدالل يف قضايــا‬\n      ‫املخــدرات املرفــق علــى اللفــة رقــم ( ‪ ) 1‬مــن طيــات املعاملــة املتضمــن‬\n      ‫نحــو مــا ُأشــير إليــه يف الدعــوى وبعــد االطــاع علــى إيضاحــات واقعــة‬\n      ‫القبــض والضبــط والتفتيــش املدونــة علــى الصفحتــن رقــم ( ‪) 12 - 11‬‬\n      ‫مــن ملــف ضبــط إجــراءات االســتدالل يف قضايــا املخــدرات املرفــق علــى‬\n      ‫اللفــة رقــم ( ‪ ) 18‬مــن طيــات املعاملــة وممــا تضمنتــه بأنــه شــوهد شــخص‬\n      ‫يقود ســيارة من نوع ‪ ....‬أخضر ويقوم بتســليم أحد األشــخاص قارورتني‬\n      ‫ُيشــتبه أن تكــون مــن الشــراب املســكر وأثنــاء اســتيقاف الشــخص‬\n      ‫املذكــور اتضــح أنــه يدعــى ‪ ......‬وحيــث أن يف هــذا احملضــر مــا يوجــه‬\n      ‫التهمــة يف حــق املدعــى عليــه بترويــج قارورتــي املســكر املذكورتــن‬\n      ‫ـاء علــى الفقــرة ( ‪ ) 2‬مــن املــادة رقــم ( ‪ ) 3‬والفقــرة ( ‪ ) 1‬مــن املــادة‬\n                                                                                   ‫وبنـ ً‬\n      ‫رقــم ( ‪ ) 38‬واملــادة رقــم ( ‪ ) 53‬والفقــرة ( ‪ ) 1‬مــن املــادة رقــم ( ‪) 56‬‬\n      ‫والفقــرة ( ‪ ) 1‬مــن املــادة رقــم ( ‪ ) 62‬مــن نظــام مكافحــة املخــدرات‬\n\n\n‫‪227‬‬\n\f‫واملؤثــرات العقليــة لذلــك كلــه فقــد قــررت مــا يلــي ‪ :‬أوالً‪ -‬ثبــت لــدي‬\n‫إدانــة املدعــى عليــه بترويــج قطعــة احلشــيش املخــدر املذكــورة يف‬\n‫الدعــوى البالــغ وزنهــا ( ‪ ) 6.9‬ســتة جرامــات وتســعة مــن العشــرة مــن‬\n‫اجلــرام وذلــك عــن طريــق البيــع وقــررت معاقبتــه علــى ذلــك مبــا يلــي ‪ :‬أ‪-‬‬\n‫ـداء مــن تاريــخ إيقافــه وجلــده أربعمائــة‬  ‫ســجنه ملــدة خمــس ســنوات ابتـ ً‬\n‫ـات متســاوية بــن كل دفعـ ٍة وأخــرى مــا ال‬      ‫جلــدة مفرقــة علــى ثمــان دفعـ ٍ‬\n‫يقــل عــن خمســة عشــر يوم ـ ًا وتغرميــه مبلغ ـ ًا وقــدره ( ‪ ) 5000‬خمســة‬\n‫آالف ريــال ‪ .‬ب‪ -‬منعــه مــن الســفر ملــدة خمــس ســنوات تبــدأ بعــد انتهــاء‬\n‫مدة السجن املقررة يف حقه يف الفقرة ( أ ) من هذا البند ‪ .‬ج‪ -‬مصادرة‬\n‫هاتفــه اجلــوال املذكــور رقمــه املصنعــي يف الدعــوى الســتخدامه يف‬\n‫التنســيق لعمليــة البيــع املذكــورة مــع إســقاط شــريحة الهاتــف اجلــوال‬\n‫املذكــور يف الدعــوى وعــدم صرفهــا لنفــس املدعــى عليــه ‪ .‬ثانيـاً‪ -‬عــدم‬\n‫اســتحقاق املدعــي العــام ملــا ُيطالــب بــه مــن مصــادرة الســيارة ‪ ....‬املشــار‬\n‫إليهــا يف الدعــوى ملــا ورد مــن ضمــن احليثيــات أعــاه ‪ .‬ثالث ـاً‪ -‬إلــزام‬\n‫املدعــى عليــه بدفــع مبلـ ٍـغ وقــدره ( ‪ ) 250‬مائتــان وخمســون ريــا ًال وذلــك‬\n‫للجهــة املختصــة بــد ًال عــن املبلــغ احلكومــي املرقــم الــذي قــام بصرفــه‪.‬‬\n‫رابعـاً‪ -‬عــدم اســتحقاق املدعــي العــام ملــا ُيطالــب بــه مــن مصــادرة املبلــغ‬\n‫املالــي املشــار إليــه يف الدعــوى وقــدره ( ‪ )1300‬ألــف وثالثمائــة ريــال‬\n‫لعــدم وجــود البينــة القاطعــة مــن أنــه مــن نتــاج جتــارة املخــدرات أو‬\n‫املســكرات ‪ .‬خامس ـاً‪ -‬ثبــت لــدي إدانــة املدعــى عليــه بحيــازة ( ‪) 37‬‬\n‫ســبعه وثالثــن حبــة مــن عقــار الكلونازيبــام بقصــد التعاطــي بــدون‬\n‫وصفـ ٍة طبيــة كمــا ثبــت لــدي إدانتــه بحيــازة ثــاث قطـ ٍـع مــن احلشــيش‬\n‫املخــدر البالــغ وزنهــا ( ‪ ) 77.3‬ســبعه وســبعني جرامـ ًا وثالثــة مــن العشــرة‬\n\n\n                                                                                        ‫‪228‬‬\n\f      ‫مــن اجلــرام بقصــد التعاطــي والتهمــة متوجه ـ ُة يف حقــه بحيــازة هــذه‬\n      ‫احلبــوب والقطــع بقصــد الترويــج باإلضافــة للتعاطــي ملــا ُذكــر مــن ضمــن‬\n      ‫احليثيــات أعــاه وعقوبتــه يف ذلــك كلــه داخلـ ٌة يف العقوبــة الصــادرة يف‬\n      ‫ـاء بالعقوبــة‬‫حقــه يف الفقرتــن ( أ ) و ( ب ) مــن البنــد ( أو ًال ) اكتفـ ً‬\n      ‫األشــد ‪ .‬سادسـاً‪ -‬توجــه التهمــة يف حــق املدعــى عليــه يف ترويــج قارورتــي‬\n      ‫املســكر املذكورتــن يف الدعــوى ملــا ورد مــن ضمــن احليثيــات أعــاه‬\n      ‫كمــا ثبــت لــدي إدانتــه بحيــازة ( ‪ ) 5‬خمــس قواريــر مــن املســكر املشــار‬\n      ‫إليهــا يف الدعــوى املوجــودة يف ســيارته بقصــد الشــرب والتهمــة متوجهــة‬\n      ‫يف حقــه بحيازتهــا بقصــد الترويــج باإلضافــة للشــرب كمــا ثبــت لــدي‬\n      ‫إدانــة املدعــى عليــه بحيــازة (‪ ) 4‬أربــع جوالــن مــن املســكر املضبوطــة‬\n      ‫يف منزلــه بقصــد الشــرب والتهمــة متوجه ـ ٌة يف حقــه بحيازتهــا بقصــد‬\n      ‫الترويــج باإلضافــة للشــرب وعقوبتــه علــى ذلــك كلــه داخلــة يف عقوبــة‬\n      ‫الســجن واجللــد الصــادرة يف حقــه يف القفــرة ( أ ) مــن البنــد ( أو ًال )‬\n      ‫ـاء بالعقوبــة األشــد ‪ .‬ســابعاً‪ -‬ثبــت لــدي إدانــة املدعــى عليــه بشــرب‬\n                                                                                 ‫اكتفـ ً‬\n      ‫املســكر وقــررت جلــده حــد املســكر ثمانــن جلــدة دفع ـ ًة واحــده علن ـ ًا‬\n      ‫مبجمـ ٍـع مــن النــاس علــى أن ُيفـ ّـرق بــن هــذا اجللــد واجللــد الصــادر يف‬\n      ‫حقــه يف الفقــرة ( أ ) مــن البنــد ( أو ًال ) مبــد ٍة ال تقــل عــن خمســة عشــر‬\n      ‫يوم ـ ًا ‪ .‬ثامن ـاً‪ -‬ثبــت لــدي إدانــة املدعــى عليــه بتعاطــي احلشــيش املخــدر‬\n      ‫واكتفيــت مبــا صــدر عليــه مــن حــدٍ للمســكر املذكــور يف البنــد‬\n      ‫(ســابعاً) كمــا اكتفيــت مبــا صــدر عليــه مــن منـ ٍـع مــن الســفر املذكــور‬\n      ‫يف الفقــرة ( ب ) مــن البنــد ( أو ًال ) ‪ .‬تاســعاً‪ -‬ثبــت لــدي إدانــة املدعــى‬\n      ‫عليــه بتعاطــي حبــوب عقــار الكلونازيبــام بــدون وصف ٍة طبيــة واكتفيت‬\n      ‫مبــا صــدر عليــه مــن حــدٍ للمســكر املذكــور يف البنــد ( ســابع ًا ) عــن‬\n\n\n‫‪229‬‬\n\f‫تعزيــره لقــاء ذلــك كمــا اكتفيــت مبــا صــدر عليــه مــن منـ ٍـع مــن الســفر‬\n‫املذكــور يف الفقــرة ( ب ) مــن البنــد ( أو ًال ) وبذلــك أجمــع حكمــت‬\n‫وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه القناعة وقــرر املدعي‬\n‫العــام االعتــراض وطلــب رفــع احلكــم حملكمــة االســتئناف واكتفــى‬\n‫بالئحــة الدعــوى وأوراق املعاملــة عــن تقــدمي الئح ـ ٍة اعتراضيــة ف ٌأجيــب‬\n                ‫لطلبه واهلل املوفق وصلى اهلل على نبينا محمد وآله وسلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد‪ ،‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام برقــم ‪ ......‬وتاريــخ‬\n‫‪1434/2/20‬هـ املقيدة لدى احملكمة برقم ‪ ......‬وتاريخ ‪1434/2/26‬هـ‬\n‫املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪......‬‬\n‫املســجل برقــم ‪ ......‬وتاريــخ ‪1434/2/9‬ه ـ اخلــاص بدعوى‪/‬املدعــى العــام‬\n‫ضــد‪ ....../‬يف قضيــة مخــدرات ومســكر وقــد تضمــن القــرار حكــم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه‬\n‫وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل‬\n          ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/4/17‬ه ـ‬\n\n\n\n\n                                                                                    ‫‪230‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":214,"source_page_end":230,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"153f76efcbd454bde73fa100bc4115e6e4264f7f07a6d135f510234696afc2d6","normalized_text_hash":"88b95ad3f69ca73548c601cd30fb15d399d5b27cdff9ff441dc7a9bfab029915","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p214-3432371"},{"id":"af7b6fa5-bfe0-5c17-88b1-543c2a8f13b7","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -شروع يف نقل حبوب محظورة-شهادة شهود ومحاضر ضبط -إقرار املدعى عليه حتقيق ا -ضبط احلبوب احملظورة داخل املطار حال وصولها -ثبوت إدانة -تعزير بالسجن واجللد والغرامة ومصادرة ومنع من السفر.","document_number":"33297549","case_number":"3374553","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1432/01/29","year":"1434","subject":"مخدرات -شروع يف نقل حبوب محظورة-شهادة شهود ومحاضر ضبط -إقرار املدعى عليه حتقيق ا -ضبط احلبوب احملظورة داخل املطار حال وصولها -ثبوت إدانة -تعزير بالسجن واجللد والغرامة ومصادرة ومنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 33297549 :‬تاريخه‪1432/01/29 :‬هـ‬\n                            ‫رقم الدعوى‪3374553:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34195156‬تاريخه‪1434/4/22 :‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬شــروع يف نقــل حبــوب محظورة‪-‬شــهادة شــهود ومحاضــر‬\n       ‫ضبــط ‪ -‬إقــرار املدعــى عليــه حتقيقـ ًا ‪ -‬ضبــط احلبــوب احملظــورة داخــل‬\n       ‫املطــار حــال وصولهــا ‪ -‬ثبــوت إدانــة ‪ -‬تعزيــر بالســجن واجللــد والغرامــة‬\n                                                      ‫ومصــادرة ومنــع مــن الســفر‪.‬‬\n\n\n\n\n       ‫املــادة ‪ ، 38‬املــادة ‪ 59‬فقــرة (‪،)1‬املــادة ‪ 60‬مــن نظــام مكافحــة املخــدرات‬\n                                                               ‫واﻤﻟﺆﺛﺮات اﻟﻌﻘﻠﻴﺔ‪.‬‬\n\n\n\n\n                 ‫أقام املدعي العام دعواه ضد املدعى عليه طالب ًا احلكم عليه‪-:‬‬\n       ‫‪ .1‬عقوبــة القتــل املنصــوص عليهــا يف الفقــرة (‪ )1‬مــن املــادة الثالثــة مــن‬\n                                                  ‫نظــام املخــدرات واملؤثــرات العقليــة‬\n       ‫‪ .2‬مصــادرة جوالــه وفقـ ًا للفقــرة (‪ )1‬مــن املــادة ‪ 53‬مــن ذات النظــام وعدم‬\n                                                  ‫صــرف شــريحة اجلــوال لــه مــرة أخرى‬\n       ‫‪ .3‬مصــادرة الســيارة العائــدة للمتهــم وذلــك بعــد القبــض عليــه متلبس ـ ًا‬\n       ‫بالشــروع يف نقــل احلبــوب املخــدرة مبعرفــة رجــال األمــن واعترافــه‬\n                                                                    ‫مبحاضــر الضبــط‪.‬‬\n       ‫ومبواجهــة املدعــى عليــه أنكــر التهمــة وبــرر تواجــده بالســوق مــن أجــل‬\n\n‫‪231‬‬\n\f‫شــراء بعــض اخلضــار والفاكهــة ألجــل ســفره مــع أبنــاء عمــه‪ .‬وبعــد أن‬\n‫قارنــت احملكمــة بــن أقــوال وبينــات الطرفــن وطالعــت أوراق القضيــة‬\n‫وســماع شــهادة الشــهود قــررت احملكمــة اآلتــي‪ :‬صــرف النظــر عــن‬\n‫دعــوى املدعــى العــام وعــن مطالبتــه بتطبيــق املــادة ‪ 37‬رقــم ‪ 2‬مــن البنــد‬\n‫أوالً‪ :‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ ،‬وعــن مطالبتــه‬\n‫بتطبيــق الفقــرة (‪ )1‬مــن املــادة ‪ 53‬مــن النظــام نفســه ‪ .‬ثانيـاً‪ :‬ثبــت لديهــا‬\n‫الشــروع يف نقــل املــواد احملظــورة وقــررت تعزيــره ألجــل ذلــك بالســجن‬\n‫عشــر ســنوات وجلــده ألــف جلــدة وتغرميــه مببلــغ خمســن ألــف ريــال تــودع‬\n‫يف بيــت مــال املســلمني ومنعــه مــن الســفر مــدة مماثلــة ملــدة ســجنه‪ .‬ولــم‬\n‫يقنــع كل مــن املدعــى العــام واملدعــى عليــه ‪ ،‬وجــرى تصديــق محكمــة‬\n                                                       ‫االســتئناف علــى احلكــم‪.‬‬\n\n\n\n‫احلمد هلل وحده وبعد لدينا نحن ‪ ................‬القضاة يف احملكمة العامة‬\n‫بالدمــام وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالدمــام برقــم ‪................‬وتاريــخ ‪1433/01/29‬ه ــاملقيدة‬\n‫باحملكمــة برقــم ‪................‬وتاريــخ ‪ 1433/01/29‬ه ـ ففــي يــوم االثنــن‬\n‫املوافــق‪ 1433/02/15‬ه ـ افتتحــت اجللســة الســاعة ‪ 12 : 55‬وفيهــا‬\n‫حضــر املدعــي العــام بالدمــام ‪................‬وقــدم الئحــة الدعــوى املتضمنــة‬\n‫‪ :‬اســم املتهــم‪ ................ :‬اجلنــس‪ :‬ذكــر‪ .‬اجلنســية‪ :‬ســعودي‪ .‬العمــر وقــت‬\n‫اجلرميــة‪ 23 :‬رقــم الهويــة‪................ :‬املهنــة‪ :‬متســبب احلالــة االجتماعيــة‪:‬‬\n‫أعــزب مــكان اإلقامــة‪ - .... :‬حــي ‪.........‬جهــة اإليقــاف‪ :‬شــعبة اصالحيــة‬\n‫الدمــام تاريــخ القبــض‪ 1432/7/23 :‬حالــة املتهــم‪ :‬موقــوف اإلتهــام‪:‬‬\n\n                                                                                         ‫‪232‬‬\n\f                   ‫تلقــي املؤثــرات العقليــة بقصــد الترويــج الســوابق‪ :‬ال يوجــد ‪..‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن النبــي بعــده ‪ ...‬بصفتــي‬\n      ‫مدعي ـ ًا عام ـ ًا بدائــرة اإلدعــاء العــام لفــرع الهيئــة باملنطقــة الشــرقية‬\n      ‫أدعــي علــى املذكــور أعــاه أنــه بتاريــخ ‪1432/7/22‬ه ــتم القبــض علــى‬\n      ‫املتهــم اعــاه اثــر بــاغ مــن قبــل وحــدة مكافحــة املخــدرات مبطــار امللــك‬\n      ‫فهــد الدولــي مبنــي علــى بــاغ مــن قبــل جمــرك مطــار امللــك فهــد بقــدوم‬\n      ‫شــحنة جويــة قادمــة مــن دولــة ‪ ....‬بداخلهــا بضائــع من الفواكــه (فاكهة‬\n      ‫الكرز) ويف أثناء تفتيشــها مت العثور على ما عدده (‪ )211.293‬مائتان‬\n      ‫وأحــد عشــر ألفــا ً ومئتــان وثــاث وتســعون حبة أثبت التقريــر الكيماوي‬\n      ‫الشــرعي رقــم (‪ ).........‬وتاريــخ ‪1432/8/4‬ه ـ إيجابيــة عيناتهــا ملــادة‬\n      ‫(االمفيتامــن) املنبهــة واملدرجــة باجلــدول الثانــي فئــة (ب) مــن نظــام‬\n      ‫ـاء عليــه مت اســتدعاء‬    ‫مكافحــة املخــدرات واملؤثــرات العقليــة ‪ ،‬وبنـ ً‬\n      ‫املخلــص اجلمركــي للبضاعــة املدعــو ‪................ /‬ومبناقشــته أفــاد أن‬\n      ‫البضاعــة هــي فواكــه مســتوردة ألحــد التجــار املســتوردين يف ســوق‬\n      ‫اخلضــار والفواكــه بالدمــام ويدعــى ‪................ /‬وباالتصــال عليــه قــام‬\n      ‫باحلضــور إلــى وحــدة مكافحــة املخــدرات باملطار وبســؤاله عــن تفاصيل‬\n      ‫ســير البضاعــة املضبوطــة ذكــر أنــه دائمـ ًا مــا يقــوم باســتيراد الفواكــه‬\n      ‫وأنــه قــد اتصــل بــه شــخص ‪ ....‬اجلنســية يدعــى ‪................ /‬وأفــاد وهــو‬\n      ‫أحــد جتــار الفواكــه يف ‪ ....‬ولــه تعامــل مســبق معــه وآخرهــا يف اجلمعــة‬\n      ‫الفائتــة علــى بضاعــة مــن الفواكــه (الكــرز) حيــث اســتلمها وقــام‬\n      ‫بوضعهــا لديــه بالثالجــات وحضــر إليــه بعــد ذلــك شــخصان (ســعوديان)‬\n      ‫علــى ســيارة مــن نــوع (‪ )................‬وقامــا بتحميــل البضاعــة وذهبــوا بهــا‬\n      ‫مقابــل عمولــة يأخذهــا علــى ذلــك وأبــدى اســتعداده للتعــاون باإلطاحــة‬\n\n\n‫‪233‬‬\n\f‫باملســتقبل لهــذه الكميــة ويف متــام الســاعة الرابعــة عصــر ًا مت االنتقــال‬\n‫إلــى ســوق اخلضــار مبدينــة الدمــام ومت اصطحــاب البضاعة بســيارة (‪)....‬‬\n‫ووضعهــا يف داخــل الســوق وقــام ‪................ /‬باالتصــال علــى التاجــر ‪.....‬‬\n‫‪ .. /‬علــى الرقــم (‪ )................‬وأفــاد أن البضاعــة قــد وصلــت وســأله‬\n‫عــن الشــخص الــذي ســوف يقــوم باســتالمها فذكــر لــه أنــه شــخص‬\n‫يدعــى ‪................‬ويحمــل اجلــوال رقــم ‪................‬وأنــه ســوف يحضــر إليــه‬\n‫ـاء علــى ذلــك مت التمركــز يف ســوق اخلضــار بالدمــام‬      ‫يف اليــوم التالــي وبنـ ً‬\n‫ويف الســاعة السادســة صباحـ ًا قــام ‪................ /‬باالتصــال علــى املتهــم ‪/‬‬\n‫‪................‬علــى اجلــوال رقــم ‪................‬وطلــب منــه احلضــور إليــه الســتالم‬\n‫البضاعــة فذكــر لــه أنــه ســوف يحضــر بعــد قليــل وكانــت املكاملــة‬\n‫علــى مســمع مــن قائــد الفرقــة وبعــد نصــف ســاعة حضــرت ســيارة مــن‬\n‫نــوع ‪ ................‬اللــون ‪ ....‬حتمــل اللوحــة رقــم (‪ )............‬وقــام بالوقــوف‬\n‫بالقــرب مــن املوقــع وترجــل مــن ســيارته وتوجــه إلــى ‪ ................ /‬وســأله‬\n‫هــل البضاعــة جاهــزة فأفــاده أنهــا جاهــزة وطلــب منــه إحضــار ســيارة‬\n‫ليقــوم العمــال بتحميــل البضاعــة عليهــا ولوحــظ علــى املتهــم عالمــات‬\n‫االرتبــاك وكثــرة االلتفــات مينــة ويســرة ويبــدو أنــه يف اثنــاء ذلــك شــاهد‬\n‫قائــد الفرقــة وشــاهد آثــار التفتيــش علــى البضاعــة وقــام بالرجــوع إلــى‬\n‫ســيارته مــرة أخــرى ووقــف بالقــرب مــن بــاب الســائق وحضــر شــخص ‪....‬‬\n‫اجلنســية واحتــك بــه وكانــا يتفقــان علــى نقــل البضاعــة إلــى مدينــة ‪....‬‬\n‫وللخــوف مــن أن يكــون املتهــم قــد شــاهد البضاعــة وعليهــا عالمــات‬\n‫التفتيــش متــت مداهمتــه والقبــض عليه وبتفتيشــه شــخصي ًا لــم يتم العثور‬\n‫بحوزتــه علــى شــيء مــن املمنوعــات وبأخــذه خــارج املوقــع ومبحاولــة‬\n‫مناقشــته حــول القضيــة واإلحلــاح عليــه حيــال ذلــك أفــاد انــه قبــل يومــن‬\n\n\n                                                                                              ‫‪234‬‬\n\f                                 ‫قابــل شــخص يدعــى ‪................ /‬يف محافظــه ‪.....‬‬\n      ‫وذكــر لــه أن هنــاك حجــر ابيــض قــادم مــن ســوريا وهــو يقصــد بذلــك‬\n      ‫احلبــوب املخــدرة وتقــدر كميتهــا بــ(‪ )1000‬شــد وأنــه قــد أغــراه باملــال‬\n      ‫ووعــده مببلــغ (‪ )150‬مائــة وخمســن ألــف ريــال إذا قــام باحضارهــا إليــه‬\n      ‫يف محافظــة اخلــرج وكان ذلــك علــى مســمع مــن قائــد الفرقــة وأحــد‬\n      ‫أعضائهــا ومت متكينــه مــن االتصــال باملدعــو‪ ....‬علــى جوالــه رقــم (‪)....‬‬\n      ‫وذكــر لــه أن األمــور طيبــة وعلــى مــا يــرام ولكــن املدعــو‪ ...‬كان قلقـ ًا‬\n      ‫وكان يتصــل يف كل دقيقــة حملاولــة كشــف الشــخص وبعــد ذلــك قــام‬\n      ‫باقفــال جوالــه وبتفتيــش الســيارة العائــدة للمتهــم لــم يتــم العثــور بهــا علــى‬\n      ‫شــيء مــن املمنوعــات وأفــاد مســتورد البضاعــة‪ ....‬أن البضاعة املضبوطة‬\n      ‫قــد وردت عــن طريــق مطــار امللــك فهــد الدولــي مــن قبــل شــخص ســوري‬\n      ‫اجلنســية يدعــى‪ .....‬يتعامــل معــه يف مجــال توريــد الفواكــه منــذ ســنوات‬\n      ‫وقــد انقطــع عــن التعامــل معــه يف الفتــرة األخيــرة ولكنــه عــاد واتصل به‬\n      ‫وطلــب منــه اســتالم بضاعــة مــن الفواكــه ســوف تصــل ملطــار امللــك فهــد‬\n      ‫بالدمــام وتســمليها ‪ .. ...‬وبعــد وصــول البضاعــة مت االتصــال بــه مــن قبــل‬\n      ‫مكافحــة املخــدرات وبســؤاله عــن البضاعــة ذكــر لهــم مــا يعرفــه فتــم‬\n      ‫االتفــاق معــه علــى إخــراج البضاعة من املطار واالتصال بالشــخص الذي‬\n      ‫طلــب منــه أبــو ‪ ....‬وهــو ‪ ....‬للحضــور الســتالمها وبعــد ذلــك قــام باالتصــال‬\n      ‫باملتهــم علــى جوالــه ‪ ....‬واخبــره بوصــول البضاعــة وحضــر املتهــم‪ ،‬وقــام‬\n      ‫مبقابلتــه بالســوق وانصــرف بغــرض إحضــار ســيارة للتحميل ومت القبض‬\n      ‫عليــه يف أثنــاء ذلــك‪ ،‬وأضــاف أنــه ويف األســبوع املاضــي وصلــت بضاعــة‬\n      ‫عــن طريــق نفــس التاجــر وحضــر املتهــم وبرفقتــه شــخص آخــر لتحميلهــا‬\n      ‫وأفــاد أنــه يقــوم بذلــك مقابــل عمولــة يقــوم بأخذهــا ‪ .‬وبعــرض املتهــم ‪....‬‬\n\n\n‫‪235‬‬\n\f‫علــى ‪ ....‬قــام بالتعــرف عليــه وذكــر أنــه هــو الشــخص الــذي حضــر إليــه‬\n‫يف الســوق الســتالم البضاعــة وقــام بســؤاله عنهــا وأنــه نفــس الشــخص‬\n‫الــذي حضــر إليــه مــن قبــل وقــام باســتالم البضاعــة منــه ومبواجهــة‬\n‫ا وأنكــر مشــاهدته‬      ‫املتهــم بذلــك أنكــر عالقتــه ب ــ‪ ....‬جملــة وتفصي ـ ً‬\n‫لــه مــن قبــل وأنكــر جميــع مــا ذكــره مــن أقــوال وأنكــر وجــود اتصــال‬\n‫بينهمــا‪ .‬وأفــاد صاحــب الســيارة (النقــل) ‪ .....‬علــى أن املتهــم‪ ....‬قــد‬\n‫حضــر إليــه وطلــب منــه نقــل كميــة مــن الفواكــه إلــى مدينــة اخلــرج‬\n‫ومت االتفــاق علــى ذلــك مقابــل مبلــغ ‪700‬ريــال ويف صبــاح ذلــك اليــوم‬\n‫اتصــل بــه وطلــب منــه احلضــور إليــه يف الســوق لتحميــل البضاعــة وبعــد‬\n‫حضــوره قــام مبقابلتــه يف الســوق وهــو واقــف بجانــب ســيارته مــن نــوع ‪...‬‬\n‫أبيــض اللــون وطلــب منــه االنتظــار لتحميــل البضاعــة ويف أثنــاء ذلــك مت‬\n‫القبــض عليــه وأضــاف أنــه كان وحــده‪ .‬وبعــرض املتهــم‪ ...‬علــى صاحــب‬\n‫ســيارة النقــل‪ .....‬أكــد أنــه نفــس الشــخص الــذي حضــر إليــه واتفــق معــه‬\n‫علــى نقــل كميــة مــن اخلضــار حملافظــة اخلــرج واتصــل عليــه يف صبــاح‬\n‫ذلــك اليــوم وطلــب منــه احلضــور للســوق وعنــد الوصــول إلــى الســوق قــام‬\n‫مبقابلتــه وطلــب منــه االنتظــار لتحميــل البضاعــة ومت القبــض عليــه‬\n‫بعــد ذلــك‪ .‬وبســماع أقــوال املدعــى عليــه األوليــة أفــاد أنــه مت القبــض‬\n‫عليــه إثــر حضــوره الســتالم بضاعــة حتتــوي علــى الكــرز والتــي كان‬\n‫بداخلهــا احلبــوب املنبهــة واحملظــورة وأفــاد أنــه كان يعلــم بوجــود احلبــوب‬\n‫املنبهــة واحملظــورة يف داخــل هــذه البضاعــة والتــي تعــود للمدعــو ‪.....‬‬\n‫والــذي يســكن يف محافظــة اخلــرج وقــد اتفــق معــه علــى ذلــك مقابــل‬\n‫مبلــغ مالــي قــدره (‪ )150.000‬مائــة وخمســون ألــف ريــال‪ .‬وباســتجوابه‬\n‫انكــر قيامــه بتلقــي احلبــوب املنبهــة واحملظــورة وأفــاد أنــه مت القبــض‬\n\n\n                                                                                     ‫‪236‬‬\n\f      ‫عليــه أثنــاء تواجــده يف ســوق اخلضــار والفواكــه بغــرض شــراء كميــة‬\n      ‫مــن اخلضــار ألخذهــا إلــى النعيريــة لوجــود مناســبة لهــم هنــاك وأنه كان‬\n      ‫لوحــده وأفــاد أن اجلــوال رقــم ‪ ....‬ال عالقــة لــه بــه وأضــاف أنــه ال عالقــة له‬\n      ‫باحلبــوب التــي مت ضبطهــا يف داخــل صناديــق فاكهــة الكــرز وأنكــر‬\n      ‫عالقتــه باملدعــو‪ ...‬وأنكــر مــا تضمنــه محضــر القبــض مــن االتصــال‬\n      ‫عليــه مــن قبــل املدعــو ‪ ...‬للحضــور الســتالم البضاعــة وحضــوره بعــد‬\n      ‫ذلــك إلــى الســوق والوقــوف مــع ‪ ...‬والســؤال عــن البضاعــة واالتفــاق مــع‬\n      ‫شــخص ســوداني اجلنســية علــى حتميــل البضاعــة إلــى محافظــة اخلــرج‬\n      ‫وأفــاد أنــه قــد حضــر غلــى الدمــام للتمشــية‪ .‬وقــد انتهــى التحقيــق إلــى‬\n      ‫اتهامــه بتلقــي مــا عــدده (‪ )211293‬مائتــان وأحــد عشــر ألــف حبــة مــن‬\n         ‫احلبــوب املنبهــة واحملظــورة (اإلمفيتامــن) مــن مهــرب بقصــد االجتــار‪.‬‬\n                                                        ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n      ‫‪ -1‬مــا ورد يف اقــوال املتهــم املنــوه عنهــا علــى اللفــة رقــم (‪28, 25-21‬‬\n      ‫ـ‪ )29‬وعلــى الصفحــة رقــم ( ‪ ) 3-2‬مــن ملــف التحقيــق املرفــق علــى اللفــة‬\n                                                                                        ‫رقم‪2‬‬\n      ‫‪ -2‬محضــر االنتقــال والقبــض والتفتيــش املنــوه عنــه علــى الصفحــة رقــم‬\n                                 ‫( ‪) 13-11‬مــن ملــف التحقيــق علــى اللفــة رقــم (‪)1‬‬\n      ‫‪ -3‬التقريــر الكيمــاوي الشــرعي املنــوه عنــه املرفــق علــى اللفــة رقــم‬\n                                                                                      ‫(‪. )40‬‬\n      ‫‪ -4‬إفــادات ‪ ..‬واملقيــم ‪ ..‬املنــوه عنهــا واملرفقــة علــى اللفــة رقــم (‪ 30‬ـ ‪)35‬‬\n                                                                               ‫و (‪)45, 44‬‬\n      ‫‪ -5‬محضــري العــرض واملواجهــة املنــوه عنهــا املرفقــة علــى اللــف رقــم‬\n                                                                                  ‫(‪. )46,27‬‬\n\n\n‫‪237‬‬\n\f                                 ‫‪ -6‬اقرار املتهم املنوه عنه على اللفة رقم (‪. )6‬‬\n‫‪ -7‬وجــود اتصــاالت هاتفيــه بــن اجلــوال رقــم ‪ ........‬العائــد للمتهم واجلوال‬\n                                           ‫رقم ‪ ..........‬العائد ملســتورد البضاعة ‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور ـ وهــو بكامــل أهليتــه املعتبــرة‬\n‫شــرعا فعــل محــرم ومعاقــب عليــه شــرع ًا ومجــرم نظام ـ ًا مبوجــب‬\n‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة يف عقوباتــه األصليــة‬\n‫والتكميليــة أطلــب إثبــات مــا أســند إليــه وفق ـ ًا للفقــرة (‪ )1‬مــن املــادة‬\n‫الثالثــة مــن نظــام املخــدرات واملؤثــرات العقليــة واحلكــم مبــا يلــي‪/1 :‬‬\n‫عقوبــة القتــل املنصــوص عليهــا يف الفقــرة رقــم (‪ )2‬مــن البنــد( اوالً)‬\n‫مــن املــادة (‪ )37‬مــن النظــام ‪ /2 .‬مصــادرة جوالــه الــذي يحمــل الرقــم‬\n‫املصنعــي رقــم (‪ ).........‬وفق ـ ًا للفقــرة (‪ )1‬مــن املــادة (‪ )53‬مــن النظــام‬\n‫وعــدم صــرف الشــريحة رقــم (‪ )..‬لنفــس املتهــم وفق ـ ًا لتعميــم وزيــر‬\n                      ‫الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1428/2/10-9‬ه ـ ‪.‬‬\n‫ـاء علــى الفقــرة (‪)1‬‬ ‫‪ /3‬مصــادرة الســيارة العائــدة للمتهــم املوصوفــة بنـ ً‬\n   ‫مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪.‬‬\n‫وبــاهلل التوفيق‪،،،‬هــذه دعــواي ‪ ،‬وكنــا قــد كتبنــا إلصالحيــة الدمــام‬\n‫إلحضــار املدعــى عليــه هــذا اليــوم االثنــن ‪1433/3/14‬ه ـ ولــم يحضــر‬\n‫ولذلــك أجلــت اجللســة الــى يــوم االثنــن ‪1433/3/21‬ه ـ وبــاهلل التوفيــق‪.‬‬\n‫ويف هــذا اليــوم االثنــن ‪1433/3/21‬ه ـ حضــر الطرفــان وباســتجواب‬\n‫املدعــى عليــه أجــاب بقولــه ‪ :‬ماذكــره املدعــي العــام يف دعــواه كلــه‬\n‫غيــر صحيــح ولــم يحصــل منــي شــيء مــن ذلــك وأنــا كنــت فيســوق‬\n‫اخلضــار يف الدمــام أشــتري أغــراض للكشــتة وكنــت علــى موعــد مــع‬\n‫أبنــاء عمــي يف ‪ .....‬فســألت أحدهــم عــن موقــع ســوق اخلضــار فدلنــي‬\n\n\n                                                                                       ‫‪238‬‬\n\f      ‫علــى ســوق الدمــام وقــد قبــض علـ ّـي فيــه وال أدري عــن ســبب القبــض‬\n      ‫علــي ‪ .‬هكــذا أجــاب وبعــرض ذلــك علــى املدعــي العــام قــال‪ :‬الصحيــح‬\n      ‫مــا ذكرتــه ولــدي البينــة مــا يف أوراق املعاملــة وأطلــب الرجــوع إليهــا ‪.‬‬\n      ‫ورفعــت اجللســة لذلــك إلــى يــوم االثنــن ‪1433/3/28‬هـ الســاعة العاشــرة‬\n                                                              ‫والنصــف واهلل املوفــق‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ويف هــذا اليــوم االثنــن املوافق‪1433/04/05‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪10 : 20‬وفيهــا حضــر الطرفــان وقــد جــرى‬\n      ‫الرجــوع للمعاملــة فوجدنــا علــى اللفــة رقــم ‪ 1‬ص ‪11‬و‪ 12‬واقعــة القبــض‬\n      ‫والضبــط والتفتيــش وتتضمــن مــا يلــي ‪ :‬احلمــد هلل رب العاملــن والصــاة‬\n      ‫والســام علــى أشــرف األنبيــاء واملرســلني أمــا بعــد نثبــت نحــن املوقعــن‬\n      ‫ـاء علــى املعلومــات الــواردة لنــا مــن وحــدة مكافحــة املخــدرات‬  ‫أدنــاه وبنـ ً‬\n      ‫مبطــار امللــك فهــد بالدمــام املبنــي علــى بــاغ جمــرك املطــار بشــأن ضبط‬\n      ‫كميــة مــن احلبــوب احملظــورة بيضــاء اللــون يشــتبه أن تكــون مــن‬\n      ‫حبــوب الكبتاجــون املخــدرة بلــغ إجماليهــا (‪ )211293‬مائتــن وإحــدى‬\n      ‫عشــر ألــف ومائتــن وثالثــة وتســعني حبــة والتــي كانــت مهربــة بداخــل‬\n      ‫صناديــق فاكهــة الكــرز وعليــه ويف متــام الســاعة الواحــدة ظهــرا مــن‬\n      ‫يــوم اجلمعــة ‪1432/7/22‬ه ـ مت اســتدعاء املخلــص اجلمركــي للبضاعــة‬\n      ‫املســتوردة والــذي يدعــى ‪................ /‬ومبناقشــته أفــاد بــأن البضاعــة‬\n      ‫الفواكــه هــي ملــك ألحــد التجــار املســتوردين يف ســوق اجلملــة للخضــار‬\n      ‫والفواكــه باســم يدعــى ‪................ /‬أثنــاء ذلــك مت االتصــال علــى‬\n      ‫صاحــب البضاعــة والطلــب منــه احلضــور إلــى وحــدة املكافحــة باملطــار‬\n      ‫وبالفعــل حضــر شــخصيا وقــد طلــب منــه التفاصيــل عــن ســير البضاعــة‬\n      ‫فقــد أفــاد بأنــه دائمــا مــا يقــوم بعمليــة االســتيراد للفواكــه وقــد اتصــل‬\n\n\n‫‪239‬‬\n\f‫بــه شــخص ‪....‬يدعــى ‪................ /‬وهــو أحــد جتــار الفاكهــة يف ‪ .....‬ولــي‬\n‫تعامــل مســبق معــه وآخرهــا اجلمعــة الفائتــة علــى نفــس البضاعــة نوعيــة‬\n‫كــرز واســتلمتها ووضعتهــا لــدي باملكتــب بالثالجــات حتــى حضــر‬\n‫شــخصان ســعوديان علــى ســيارة ‪ ....‬وأخذوهــا وذهبــوا بهــا ولــي عمولــة‬\n       ‫علــى ذلــك وأنــا مســتعد بالتعــاون معكــم بــكل شــيء عــن ذلــك ‪.‬‬\n‫وأننــي ســوف أقــوم بإحضارهــا إلــى مدينــة ‪ ....‬مقابــل مبلــغ وقــدره مائــة‬\n‫وخمســن ألــف ريــال فقــط وانــه قــد قــام بالتغريــر بــي ألجــل املــادة واجــل‬\n‫حاجتــي املاســة بهــا وانــه املدعــو‪ .............‬وهــو مــن قــام بالتخطيــط علــى‬\n‫تهريبهــا والــرأس املدبــر لهــا علــى هــذا أقــر علــى مــا أقولــه وقــد أذنــت‬\n‫ملــن يشــهد بذلــك ‪ .‬الشــاهد األول ‪................‬توقيعــه الشــاهد الثانــي‬\n‫‪................‬توقيعــه املقــر مبــا فيــه ‪................‬بصمتــه ‪ .‬كمــا وجدنــا علــى‬\n‫اللفــة رقــم ‪ 2‬ص ‪ 2‬مــن ملــف التحقيــق جــواب املدعى عليــه أثناء التحقيق‬\n‫معــه ‪ :‬س ‪ /‬ملــاذا مت القبــض عليــك ‪ .‬ج ‪ /‬عنــد حضــوري الســتالم فاكهــة‬\n‫الكــرز الــواردة مــن دولــة ‪ ....‬عــن طريــق املطــار ‪ .‬س ‪ /‬مــاذا كان داخــل‬\n‫الكــرز ‪ .‬ج ‪ /‬كان بداخلهــا حبــوب أبيــض محظــورة ‪ .‬س ‪ /‬هــل كنــت‬\n‫تعلــم عــن تلــك احلبــوب ‪ .‬ج ‪ /‬نعــم ‪ .‬س ‪ /‬ملــن تعــود تلــك الكميــة ج ‪ /‬تعــود‬\n‫للمدعــو ‪................‬ويســكن ‪ .....‬س ‪ /‬كــم املبلــغ املتفــق عليــه بينــك‬\n‫وبينــه اليصــال تلــك الكميــة ‪ . .....‬ج ‪ /‬كان املبلــغ املتفــق عليــه مائــة‬\n‫وخمســن الــف ريــال كمــا وجدنــا علــى اللفــة رقــم ‪ 27‬تعــرف املدعــو‬\n‫‪ ................‬علــى املدعــى عليــه وأنــه هــو الشــخص نفســه الــذي اتصــل‬\n‫بــه بعــد إرســال رقمــه ‪................‬مــن الشــخص ‪ . ....‬كمــا وجدنــا علــى‬\n‫اللفــة رقــم ‪ 46‬محضــر تعــرف املدعــو ‪................‬علــي ‪ .....‬اجلنســية علــى‬\n‫املدعــى عليــه وأنــه هــو نفــس الشــخص الــذي حضــر إليــه واتفــق معــه‬\n\n\n                                                                                             ‫‪240‬‬\n\f      ‫علــى نقــل كميــة مــن اخلضــار حملافظــة ‪ . .....‬كمــا وجدنــا علــى اللفــة‬\n      ‫رقــم ‪ 40‬التقريــر الكيمــاوي الشــرعي رقــم ‪.........‬ويتضمــن ايجابيــة‬\n      ‫العينــة املضبوطــة ملــادة االمفيتامــن املنبــه احملظــور وبعــرض ذلــك علــى‬\n      ‫املدعــى عليــه قــال ‪ :‬كل مــا جــاء فيمــا ذكــر غيــر صحيــح وأطلــب‬\n      ‫تزويــدي بنســخة ممــا ضبــط للــرد عليــه تفصيليــا ورفعــت اجللســة لذلــك‬\n      ‫بعــد اعــام الطرفــن باحلضــور يــوم االثنــن ‪1433/4/12‬ه ـ الســاعة‬\n      ‫العاشــرة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/04/05‬ه ـ احلمــد هلل وحــده ويف هــذا‬\n      ‫اليــوم االثنــن املوافــق‪ 1433/04/12‬ه ـ افتتحــت اجللســة الســاعة ‪: 32‬‬\n      ‫‪11‬وفيهــا حضــر الطرفــان وأحضــر املدعــي العــام للشــهادة كال مــن ‪... :‬‬\n      ‫‪ .............................‬وبســؤالهما عما لديهما من شــهادة شــهد كل واحد‬\n      ‫منهمــا علــى حــده بقولــه ‪:‬إنــه جاءتنــا مــن وحــدة مكافحــة املخــدرات‬\n      ‫مبطــار امللــك فهــد بالدمــام املبنــي علــى بــاغ جمــرك املطــار بشــأن‬\n      ‫ضبــط كميــة مــن احلبــوب احملظــورة بيضــاء اللــون يشــتبه أن تكــون مــن‬\n      ‫حبــوب الكبتاجــون املخــدرة بلــغ إجماليهــا ( ‪ ) 211293‬مائتــن وإحــدى‬\n      ‫عشــر ألــف ومائتــن وثالثــة وتســعني حبــة والتــي كانــت مهربــة بداخــل‬\n      ‫صناديــق فاكهــة الكــرز وعليــه ويف متــام الســاعة الواحــدة ظهــرا مــن‬\n      ‫يــوم اجلمعــة ‪1432/7/22‬ه ـ مت اســتدعاء املخلــص اجلمركــي للبضاعــة‬\n      ‫املســتوردة والــذي يدعــى ‪ ................ /‬ومبناقشــته أفــاد بــأن البضاعــة‬\n      ‫الفواكــه هــي ملــك ألحــد التجــار املســتوردين يف ســوق اجلملــة للخضــار‬\n      ‫والفواكــه باســم يدعــى ‪................ /‬أثنــاء ذلــك مت االتصــال علــى‬\n      ‫صاحــب البضاعــة وطلــب منــه احلضــور إلــى وحــدة املكافحــة باملطــار‬\n      ‫وبالفعــل حضــر شــخصيا وقــد طلــب منــه التفاصيــل عــن ســير البضاعــة‬\n\n\n‫‪241‬‬\n\f‫فقــد أفــاد بأنــه دائمــا مــا يقــوم بعمليــة االســتيراد للفواكــه وقــد اتصــل‬\n‫بــه شــخص ‪ ....‬يدعــى ‪................ /‬وهــو أحــد جتــار الفاكهــة يف ‪.....‬‬\n‫ولــه تعامــل مســبق معــه وآخرهــا اجلمعــة الفائتــة علــى نفــس البضاعــة‬\n‫نوعيــة كــرز واســتلمها ووضعهــا لديــه باملكتــب بالثالجــات حتــى‬\n‫حضــر شــخصان ســعوديان علــى ســيارة دينــا وأخذوهــا وذهبــوا بهــا ولــه‬\n‫عمولــة علــى ذلــك وأنــه مســتعد بالتعــاون معنــا بــكل شــيء عــن ذلــك‬\n‫‪.‬وبعــد أخــذ معطيــات القضيــة مت عمــل خطــة ميدانيــة ناجحــة ملعرفــة‬\n‫املخطــط لهــا واملســتقبل لهــذه الكميــة وأنــه يف متــام الســاعة الرابعــة‬\n‫عصــر ًا مت االنتقــال لســوق اخلضــار مبدينــة الدمــام واصطحــاب دينــا‬\n‫اخلضــار ووضعهــا بداخــل الســوق وصناديــق الكــرز ملعرفــة الشــخص‬\n‫الــذي يقــوم باســتالمها بعــد ذلــك وفــور وصولنــا إلــى الســوق مت متكــن‬\n‫املدعــو ‪ ................ /‬مــن االتصــال علــى ‪ ....‬الــذي يدعــى ‪................ /‬‬\n‫علــى رقــم ال نذكــره اآلن فقــد أفــاد بــأن البضاعــة وصلــت وقــام بســؤاله‬\n‫مــن الــذي ســيقوم باســتالمها فأفــاد بــأن الشــخص الــذي سيســتلمها‬\n‫شــخص يدعــى ‪................‬يحمــل هاتــف جــوال مســجل رقمــه يف احملضــر‬\n‫وأنــه ســوف يحضــر لــك يف اليــوم التالــي الصبــاح الباكــر انتهــت‬\n‫مت التمركــز جيــدا يف املوقــع بســوق اخلضــار حتــى‬     ‫املكاملــة عنــد ذلــك ّ‬\n‫اليــوم التالــي الســبت ويف حوالــي الســاعة السادســة صباحــا مت متكــن‬\n‫املدعــو ‪................ /‬مــن االتصــال علــى املدعــو ‪................ /‬علــى هاتفــه‬\n‫وطلــب منــه احلضــور الســتالم البضاعــة فأفــاده بأنــه ســوف يحضــر بعــد‬\n‫قليــل انتهــت املكاملــة وكانــت علــى مســمع مــن قائــد الفرقــة والرقيــب‬\n‫‪................‬وبعــد نصــف ســاعة تقريبــا حضــرت ســيارة مــن نــوع ‪ ....‬اللــون‬\n‫‪ ....‬حتمــل لوحــة مذكــورة يف احملضــر تعــود ملكيتهــا ‪................‬موديــل‬\n\n\n                                                                                           ‫‪242‬‬\n\f      ‫‪ .....‬وتــدور حولــه الشــكوك ووقفــت قريبـ ًا من املوقع وترجل من ســيارته‬\n      ‫ومتــت مراقبتــه حتــى وصــل إلــى املدعــو ‪ :................‬البضاعــة جاهــزة‬\n      ‫وأفــاده بأنهــا جاهــزة وقــال لــه أحضــر ســيارتك هنــاك ليقــوم بتحميلهــا‬\n      ‫العمــال وانتظرنــا عنــد ذلــك شــوهد علــى الشــخص عالمــات االرتبــاك‬\n      ‫الشــديد مــن احلــذر وكثــرة االلتفــات مينــة ويســرة وكان قــد شــاهد قائد‬\n      ‫الفرقــة ويحتمــل أنــه شــاهد الكميــة وعليهــا آثــار عالمــات التفتيــش‬\n      ‫بعــد ذلــك رجــع حتــى وصــل إلــى ســيارته مــرة أخــرى ووقــف قريب ـ ًا مــن‬\n      ‫بــاب الســائق وحضــر شــخص ســوداني واحتــك بــه وكانــا يتفقــان علــى‬\n      ‫نقــل البضاعــة إلــى مدينــة ‪ ....‬عندهــا وخوفــا مــن أن الشــخص كان‬\n      ‫يريــد أن يقــوم ســائق الدينــا املســتأجر بتحميــل البضاعــة وأنــه يقــوم هــو‬\n      ‫مبتابعتهــا ومراقبتهــا مــن بعيــد وخوفــا أيضــا مــن أنــه شــاهد البضاعــة‬\n      ‫وعليهــا عالمــات التفتيــش فقــد متــت مداهمتــه والقبــض عليــه واتضــح‬\n      ‫أنــه يدعــى ‪................‬ســعودي اجلنســية وبتفتيشــه شــخصيا لــم يعثــر علــى‬\n      ‫شــيء مــن املمنوعــات وبأخــذه خــارج املوقــع ملناقشــته وقــد مت اخلــروج مــن‬\n      ‫الســوق وأثنــاء الطريــق متــت مناقشــته عمــا حصــل بالتفصيــل وإفهامــه‬\n      ‫بــان مبــدأ الــكالم الصــدق هــو يثمــر يف حجــر القضيــة عنــد ذلــك قــام‬\n      ‫ا ‪:‬بأنــه قبــل يومــن‬    ‫باملراوغــة يف بــادئ األمــر وبعــد اإلحلــاح أفــاد قائ ـ ً‬\n      ‫مــن اآلن تقريبــا قابلنــي شــخص يف محافظــة‪ ....‬يدعــى ‪................‬وقــال‬\n      ‫لــي فيــه حجــر ابيــض جــاي مــن ‪ .....‬وهــو يقصــد حبــوب مخــدرة وتقــدر‬\n      ‫كميتهــا بألــف شــد وقــد أغرانــي باملــال وأنه إذا قمت بإحضارها ســوف‬\n      ‫يعطينــي مقابــل ذلــك مائــة وخمســن ألــف ريــال وانــه لــوال حاجتــي املاديــة‬\n      ‫ملــا أقدمــت علــى هــذا األمــر وبعدهــا نتقابــل يف ‪ .....‬وأقــوم بتســليمها لــه‬\n      ‫هنــاك وكان ذلــك علــى مســمع مــن قائــد الفرقــة مــع الرقيــب ‪................‬‬\n\n\n‫‪243‬‬\n\f‫وقــد اخــذ عليــه إقــرار بذلــك عنــد ذلــك مت متكينــه مــن االتصــال علــى‬\n‫املدعــو ‪ ................‬علــى هاتفــه وأفــاده بــأن كل شــيء متــام وأن الوضــع‬\n‫ميشــي علــى مــا يــرام إال أن الشــخص املدعــو ‪................ /‬كان يتضــح‬\n‫مــن كالمــه القلــق وكان يتصــل كل دقيقــة حملاولة كشــف الشــخص‬\n‫وهــي عالمــة دائمــا يف عمليــات التهريــب واالســتقبال عندهــا قــام بإقفال‬\n‫مت تفتيــش‬  ‫جوالــه ولــم نتمكــن مــن مواصلــة ســير القضيــة علمــا بأنــه ّ‬\n‫الســيارة ولــم يعثــر علــى شــيء مــن املمنوعــات عنــد ذلــك مت اصطحابــه‬\n‫إلــى إدارة املكافحــة بالدمــام إلكمــال الــازم بهــذا نشــهد وعليــه نوقــع‬\n‫هكــذا ‪.‬ا‪.‬هــ‪ .‬هكــذا شــهدا ‪ .‬وبعــرض ذلــك علــى املدعــى عليــه قــال ‪:‬‬\n‫مــا ذكــره الشــهود يف شــهادتهم مــن أنهــم قبضــوا علــي يف ســوق اخلضــار‬\n‫فهــذا صحيــح وأمــا مــا ذكــروه يف باقــي شــهادتهم فهــو غيــر صحيــح‬\n‫وأنــا جئــت إلــى الســوق الشــتري خضــار حيــث أنــي ســأخرج إلــى البــر‬\n‫مــع أبنــاء عمــي ولــم آتــي الســتالم البضاعــة التــي ذكروهــا وال أدري‬\n‫عمــا ذكــروه كلــه ‪ .‬وبســؤاله هــل يطعــن يف الشــهود بشــيء قــال ‪ :‬إننــي‬\n‫ال أعرفهــم ‪ .‬وعنــد وصــول القضيــة لهــذا احلــد جــرى رفعهــا إلــى االثنــن‬\n‫القــادم ‪1433/4/19‬ه ـ واهلل املوفــق‪ .‬ويف جلســة أخــرى يــوم االثنــن‬\n‫املوافــق‪ 1433/04/19‬ه ـ حضــر الطرفــان وقــرر املدعــى عليــه أنــه أقــام‬\n‫محامي ـ ًا للدفــاع عنــه ولــم يســتطع احلضــور اليــوم ويطلــب رفــع اجللســة‬\n‫ليتمكــن احملامــي مــن احلضــور ورفعــت اجللســة لذلــك‪ .‬ويف جلســة‬\n‫أخــرى يــوم األربعــاء املوافــق‪ 1433/04/21‬ه ـ حضــر كل مــن ‪........... /‬‬\n‫ســعودي بالســجل رقــم ‪ ........‬و ‪ .........‬ســعودي بالســجل رقــم ‪.........‬‬\n‫وباستشــهادهما شــهدا بعدالــة وثقــة الشــاهدين وأنهمــا صادقــان مقبــوال‬\n‫الشــهادة‪ .‬ويف هــذا اليــوم االثنــن ‪1433/4/26‬ه ـ افتتحــت اجللســة وفيهــا‬\n\n\n                                                                                     ‫‪244‬‬\n\f      ‫حضــر الطرفــان وحضــر وكيــل املدعــى عليــه ‪ .......‬ســعودي اجلنســية‬\n      ‫ا عــن املدعــى عليــه بالوكالــة رقــم ‪.........‬‬ ‫بالبطاقــة رقــم ‪ ..........‬وكي ـ ً‬\n      ‫وتاريــخ ‪1432/10/21‬ه ـ وقــدم مذكــرة دفــاع مكونــة مــن خمــس‬\n      ‫ورقــات ولكــون فضيلــة الشــيخ ‪ .......‬يتمتــع بإجــازة اعتياديــة فقــد جــرى‬\n                                          ‫رفــع اجللســة حلــن مباشــرته وعليــه أجلــت‪.‬‬\n      ‫ويف جلســة أخــرى حضــر الطرفــان وقــد جــرى الرجــوع إلــى املعاملــة‬\n      ‫فوجدنــا علــى اللفــة رقــم ‪ 48‬صــورة مــن شــهادة تصديــر مركبــة صــادرة‬\n      ‫من إدارة املرور بدولة ‪ ....‬وتتضمن أن السيارة ‪ .....‬موديل ‪ ....‬رقم اللوحة‬\n      ‫‪ .......‬تعــود ملكيتهــا ‪ .......‬كمــا وجدنــا علــى اللفــة رقم ‪ 19‬أنه ال ســوابق‬\n      ‫للمدعــى عليــه وبعــرض مــا جــاء يف اقــرار املدعــى عليــه علــى اللفــة رقــم ‪6‬‬\n      ‫قــال ‪ :‬إنهــم غرونــي وقالــوا هــذه إجــراءات توقيفــك عندنــا ‪ .‬فبنــاء علــى‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة وإلنــكار املدعــى عليــه ملــا جــاء يف دعوى‬\n      ‫املدعــي العــام وبنــاء علــى شــهادة الشــاهدين املعدلــن شــرعا املذكــورة‬\n      ‫بعاليــه وبنــاء علــى إقــرار املدعــى عليــه املــدون مضمونــه بعاليــه والــذي‬\n      ‫دفــع املدعــى عليــه بأنــه غــرر بــه فيــه ولــم يقــم بينــة علــى ذلــك وبنــاء‬\n      ‫علــى التقريــر الكيمــاوي املذكــور بعاليــه وبنــاء علــى املــادة التاســعة‬\n      ‫واخلمســن الفقــرة (‪ )1‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقلية‬\n      ‫وبنــاء علــى املــادة (‪ )38‬و (‪ )60‬مــن النظــام نفســه وألن جرميــة املدعــى‬\n      ‫عليــه تتعلــق باملخــدرات التــي تفســد العقــول واألديــان وقــد عــم ضررهــا‬\n      ‫وانتشــر يف كثيــر مــن البلــدان ودمــرت كثيــرا مــن الشــباب والناشــئة‬\n      ‫وقــد كثــر يف اآلونــة األخيــرة ترويجهــا وبيعهــا واســتخدامها والتغريــر‬\n      ‫بهــا ممــا يســتدعي تشــديد العقوبــة علــى مــن تلبــس بهــا أو شــارك يف أي‬\n      ‫مجــال يســبب نشــرها وبثهــا بــن النــاس أشــد التعزيــر وأليــم العقوبــة‬\n\n\n‫‪245‬‬\n\f‫فبنــاء علــى كل مــا تقــدم فقــد قررنــا باإلجمــاع مــا يلــي‪ :‬أوال صرفنــا‬\n‫النظــر عــن دعــوى املدعــي العــام وعــن مطالبتــه بتطبيــق املــادة ‪ 37‬رقــم ‪2‬‬\n‫مــن البنــد أو ًال مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وعــن‬\n‫مطالبتــه بتطبيــق الفقــرة(‪ )1‬مــن املــادة (‪ )53‬مــن النظــام نفســه ‪ .‬ثانيــا‬\n‫‪ :‬ثبــت لدينــا إدانــة املدعــى عليــه بالشــروع يف التوســط أو الشــروع يف‬\n‫نقــل املــواد احملظــورة وقررنــا تعزيــره علــى ذلــك بالســجن عشــر ســنوات‬\n‫تبــدأ مــن تاريــخ إيقافــه وجلــده ألــف جلــدة مفرقــة علــى عشــرين دفعــة‬\n‫كل دفعــة خمســون جلــدة بــن كل دفعــة وأخــرى عشــرة أيــام علــى‬\n‫أن تكــون الدفعــة األولــى واألخيــرة معلنــة أمــام جامــع ‪ .........‬بالدمــام‬\n‫كمــا قررنــا إلزامــه بدفــع غرامــة ماليــة قدرهــا خمســون ألــف ريــال‬\n‫تــودع يف بيــت مــال املســلمني كمــا قررنــا منعــه مــن الســفر خلــارج البــاد‬\n‫مــدة مماثلــة ملــدة ســجنه وبذلــك كلــه حكمنــا ‪ .‬وبعــرض ذلــك علــى‬\n‫الطرفــن قــررا عــدم قناعتهمــا باحلكــم وأفهمــا بتقــدمي اعتراضيهمــا‬\n‫خــال املــدة احملــددة بعــد اســتالمهما نســخة احلكــم وبــاهلل التوفيــق‪.‬‬\n                                                      ‫حــرر يف ‪1433/6/2‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق‪ 1434/03/10‬ه ـ‬\n‫افتتحــت اجللســة بنــاء علــى عــودة املعاملــة مــن محكمــة االســتئناف‬\n‫برقــم ‪ ..........‬يف ‪1433/12/27‬ه ـ املقيــدة باحملكمــة برقــم ‪.........‬‬\n‫يف ‪1434/1/4‬ه ـ وبرفقهــا قــرار أصحــاب الفضيلــة قضــاة الدائــرة‬\n‫اجلزائيــة اخلماســية األولــى رقــم ‪ ...........‬يف ‪1433/12/20‬ه ــاملتضمن‬\n‫مــا ملخصــه بعــد املقدمــة (وبدراســة القــرار وصــورة ضبطــه والالئحتــن‬\n‫االعتراضيتــن وأوراق املعاملــة لوحــظ أنــه ذكــر أصحــاب الفضيلــة يف‬\n‫حكمهــم مــا نصــه ثبــت لدينــا إدانــة املدعــى عليــه بالشــروع يف التوســط‬\n\n\n                                                                                     ‫‪246‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":231,"source_page_end":246,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ad3f1fbce58b020e58f030affc64366b789de93fe4b9439e4f3ca2d0360671ee","normalized_text_hash":"b93e18c61227bc71d2aed64877d76773bd69b8ac4363353af134dc3a99beae77","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p231-33297549"},{"id":"48dac714-904a-59f2-b2da-0f3f3ebc7694","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج عدد من احلبوب احملظورة -تعاطي احلبوب احملظورة -اإلقرار -عقوبة مشددة كون املتهم عسكري -التعزير بالسجن واجللد والغرامة واملنع من السفر واملصادرة وإعادة املبلغ","document_number":"347121","case_number":"3410623","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/01/10","year":"1434","subject":"مخدرات -ترويج عدد من احلبوب احملظورة -تعاطي احلبوب احملظورة -اإلقرار -عقوبة مشددة كون املتهم عسكري -التعزير بالسجن واجللد والغرامة واملنع من السفر واملصادرة وإعادة املبلغ","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 347121 :‬تاريخه ‪1433/01/10 :‬هـ‬\n                           ‫رقم الدعوى ‪3410623:‬‬\n                    ‫رقم قرار التصديق من محكمة‬\n        ‫االستئناف‪ 34174231:‬تاريخه‪1434/03/29:‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬ترويــج عــدد مــن احلبــوب احملظــورة ‪ -‬تعاطــي احلبــوب‬\n       ‫احملظــورة ‪ -‬اإلقــرار ‪ -‬عقوبــة مشــددة كــون املتهــم عســكري ‪ -‬التعزيــر‬\n       ‫بالســجن واجللــد والغرامــة واملنــع مــن الســفر واملصــادرة وإعــادة املبلــغ‬\n                                                                             ‫احلكومــي‪.‬‬\n\n\n\n\n                    ‫ض َب ْع َد ِإ ْص َل ِح َها } ‪.‬‬         ‫‪ -1‬قوله تعالى { َو َل ُت ْف ِس ُدوا ِف ْ َ‬\n                                                     ‫ال ْر ِ‬\n                                                              ‫‪ -2‬قوله تعالى { َو َال ُت ْل ُقو ْا ِب َأ ْيدِ ُ‬\n                              ‫يك ْم ِإ َلى ال َّتهْ ُل َك ِة } ‪.‬‬\n       ‫‪ -3‬املــواد (‪ )2/3‬و(‪)1/38‬و (‪)1/56‬و(‪ )1/53‬مــن نظــام مكافحــة املخدرات‬\n                                                                                           ‫واملؤثــرات العقلية ‪.‬‬\n\n\n\n       ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بترويــج عــدد مــن احلبــوب‬\n       ‫احملظــورة وتعاطــي احلبــوب املنبهــة احملظــورة ‪ ،‬وطلــب املدعــي العــام‬\n       ‫إثبــات مــا أســند للمدعــى عليــه واحلكــم عليــه بالســجن واجللــد والغرامــة‬\n       ‫واملنــع مــن الســفر ومصــادرة الهاتــف اجلــوال والغاء الشــريحة والزامه برد‬\n       ‫املبلــغ احلكومــي املرقــم تطبيق ـ ًا ألحــكام نظــام مكافحــة املخــدرات‬\n       ‫واملؤثــرات العقليــة ‪ -‬حيــث وردت معلومــات ملكافحــة املخــدرات مــن‬\n       ‫أحــد مصادرهــا الســرية عــن قيــام املدعــى عليه بترويــج احلبوب احملظورة‬\n\n‫‪249‬‬\n\f‫بكميــات كبيــرة ويرتبــط مبجموعــه مــن مروجــي املخــدرات ‪ ،‬وقــد‬\n‫عــرض املدعــى عليــه علــى املصــدر البحــث لــه عــن مشــتري لكميــات‬\n‫كبيــرة مــن احلبــوب احملظــورة ‪ ،‬ومت متكــن املصــدر مــن االتصــال علــى‬\n‫جــوال املدعــى عليــه وطلــب منــه كميــه كبيــرة مــن احلبــوب وأنهــا ألحــد‬\n‫األشــخاص فوافــق املدعــى عليــه ‪ ،‬وكانــت املكاملــة علــى مســمع مــن‬\n‫أفــراد الفرقــة القابضــة ومت تزويــد املصــدر باملبلــغ املرقــم بعــد تفتيشــه‬\n‫ورافقــه قائــد الفرقــة لتمثيــل دور املشــتري واتفقا علــى الكمية ‪ ،‬وطلب‬\n‫املدعــى عليــه أن يكــون االســتالم والتســليم يف يــوم الغــد ‪ ،‬ويف اليــوم‬\n‫احملــدد اتصــل املدعــى عليــه باملصــدر وأخبــره بأنــه متواجــد يف منزلــه‬\n‫وحضــر إليــه املصــدر يرافقــه قائــد الفرقــة (ممثــل دور املشــتري) فســلمه‬\n‫ســتمائة ريــال واســتلم مــن املدعــى عليــه عــدد (‪ )22‬حبــة مــن حبــوب‬\n‫اإلمفيتامــن ‪ ،‬وطلــب املدعــى عليــه مــن املصــدر ومرافقــه االتصــال بــه‬\n‫بعــد يومــن إلخبــاره إن كانــت احلبــوب التــي ســلمها جيــدة لتســليمهما‬\n‫باقــي الكميــة املتفــق عليهــا وجــرى االتصــال علــى املدعى عليــه فاعتذر‬\n‫مــن تســليم الكميــة لشــكه بالوضــع ‪ -‬مت مراقبــة منزلــه وبعــد يومــن‬\n‫تقابــل املدعــى عليــه مــع أحــد األشــخاص وركــب معــه واجتهــا للطريــق‬\n‫الســريع فتــم االســتعانة بالدوريــات األمنيــة الســتيقافهما ومت القبــض‬\n‫علــى املدعــى عليــه ‪ ،‬أقــر املدعــى عليــه بتعاطــي حبــوب اإلمفيتامــن‬\n‫وأنكــر مــا عــداه وصــدر احلكــم بإثبــات إدانــة املدعــى عليــه ببيــع (‪)22‬‬\n‫حبــة مــن حبــوب اإلمفيتامني بقصد االجتــار وتعاطيه لهذه احلبوب‪،‬وبناء‬\n‫علــى مــا تقــدم حكمــت احملكمــة بتعزيــره بالســجن واجللــد والغرامــة‬\n‫واملنــع مــن الســفر ومصــادرة الهاتــف اجلــوال وشــريحته وإلزامــه بإعــادة‬\n            ‫املبلــغ احلكومــي وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n                                                                                    ‫‪250‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫مبحافظــة القطيــف وبنــاء علــى املعاملــة احملالــة مــن فضيلــة الرئيــس‬\n      ‫برقــم ‪ ......‬وتاريــخ ‪1434/1/6‬ه ـ املقيــدة باحملكمــة برقــم ‪ ......‬وتاريــخ‬\n      ‫‪ 1434/1/6‬ه ـ واملتعلقــة بدعــوى املدعــي العــام ‪ ......‬ضــد‪ ،......‬حامــل‬\n      ‫الســجل املدنــي رقــم ( ‪ ) ......‬ففــي يــوم الســبت ‪1434/ 1 / 10‬ه ـ فتحــت‬\n      ‫اجللســة الســاعة ‪ 10 : 15‬وفيهــا حضــر املدعــي العــام واملدعــى عليــه‬\n      ‫املدونــة هويتــه بعاليــه وقــدم املدعــي العــام الئحــة الدعــوى املتضمنــة مــا‬\n      ‫يلــي ‪( :‬بصفتــي مدعيـ ًا عامــا يف دائــرة اإلدعــاء العــام مبحافظــة القطيــف‬\n      ‫أدعي على‪ ، ...... :‬البالغ من العمر (‪ )25‬ســنة س ــعودي اجلنســية مبوجب‬\n      ‫الســجل املدنــي رقــم (‪ )......‬محصــن ‪ ،‬عســكري ‪ ،‬أوقــف بتاريــخ‬\n      ‫‪1433/11/22‬ه ـ ‪ ،‬وأحيــل لســجن محافظــة القطيــف اســتناد ًا للقــرار‬\n      ‫الــوزاري رقــم (……) وتاريــخ ‪1428/7/9‬هــ‪ .‬حيــث انــه بتاريــخ‬\n      ‫‪1433/11/14‬ه ـ وردت معلومــات لرجــال مكافحــة املخــدرات بالدمــام‬\n      ‫مــن احــد مصادرهــم الســرية عــن قيــام املدعــى عليــه بترويــج احلبــوب‬\n      ‫احملظــورة بكميــات كبيــرة ويرتبــط مبجموعــة مــن مروجــي املخــدرات‬\n      ‫بالقطيــف ويعمــل ســائق زورق يف ‪ ،.........................‬وقــد عــرض املدعــى‬\n      ‫عليــه علــى املصــدر البحــث لــه عــن مشــتري لكميــات كبيــرة مــن‬\n      ‫احلبــوب احملظــورة يرغــب يف تصريفهــا ‪ ،‬فتــم متكــن املصــدر مــن‬\n      ‫االتصــال علــى جــوال املدعــى عليــه رقــم (‪ )......‬رقمــه املصنعــي (‪)......‬‬\n      ‫وطلــب منــه حبوب ـ ًا محظــورة فذكــر املدعــى عليــه ان لديــه كميــة مــن‬\n      ‫احلبــوب احملظــورة و يرغــب يف تصريفهــا ‪ ،‬فســأله املصــدر عــن قيمــة‬\n\n‫‪251‬‬\n\f‫الشــد وهــي مائتــي حبــة فأجابــه املدعــى عليــه بــأن قيمــة الشــد ثالثــة‬\n‫آالف ريــال وأنهــا موجــودة يف الوقــت احلالــي فطلــب املصدر شــراء خمســة‬\n‫وعشــرون شــد ًا واخبــره انهــا ألحــد األشــخاص ‪ ،‬فطلــب املدعــى عليــه‬\n‫مــن املصــدر ان يــزوده برقــم هاتــف املشــتري وإبالغــه باالتصــال عليــه او‬\n‫حضــور املصــدر واملشــتري ملنزلــه ‪ ،‬وكانــت املكاملــة علــى مســمع مــن‬\n‫أفــراد الفرقــة القابضــة ‪ -‬فجــرى ترقيــم مبلــغ وقــدره (‪ )2000‬الفــي‬\n‫ريــال و تفتيــش املصــدر تفتيشــا دقيقــا‪ ،‬وقيــام قائــد الفرقــة القابضــة‬\n‫مبرافقتــه لتمثيــل دور املشــتري ومت وتزويدهمــا باملبلــغ املرقــم ‪ ،‬وانتقــا‬\n‫إلــى منــزل املدعــى عليــه وقابــاه ودخــا منزلــه وأثنــاء احلديــث اتفــق‬\n‫قائــد الفرقــة القابضــة مــع املدعــى عليــه علــى الشــراء منــه خمســة‬\n‫وعشــرين شــد ًا فوافــق املدعــى عليــه وذكــر أن الكميــة عنــد احــد‬\n‫أعوانــه بالقطيــف وطلــب ان يكــون االســتالم والتســليم يــوم غــدٍ الثالثاء‬\n‫املوافــق ‪1433/11/16‬ه ـ ‪ ،‬ويف اليــوم احملــدد مت االتصــال عليــه فذكــر‬\n‫انــه عنــد احــد أعوانــه بالقطيــف ‪ ،‬وعنــد الســاعة الواحــدة اتصل املدعى‬\n‫عليــه باملصــدر واخبــره انــه متواجــد برحيمــه مبنزلــه وطلــب حضــور‬\n‫املشــتري لــه فجــرى تفتيــش املصــدر ومرافقــة قائــد الفرقــة القابضــة لــه‬\n‫وانتقــا حتــى وصــا منــزل املدعــى عليــه وبدخولهمــا املنــزل طلــب‬\n‫املدعــى عليــه منهمــا املبلــغ قبــل اســتالم الكميــة فرفــض ممثــل دور‬\n‫املشــتري تســليم املبلــغ قبــل مشــاهدة الكميــة فأجــرى املدعــى عليــه‬\n‫اتصــاال ثــم دخــل املدعــى عليــه داخــل منزلــه واحضــر عــدد (‪ )22‬اثنــن‬\n‫وعشــرين حبــة أثبــت التقريــر الكيمــاوي الشــرعي رقــم () وتاريــخ‬\n‫‪ 1433/11/30‬ه ـ ايجابيــة عينتهــا ملــادة االمفيتامــن املنبهــة احملظــورة ‪،‬‬\n‫وســلمها لقائــد الفرقــة القابضــة وجــرى تســليمه مبلــغ مرقــم وقــدره‬\n\n\n                                                                                  ‫‪252‬‬\n\f      ‫(‪ )600‬ســتمائة ريــال ‪ ،‬وطلــب مــن املصــدر و مرافقــه االتصــال بــه بعــد‬\n      ‫يومــن إلخبــاره ان كانــت احلبــوب التــي ســلمها جيــدة لتســليمهما باقــي‬\n      ‫الكميــة املتفــق عليهــا‪ .‬وبتاريــخ ‪1433/11/20‬ه ـ جــرى االتصــال علــى‬\n      ‫املدعــى عليــه فذكــر أنــه بعملــه وأنــه ســيتصل بــه يــوم غــد لتســليمه‬\n      ‫الكميــة املتفــق عليهــا‪ ،‬ويف اليــوم التالــي جــرى االتصــال عليــه اال انــه‬\n      ‫اعتــذر مــن تســليم الكميــة لشــكه بالوضــع فتــم مراقبــة منزلــه ‪ ،‬ويف‬\n      ‫يــوم االثنــن املوافــق ‪1433/11/22‬ه ـ تقابــل املدعــى عليــه مــع احــد‬\n      ‫األشــخاص وركــب معــه واجتهــا إلــى شــارع ‪ ......‬ثــم عــادا حلــي ‪ ......‬علــى‬\n      ‫طريــق ‪ ......‬فتــم االســتعانة بالدوريــات األمنيــة الســتيقافهما فتــم القبــض‬\n      ‫علــى املدعــى عليــه‪ .‬وباســتجواب املدعــى عليــه اقــر بصحــة واقعــة‬\n      ‫الضبــط‪ ،‬وافــاد انــه قبــل القبــض عليــه بعشــرة أيــام اتصــل بــه املصــدر‬\n      ‫وطلــب منــه حبوب ـ ًا منبهــة وأخبــره أنــه ال ميلكهــا وقــام بتكــرار طلبــه‬\n      ‫عــدة مــرات‪ ،‬وألنــه يطالــب املصــدر مببلــغ (‪)700‬ريــال كســلفة فطلــب‬\n      ‫منــه أن يحضــر إليــه مبنزلــه وعنــد حضــور املصدر كان برفقته شــخص‬\n      ‫أخــر وطلــب منــه حبوبـ ًا منبهــة وأصــر علــى طلبــه فأخبــره أنــه إذا عــرف‬\n      ‫أحــد ســيحضر منــه احلبــوب‪ ،‬وبعدهــا بيومــن حضــر املصــدر وبرفقتــه‬\n      ‫الشــخص وطلــب منــه احلبــوب فأخبرهمــا أنــه ال يوجــد لديــه ســوى مــا‬\n      ‫يســتخدمه فقــام وســلم مرافــق املصــدر عــدد (‪ )22‬حبــة مــن احلبــوب‬\n      ‫املنبهــة التــي يتعاطاهــا فقــام مرافــق املصــدر وأخــرج مبلــغ (‪ )600‬ريــال‬\n      ‫وســلمه إياهــا وقــام بإعادتهــا إليــه فأصــر مرافــق املصــدر علــى أن‬\n      ‫يأخذهــا فاســتلمها وغــادر املصــدر ومرافقــه املنــزل ‪ ،‬كما اقــر بتعاطي‬\n      ‫احلبــوب املنبهــة منــذ ســنة وأخــر مــرة كانــت قبــل القبــض عليــه بأســبوع‪.‬‬\n      ‫وقــد انتهــى التحقيــق معــه إلــى توجيــه االتهــام إليــه ببيــع مــا عــدده (‪)22‬‬\n\n\n‫‪253‬‬\n\f‫اثنــن وعشــرين حبــة مــن حبــوب االمفيتامــن املنبهــة احملظــورة بقصــد‬\n‫االجتــار وتعاطــي احلبــوب املنبهــة احملظــورة ‪ ،‬وذلــك لألدلــة والقرائــن‬\n‫التاليــة ‪ -1 :‬مــا ورد باســتجوابه املنــوه عنــه املرفــق علــى اللفــات رقم(‪-12‬‬\n‫‪ -2 . )14‬محاضــر البــاغ و االتصــال و االنتقــال و القبــض والتفتيــش‬\n‫املنــوه عنهــا املدونــة علــى الصفحــات رقــم (‪ )14-12 ، 4 ، 2‬مــن ملــف‬\n‫التحقيــق‪ -3 .‬التقريــر الكيمــاوي الشــرعي املنــوه عنــه املرفــق علــى‬\n‫اللفــة رقــم(‪ .)15‬وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى أي‬\n‫ســوابق‪ .‬وحيــث إن مــا أقــدم عليــه املذكــور ‪ ،‬وهــو بكامــل أهليتــه‬\n‫املعتبــرة شــرع ًا ‪ ،‬فعــل محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا لــذا أطلــب‬\n‫إثبــات مــا أســند اليــه وفــق الفقــرة رقــم(‪ )2‬مــن املــادة رقــم(‪ )3‬مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم عليــه مبــا يلــي‪:‬‬\n‫‪-1‬بعقوبــة الســجن واجللــد والغرامــة الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة‬\n‫رقــم(‪ )38‬مــن النظــام‪ ،‬والتشــديد عليــه كــون املــادة املروجــة حبــوب‬\n‫منبهــة وفــق الفقــرة (‪/2‬ج) مــن املــادة رقــم(‪ )38‬مــن النظــام‪ ،‬و اســتنادا‬\n‫لبرقيــة صاحــب الســمو امللكــي وزيــر الداخليــة رقــم(‪2/8346/5/1‬ش)‬\n‫وتاريــخ ‪1427/2/8‬ه ـ ‪ ،‬و كونــه عســكري اســتناد ًا إلــى برقيتــي‬\n‫صاحــب الســمو امللكــي وزيــر الداخليــة رقم……………‪.‬وتاريــخ‬\n‫‪1429/11/4‬هـ‪ ،‬ورقم ……………‪ .‬وتاريخ ‪1429/2/15‬هـ‪-2 .‬منعه‬\n‫مــن الســفر وفــق الفقــرة رقــم(‪ )1‬مــن املــادة رقــم(‪ )56‬مــن النظــام‪.‬‬\n‫‪-3‬مصــادرة هاتفــه النقــال املســتخدم يف عمليــة الترويــج وفــق الفقــرة (‪)2‬‬\n‫مــن املــادة رقــم (‪ )53‬مــن النظــام ‪ ،‬وعــدم صرف الشــريحة لنفس املدعى‬\n‫عليــه وفق ـ ًا لتعميــم وزيــر الداخليــة رقــم (……………‪ ).‬وتاريــخ‬\n‫‪1428/2/10-9‬هــ‪-4 .‬إلزامــه بدفــع املبلــغ املرقــم الــذي لــم يتــم العثــور‬\n\n\n                                                                                        ‫‪254‬‬\n\f      ‫عليــه وفــق تعميــم وزيــر الداخليــة رقــم (……………‪ ).‬وتاريــخ ‪-22‬‬\n      ‫‪1428/10/23‬هــ‪ .‬وبــاهلل التوفيــق) ا‪ .‬ه ـ وبعــرض الدعــوى علــى املدعــى‬\n      ‫عليــه أجــاب بقولــه مــا جــاء يف الدعــوى مــن اتهامــي بتعاطــي حبــوب‬\n      ‫االمفيتامــن فهــو صحيــح ومــا عــداه فكلــه غيــر صحيــح هــذا جوابــي‬\n      ‫وبعــرض ذلــك علــى املدعــي العــام قــال الصحيــح مــا جــاء يف دعــواي‬\n      ‫وبســؤاله البينــة قــال بينتــي ذكرتهــا يف الدعــوى وأطلــب رصدهــا هــذا‬\n      ‫جوابــي وباالطــاع علــى أدلــة املدعــي العــام وجــدت علــى اللفــات ‪14-12‬‬\n      ‫اســتجوابا للمدعــى عليــه يتضمــن مــا نصــه ‪( :‬س‪ .‬اشــرح لنــا بالتفصيــل‬\n      ‫كيــف مت القبــض عليــك ؟ ج‪ .‬قبــل القبــض علــي بعشــرة أيــام اتصــل بــي‬\n      ‫املصــدر وطلــب منــي حبوبــا منبهــة وأخبرتــه بأنــي ال أملكهــا وقــام‬\n      ‫بتكــرار طلبــه عــدة مــرات‪ ،‬وألنــي أطالــب املصــدر مببلــغ (‪ )700‬ريــال‬\n      ‫كســلفة فطلبــت منــه أن يحضــر إلــى املنــزل وعنــد حضــوره إلــى املنــزل‬\n      ‫كان برفقتــه شــخص آخــر وطلــب منــي حبوبــا منبهــة وأصــر علــى طلبــه‬\n      ‫وأخبرتــه أنــه إذا عرفــت أحــدا ســأحضر منــه احلبوب‪،‬وبعدهــا بيومــن‬\n      ‫حضــر وبرفقتــه الشــخص وطلــب منــي احلبــوب فأخبرتــه أنــه ال يوجــد‬\n      ‫لــدي ســوى مــا أســتخدمه فقمــت وســلمته عــدد اثنــن وعشــرين حبــة مــن‬\n      ‫احلبــوب املنبهــة التــي أتعاطاهــا فقــام مرافــق املصــدر وأخــرج مبلــغ‬\n      ‫ســتمائة ريــال وســلمني إياهــا وقمــت بإعادتهــا إليــه وقــام وأصــر علــي أن‬\n      ‫آخذهــا فاســتلمتها وغــادر املصــدر ومرافقــه املنــزل وبعدهــا بأســبوع‬\n      ‫مــررت بزميــل لــي يف العمــل ليرافقنــي إلــى املعــارض لبيــع كفــرات‬\n      ‫مســتخدمة فتــم اســتيقايف مــن قبــل رجــال مكافحــة املخــدرات ودوريات‬\n      ‫أمنيــة فتــم القبــض علـ ّـي ‪ .‬س ‪ .‬مــا هدفــك مــن بيــع احلبــوب املنبهــة ؟ ج ‪.‬‬\n      ‫ألن املصــدر أصــر علــي أن احضــر لــه حبــوب فقمــت بإعطائــه مــا معــي‬\n\n\n‫‪255‬‬\n\f‫مــن حبــوب ‪ .‬س ‪ .‬ملــاذا اســتلمت املبلــغ مــن املصــدر ومرافقــه ؟ ج ‪ .‬ألن‬\n‫مرافــق املصــدر أصــر علــى أن اســتلم املبلــغ ‪ .‬س ‪ .‬ورد يف محضــر القبــض‬\n‫أنــك اتفقــت مــع املصــدر علــى أن تبيعــه خمســة وعشــرين شــد ًا مــن‬\n‫احلبــوب املنبهــة فمــا قولــك ؟ ج ‪ .‬نعــم صحيــح اتفقــت معــه علــى ذلــك‬\n‫بســبب أنــي أطالــب املصــدر مببلــغ مــن املــال وكلمــا اتصلــت بــه ال يــرد ‪،‬‬\n‫وعندمــا كلمنــي فرحــت باتصالــه وعندمــا طلــب منــي شــدا أجبتــه بأنــي‬\n‫ســأحضر إليــه الشـ ّـد أريــده أن يحضــر إلــى املنــزل ألتفاهــم معــه بشــأن‬\n‫الديــن ولكنــي ال أملــك هــذه الكميــة مــن احلبــوب‪ .‬س ‪ .‬ذكــرت‬\n‫للمصــدر ومرافقــه أنــك تعــرف أحــد األشــخاص بالقطيــف ســتحصل‬\n‫منــه علــى كميــة احلبــوب فمــا قولــك ومــن هــو هــذا الشــخص؟ ج ‪.‬‬\n‫ذكــرت ذلــك ألطمئــن املصــدر ولكنــي ال أعــرف أحــدا ) ا‪.‬ه ـ كمــا‬\n‫وجــدت علــى اللفــة رقــم ‪ 15‬التقريــر الكيمــاوي رقــم ك ش املتضمــن ‪:‬‬\n‫( إيجابيــة العينــة ملــادة االمفيتامــن) ا‪.‬ه ـ وبعــرض األدلــة علــى املدعــى‬\n‫عليــه قــال االســتجواب املرصــود بعاليــه صحيــح وال أنكــر شــيئا منــه‬\n‫هــذا جوابــي فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر‬\n‫املدعــى عليــه مبــا نســب لــه يف االســتجواب وهــو يتضمــن إقــرارا منــه‬\n‫بالترويــج مبقابــل وبنــاء علــى إقــراره يف مجلــس احلكــم بالتعاطي ولقوله‬\n‫تعالــى ‪ ( :‬وال تفســدوا يف األرض بعــد إصالحهــا ) وقولــه ‪ ( :‬وال تلقــوا‬\n‫بأيديكــم إلــى التهلكــة ) وبنــاء علــى املــواد ‪ 2/3‬و ‪ 1/38‬و ‪ 1/56‬و‬\n‫‪ 1/53‬مــن نظــام مكافحــة املخــدرات فقــد حكمــت مبــا يلــي ‪-1 :‬ثبــوت‬\n‫إدانــة املدعــى عليــه ببيــع اثنــن وعشــرين حبــة مــن حبــوب االمفيتامــن‬\n‫املنبهــة احملظــورة بقصــد االجتــار وتعاطــي احلبــوب املنبهــة احملظــورة ‪-2‬‬\n‫معاقبــة املدعــى عليــه للتعاطــي بجلــده ســبعني جلــدة دفعــة واحــدة‬\n\n\n                                                                                     ‫‪256‬‬\n\f      ‫‪-3‬معاقبتــه علــى بيــع املــواد املخــدرة بســجنه مــدة خمــس ســنوات وجلــده‬\n      ‫خمســن جلــدة تتكــرر عليــه عشــر مــرات بــن كل إيقــاع وآخــر خمســة‬\n      ‫عشــر يومــا وتغرميــه خمســة آالف ريــال ومنعــه مــن الســفر بعــد خروجــه‬\n      ‫مــن الســجن مــدة خمــس ســنوات ومصــادرة هاتفــه اجلــوال وعــدم صــرف‬\n      ‫نفــس الشــريحة للمدعــى عليــه ‪ -4‬إلزامــه بتســليم املبلــغ احلكومــي‬\n      ‫وقــدره ســتمائة ريــال وبعــرض احلكــم علــى الطرفــن قنــع بــه املدعــي‬\n      ‫العــام وقــرر املدعــى عليــه عــدم قناعتــه ورغبتــه تقــدمي الئحــة اعتراضيــة‬\n      ‫فجــرى إفهامــه بتعليمــات االســتئناف ففهمهــا كمــا أفهمتــه بــأال‬\n      ‫ينصــرف حتــى يتســلم صــورة مــن احلكــم وبــاهلل التوفيــق وقــد مت االنتهاء‬\n          ‫من حتريره يف متام الساعة ‪ 11 : 00‬من يوم السبت ‪1434/ 1 / 10‬هـ‬\n      ‫احلمد هلل وحده وبعد ففي يوم الثالثاء ‪1434/ 4 / 16‬هـ فتحت اجللسة‬\n      ‫الســاعة ‪ 8 : 00‬وقــد وردتنــا املعاملــة وبرفقهــا قــرار أصحــاب الفضيلــة‬\n      ‫قضــاة محكمــة االســتئناف باملنطقــة الشــرقية رقــم ‪ 34174231‬يف‬\n      ‫‪1434/3/29‬ه ـ املتضمــن املصادقــة علــى احلكــم وبــاهلل التوفيــق وقــد‬\n                                ‫مت االنتهــاء مــن حتريــره يف متــام الســاعة ‪. 8 : 10‬‬\n\n\n\n\n‫‪257‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":249,"source_page_end":257,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3c950e843de7c881b3025da7366152647cab41a6dd02dd97206137298e22a274","normalized_text_hash":"30ef54a676afe08b6b28a5989f84ecac56739d3ed9647b2d6472a49df712a1e8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p249-347121"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
